// Файл згенеровано scripts/build_kz_akafisty.py. Абзац з префіксом § — рубрика, з префіксом # — підзаголовок.
import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст преподобному Онуфрію Великому","e":"Akathist to our Venerable Father Onuphrius the Great","secs":[{"h":"Кондак 1","ps":["Ізбра́нний і ди́вний о́тче Ону́фріє, сія́ющий трисія́ннаго живота́ заре́ю, ти м'я, омраче́ннаго гріхо́вними страстьми́, просвіти́, от смертоно́сния ра́ни ісхити́ і твої́ми моли́твами от всіх бід ізба́ви, да зову́ тебі́: Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Ікос 1","ps":["А́нгельстії чи́ни твої́м, о́тче, удиви́шася по́двигом, і́миже в пусти́ні непреста́нно упражня́лся єси́; три бо і шестьдеся́т літ пости́лся єси́, Боже́ственния же Христо́ви Та́йни от рук а́нгельських прийма́ти сподо́бился єси́, і ни́ні у́бо почита́я тя єдиновсе́льника і собесі́дника А́нгелов, сицева́я вопію́ тебі́, свя́те Ону́фріє:","Ра́дуйся, А́нгелов преди́вноє чу́до;","ра́дуйся, душетлі́нних страсте́й разруши́телю.","Ра́дуйся, непроходи́мия пусти́ні просвіти́телю;","ра́дуйся, воздержа́нія наказа́телю і учи́телю.","Ра́дуйся, пустинножи́телей удобре́ніє;","ра́дуйся, мона́хов богодухнове́нноє світи́ло.","Ра́дуйся, уго́дниче Христо́в преізя́щний;","ра́дуйся, безмо́лвія рачи́телю теплі́йший.","Ра́дуйся, бісо́вськия си́ли крі́пкоє попра́ніє;","ра́дуйся, спасе́нія і́стинний наста́вниче.","Ра́дуйся, пода́телю ра́дости ві́рним;","ра́дуйся, ско́рий помо́щниче к тебі́ притека́ющим.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 2","ps":["Ви́дяще стра́нний і чу́дний житія́ твоєго́ о́браз преподо́бний Пафну́тій вельми́ удиви́ся; тім же і аз, размишля́я твоя́ па́че мі́ри трудолю́бния пусти́нния по́двиги, пою́ Бо́гу, на сія́ тебі́ укріпи́вшему: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зуму да́тися мні боже́ственному, помоли́ся преподо́бне Ону́фріє, ти бо, боже́ственним сія́ющи сві́том і с А́нгели водворя́ющися посо́бствуєши па́м'ять твою́ соверша́ющим і ра́достно похва́льная тебі́ си́це принося́щим:","Ра́дуйся, стра́нно доброді́тельми просія́вий;","ра́дуйся, со́лнечнаго сві́та світлі́йшій.","Ра́дуйся, А́нгелом в пусти́ню проводи́мий;","ра́дуйся, го́рлице пустиннолю́бная.","Ра́дуйся, рожо́ багряноцвету́щая;","ра́дуйся, хра́мі всечестни́й і Бо́гу освяще́нний.","Ра́дуйся, Бо́жиїх дарова́ній ісполне́ніє;","ра́дуйся, пречу́дноє в челові́ціх удивле́ніє.","Ра́дуйся, бісо́в стра́нноє і гро́зноє устраше́ніє;","ра́дуйся, предраги́й адама́нте.","Ра́дуйся, Тро́їчнаго сві́та зри́телю;","ра́дуйся, те́плий в моли́твах предста́телю.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго от ложе́сн ма́терніх осіни́ тя, преподо́бне Ону́фріє, і показа́ тя селе́ніє і жили́ще Свята́го Ду́ха, Єго́же і аз недосто́йний усе́рдно прия́ти жела́юще, пою́ піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще тя вели́ка, о́тче, засту́пника і ско́раго в напа́стіх помо́щника, разли́чними одержи́мії напа́стьми тя на по́мощ призива́єм, і ве́село в твоє́й сві́тлой па́м'яті торжеству́юще, сія́ тебі́ вопіє́м:","Ра́дуйся, ско́рий послу́шателю моля́щихся тебі́ с ві́рою;","ра́дуйся, пра́веднаго Судії́ ізві́стноє умоле́ніє.","Ра́дуйся, честно́є Пресвята́го Ду́ха селе́ніє;","ра́дуйся, непоро́чний Пресвяти́я Тро́йці служи́телю.","Ра́дуйся, предраги́й Христа́ Бо́га би́сере;","ра́дуйся, неізрече́нная вели́кому Пафну́тію ра́досте.","Ра́дуйся, того́жде Пафну́тія наста́вниче і учи́телю;","ра́дуйся, скорб'я́щих ско́роє утіше́ніє.","Ра́дуйся, унива́ющих всежела́тельний посіти́телю;","ра́дуйся, сліпи́х врачу́ і хроми́х ціли́телю.","Ра́дуйся, боля́щих здра́віє і неду́гующих врачева́ніє;","ра́дуйся, ві́рних спасе́нноє прибі́жище.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 4","ps":["Бу́рю страсте́й многом'яте́жнаго ми́ра возненави́дівши, о́тче, всіх єго́ устрани́лся єси́ красо́т, всели́вся же в пусти́ню, преподо́бне, Крести́телю в житії́ послі́довал єси́ і проро́ка Ілію́ подража́л єси́, ни́ні же ві́чнующую в небе́сних дво́ріх сла́ву получи́вши, с небе́сними Бо́гу предстої́ши жи́телі і поє́ши ку́пно с ни́ми: Аллилу́я."]},{"h":"Ікос 4","ps":["Світоно́сноє со́лнце і златоза́рноє світи́ло іму́ще тя ві́рнії, свя́те Ону́фріє, уми́льно тя мо́лим, просвіти́, вразуми́, научи́ вопи́ти тебі́ си́це:","Ра́дуйся, пусти́ні сві́тлоє озаре́ніє;","ра́дуйся, златоза́рний ми́ра світи́льниче.","Ра́дуйся, Фиве́єв пречу́дная красото́;","ра́дуйся, Ливи́ї прекра́сная добро́то.","Ра́дуйся, Єги́пта пресві́тлоє украше́ніє;","ра́дуйся, Месопота́мії превели́кий наста́вниче.","Ра́дуйся, Іоа́нна Крести́теля і́стинний і при́сний подража́телю;","ра́дуйся, благово́нний пусти́ні ке́дре.","Ра́дуйся, я́ко равноа́нгельно слу́жиши Бо́гу;","ра́дуйся, я́ко заступа́єши всіх, те́плі тя на по́мощ призива́ющих.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 5","ps":["Боготе́чную зарю́ уви́дівши тя, о́тче, в пусти́ні, вели́кий Пафну́тій тща́тельно послі́дова тебі́, і я́ко учи́тельна світи́льника придержа́ся тебі́, і о пусти́нном любопи́тно іспита́в житії́, єго́же от тебе́ до́брі нави́к, уми́льно воспіва́я Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя твоє́ стра́нноє житіє́, Собо́р церко́вний, Ону́фріє преподо́бне, с благогові́нієм твою́ блаже́нную па́м'ять вели́ть почита́ти. Сего́ ра́ди і аз, спасе́ніє хотя́ получи́ти, с весе́лієм почита́ю і си́це тебі́ вопію́:","Ра́дуйся, пресві́тлая красото́ Це́ркве Христо́ви;","ра́дуйся, неуси́пний предста́телю і́щущим хода́тайства твоєго́.","Ра́дуйся, я́ко ко Го́споду ви́ну вопіє́ши за ни;","ра́дуйся, я́ко тобо́ю просвіти́шася вну́тренняя пусти́ні.","Ра́дуйся, я́ко просія́ша до́брая діла́ твоя́, а́ки со́лнце на землі́ і на небесі́;","ра́дуйся, я́ко впери́л єси́ ум твой к Бо́гу.","Ра́дуйся, я́ко обогати́лся єси́ нището́ю ду́ха;","ра́дуйся, орле́ гнізда́ небе́снаго.","Ра́дуйся, пре́лести бісо́вськия, я́ко трость, попаля́ющий;","ра́дуйся, послу́шателю Єва́нгелія Христо́ва.","Ра́дуйся, мудрова́ніє пло́ті крі́постію Боже́ственнаго Ду́ха смири́вий;","ра́дуйся, земни́й а́нгеле, небе́сний челові́че.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 6","ps":["Про́повіді Єва́нгельськия творця́, є́же не пещи́ся о ри́зі іли́ что я́сти, і́стинна тя, Ону́фріє, узрі́ Влади́ка Госпо́дь і а́біє власи́ бі́лими, я́ко оде́ждою, оді́я тя чу́дно, і сла́вою сви́ше обогати́л тя єсть в преставле́нії твоє́м; ю́же і нам от Христа́ получи́ти моли́, вопію́щим Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ от Єги́пта, столпо́м Боже́ственнаго сві́та наставля́єм, преподо́бне Ону́фріє, не терп'я́ще же тя бісо́встії полці́ в пусти́ні, біжа́ша; от ї́хже наві́тов і нас ізба́ви моли́твами твої́ми, вопію́щих ті си́це:","Ра́дуйся, пре́лести бісо́вськия потреби́телю;","ра́дуйся, бісо́в стра́шний прогони́телю.","Ра́дуйся, главу́ змі́єву уязви́вий моли́твами твої́ми;","ра́дуйся, дарова́ній Свята́го Ду́ха преіспо́лненний.","Ра́дуйся, ду́хи лука́вствія смиренному́дрієм покори́вий;","ра́дуйся, я́ко крест твой на ра́мі поне́сл єси́.","Ра́дуйся, я́ко тім амали́ка ми́сленнаго си́лу низложи́л єси́;","ра́дуйся, я́ко бре́м'я ле́гкоє Христо́во восприя́л єси́ на ра́мо.","Ра́дуйся, я́ко от ю́ности возлюби́л єси́ і́го Христо́во;","ра́дуйся, я́ко спасе́н от вра́жиїх сіте́й, благода́рственно Бо́гу вопіє́ши.","Ра́дуйся, я́ко і ві́рним на враги́ мо́щно посо́бствуєши;","ра́дуйся, я́ко те́плі к тебі́ притека́ющих треволне́нія страсте́й ізміня́єши.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 7","ps":["Ізше́дшу Пафну́тію от оби́телі во вну́тренняя пусти́ні, є́же ви́діти Го́сподеві рабо́тающия, Бо́жиїм смотре́нієм узрі́ тя стра́нним о́бразом і ужасе́ся; по глаго́ланії же твоє́м к нему́, позна́в тя би́ти челові́ка, ві́рне і ди́вне Бо́гу рабо́тающа, возгласи́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий воі́стину побідоно́сець на плотські́я стра́сті яви́лся єси́, преподо́бне, і кто дово́лен воспі́ти боре́нія твоя́? Кто ізочте́ть труди́, болі́зні і по́двиги, в ни́хже тече́ніє по́стничества соверши́л єси́? К сих же похвале́нію недово́льни су́ще, любо́вію па́че почита́єм тя і ві́рно тебі́ сицева́я вопіє́м:","Ра́дуйся, гла́дом і жа́ждею плоть твою́ удручи́вий;","ра́дуйся, тьми предста́теля всеконе́чно побіди́вий.","Ра́дуйся, я́ко вся́ко сладостра́стіє всено́щними бді́нії ув'яди́л єси́;","ра́дуйся, я́ко зако́нно в моли́твах і поще́ніїх претерпіва́я, в безстра́стіє обле́клся єси́.","Ра́дуйся, преди́вноє воздержа́нія зерца́ло;","ра́дуйся, преподо́бних ли́ку вели́кая сла́во.","Ра́дуйся, я́ко мра́зом померза́ємій пло́ті твоє́й, теплото́ю любве́ Христо́ви согріва́шеся дух твой;","ра́дуйся, я́ко зно́єм опаля́єма тя роса́ Боже́ственния благода́ті прохлажда́ше, преподо́бне.","Ра́дуйся, пусти́ні ле́поє украше́ніє;","ра́дуйся, по́двигов і соверше́нства о́бразе.","Ра́дуйся, я́ко вся́ку доброді́тель в тебі́ ізобрази́л єси́;","ра́дуйся, я́ко вселюби́мий подвигополо́жнику Христу́ уго́дник показа́лся єси́.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 8","ps":["Стра́нноє твоє́ житіє́ бисть, Ону́фріє: взира́я бо на возра́стшаго при пеще́рі твоє́й фи́ника, воздержа́нієм па́че пита́лся єси́. Сего́ ра́ди, улучи́во ви́шнюю трапе́зу, поє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ во ви́шніх і го́ре о́ком твоєя́ душі́ взира́л єси́ непреста́нно в сем стра́нном по́стничестві твоє́м, ни́ні же дерзнове́ніє стяжа́в к Бо́гу, преподо́бне, заступа́єши всіх, на по́мощ тя призива́ющих і вопію́щих ті си́це:","Ра́дуйся, пустинножи́телю вели́кий;","ра́дуйся, а́ки звізда́, в пусти́нях просія́вий.","Ра́дуйся, подража́вий стопа́м Христо́вим от младе́нства твоєго́;","ра́дуйся, а́нгельськаго житія́ ревни́телю.","Ра́дуйся, наві́тов неви́димих враг прогони́телю;","ра́дуйся, воздержа́нія чу́днаго показа́телю.","Ра́дуйся, соверше́нства преізя́щний учи́телю;","ра́дуйся, стра́нний і ди́вний к небесі́ путь показа́вий.","Ра́дуйся, я́ко равноа́нгельно на землі́ пожи́л єси́;","ра́дуйся, я́ко равноа́нгельную сла́ву і честь досто́йно получи́л єси́.","Ра́дуйся, я́ко в небе́сних дво́ріх ни́ні о всіх мольби́ Творцю́ прино́сиши;","ра́дуйся, я́ко тебі́ хода́тая стяжа́вшим вели́кия благода́ті Бо́жия іспроша́єши.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ удиви́ся тебі́, Ону́фріє свя́те: ми́ра бо кра́сная от се́рдця возненави́дів і єди́наго Бо́га от душі́ возлюби́в, пусти́ню пости́гл єси́. Іді́же в єди́ніх то́кмо виді́ніїх упражня́яся, яви́лся єси́ я́ко А́нгел, с пло́тію живи́й, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йстії язи́ци восхвали́ти тя по достоя́нію не мо́гуть, о́тче богому́дре Ону́фріє: ти бо от утро́би ма́терні Бо́гу прибли́зив твой смисл, весьма́ приліжа́л єси́ Царю́ Вседержи́телю, плоди́ досто́йни принося́ Єму́ от твої́х по́двиг во всем житії́, преподо́бне. Аз у́бо от Це́ркве Бо́жия сла́вима тя о тіх уві́дів, ві́рно тебі́ сицева́я вопію́:","Ра́дуйся, от младе́нства мона́шеському обуче́нію вда́нний;","ра́дуйся, в ю́ності Бо́жиїм наставле́нієм в пусти́нноє безхра́міє введе́нний.","Ра́дуйся, я́ко Христо́вим словесе́м послі́дуя, ми́ра, оте́чества же і ро́да отре́клся єси́;","ра́дуйся, я́ко крест твой єва́нгельськи на ра́мі твоє́м поне́сл єси́.","Ра́дуйся, небреги́й о ри́зі, да нетлі́нія ри́зу себі́ самому́ соді́лаєши;","ра́дуйся, сі́явий слеза́ми, да с ра́достію рукоя́ті твоя́ по́жнеши.","Ра́дуйся, я́ко неяде́нієм, ну́ждною нището́ю і всегда́шнім на моли́тві стоя́нієм плоть ізнури́л єси́;","ра́дуйся, я́ко путі́ же́стоки за словеса́ усте́н Го́спода твоєго́ сохрани́л єси́.","Ра́дуйся, по́двиги твої́ми стра́сті тіле́сния до конця́ умертви́вий;","ра́дуйся, равноа́нгельную чистоту́ сохрани́вий.","Ра́дуйся, я́ко многолі́тні а́ки безпло́тен пожи́л єси́;","ра́дуйся, я́ко от Венцепода́теля безпло́тним лико́м ни́ні счи́слился єси́.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́ще ві́рнії от напа́стей разли́чних, о́тче, предста́теля тя себе́ і побо́рника поставля́ють і не лиша́ються наде́жд свої́х: ти бо моли́твами к Бо́гу твої́ми от бід лю́тих і скорбе́й, одержа́щих ни, і многоразли́чних злих ізима́єши, наставля́єши же на спасе́нія стезі́ усе́рдно к тебі́ притека́ющия і Бо́гу ві́рно вопію́щия: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну тя, засту́пника і моли́твенника те́пла обрі́т, преподо́бне, із глубини́ се́рдця, я́ко благоуха́нноє кади́ло, с воздиха́нієм Бо́гу возсила́ю хвалу́; тебі́ же, при́сному су́щу моли́твеннику, сицева́я приношу́ пі́нія:","Ра́дуйся, плодо́в доброді́тельних благопроцве́тшая ни́во;","ра́дуйся, благоче́стія преізря́дноє удобре́ніє.","Ра́дуйся, земни́м засту́пниче крі́пкий;","ра́дуйся, послу́шателю притека́ющим к тебі́ те́плий.","Ра́дуйся, світи́льниче, де́монський мрак отріва́яй;","ра́дуйся, душетлі́нних неду́гов тьму отгоня́яй.","Ра́дуйся, я́ко заблужда́ющих преподо́бними нра́ви на путь пра́вий руково́дствуєши;","ра́дуйся, я́ко к ісполне́нію Бо́жиїх хоті́ній управля́єши.","Ра́дуйся, я́ко многоразли́чная благодія́нія тобо́ю сви́ше подає́ма бива́ють;","ра́дуйся, я́ко духо́в зло́бних наві́ти от призива́ющих тя бі́гають.","Ра́дуйся, я́ко всіх моле́нія дерзнове́нно Ви́шнему прино́сиши;","ра́дуйся, я́ко всіх в ну́ждах і печа́ліх защища́єши.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 11","ps":["Пі́ніє а́нгельськоє сли́шашеся в боже́ственнім преставле́нії твоє́м, о́тче, святі́й бо і богоуго́днейшей душі́ твоє́й, в небе́сная селе́нія пресла́вно восходя́щей, си́ли небе́сния дивля́хуся, пою́ще: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тло по преставле́нії лице́ твоє́ ви́ді, о́тче, Пафну́тій святи́й удиви́ся. Разділи́в же на дві ча́сти ря́су свою́, покри́ мо́щі твоя́ і погребе́ тя со льви че́стно. Сія́ і аз ду́хом благогові́йно почита́я, си́це ті вопію́:","Ра́дуйся, я́ко всего́ тебі́ Бо́гу освяти́л єси́;","ра́дуйся, я́ко до́брі Боже́ственния зако́ни соблю́л єси́.","Ра́дуйся, ізше́ствіє твоє́ от житія́ проро́чеськи предве́девий;","ра́дуйся, в те́плій к Бо́гу любві́ і благогові́нії многотру́дния твоя́ по́двиги око́нчивий.","Ра́дуйся, в преставле́нії благоуха́нієм чу́дним, а́ки ра́йським, почте́нний;","ра́дуйся, мо́лнії тогда́ і блиста́нії ди́вно просла́вленний.","Ра́дуйся, єго́же мо́щі а́нгельстії ли́ци с пі́нієм, кади́ли і свіща́ми окружи́ша;","ра́дуйся, єму́же го́рняя си́ли врата́ ра́йськия отверзо́ша.","Ра́дуйся, я́ко в то́мже часі́ сія́ніє ве́ліє, облиста́вшеє тя, зря́шеся;","ра́дуйся, я́ко сла́дкий глас, к восприя́тію ві́чних благ призива́ющ тя, сли́шашеся.","Ра́дуйся, я́ко святу́ю твою́ ду́шу вінцеда́вець Христо́с сла́вно прия́т в го́рняя селе́нія;","ра́дуйся, я́ко ни́ні ві́чнаго ізоби́льно наслажда́єшися весе́лія.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 12","ps":["Благода́ть, да́нную ті, і по́двиги твоя́ нікто́же от земни́х ізрещи́ мо́жеть, о́тче Ону́фріє: в пусти́ні бо нестяжа́тельно живи́й, пи́щу імі́л єси́ хліб а́нгельський, от челові́к бі́гая, с Бо́гом і А́нгели бесі́довал єси́. Сего́ ра́ди в небе́сних черто́зіх ра́дуєшися і поє́ши піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м до́блественния по́двиги твоя́, ублажа́єм достохва́льную кончи́ну, почита́єм і свяще́нную па́м'ять твою́, преподо́бне, к не́йже і я́ко єди́ному тебі́ от два́десяти четиреіх ста́рець, окружа́ющих Престо́л Ви́шняго, председя́щему похва́льная си́це вопіє́м:","Ра́дуйся, стра́нно на землі́ пожи́вий;","ра́дуйся, стра́нную і кончи́ну наслі́дивий.","Ра́дуйся, я́ко сві́тлими по́двиги твої́ми к сві́ту невече́рнему вшел єси́;","ра́дуйся, я́ко преми́рноє наслі́діє бога́тно стяжа́л єси́.","Ра́дуйся, я́ко с безпло́тними Трисвяту́ю піснь Бо́гу немо́лчно вопіє́ши;","ра́дуйся, неізрече́нних благ наслі́дниче.","Ра́дуйся, преподо́бних і пра́ведних собесі́дниче;","ра́дуйся, я́ко ни́ні разре́шшимся зерца́лом Тро́йцю Святу́ю зри́ши непосре́дственно.","Ра́дуйся, я́ко в па́м'яті твоє́й Це́рков Христо́ву весели́ши неізрече́нно;","ра́дуйся, я́ко тобо́ю по́стници і пустинножи́телі в по́двиг укріпля́ються.","Ра́дуйся, я́ко ві́рнії хода́тайством твої́м всіх благ сви́ше сподобля́ються.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 13","ps":["Овсехва́льний і преди́вний уго́дниче Христо́в о́тче Ону́фріє, молю́ ті ся і вопію́ всеусе́рдно: прийми́ сіє́ ма́лоє, от мене́ приноси́моє моле́ніє і потщи́ся ско́ро умоли́ти ми́лостиваго Бо́га і Влади́ку, да ізба́вить м'я от вся́ких бід і бу́дущия і́зметь му́ки, вопію́щаго: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельстії чи́ни твої́м, о́тче, удиви́шася по́двигом, і́миже в пусти́ні непреста́нно упражня́лся єси́; три бо і шестьдеся́т літ пости́лся єси́, Боже́ственния же Христо́ви Та́йни от рук а́нгельських прийма́ти сподо́бился єси́, і ни́ні у́бо почита́я тя єдиновсе́льника і собесі́дника А́нгелов, сицева́я вопію́ тебі́, свя́те Ону́фріє:","Ра́дуйся, А́нгелов преди́вноє чу́до;","ра́дуйся, душетлі́нних страсте́й разруши́телю.","Ра́дуйся, непроходи́мия пусти́ні просвіти́телю;","ра́дуйся, воздержа́нія наказа́телю і учи́телю.","Ра́дуйся, пустинножи́телей удобре́ніє;","ра́дуйся, мона́хов богодухнове́нноє світи́ло.","Ра́дуйся, уго́дниче Христо́в преізя́щний;","ра́дуйся, безмо́лвія рачи́телю теплі́йший.","Ра́дуйся, бісо́вськия си́ли крі́пкоє попра́ніє;","ра́дуйся, спасе́нія і́стинний наста́вниче.","Ра́дуйся, пода́телю ра́дости ві́рним;","ра́дуйся, ско́рий помо́щниче к тебі́ притека́ющим.","Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Кондак 1","ps":["Ізбра́нний і ди́вний о́тче Ону́фріє, сія́ющий трисія́ннаго живота́ заре́ю, ти м'я, омраче́ннаго гріхо́вними страстьми́, просвіти́, от смертоно́сния ра́ни ісхити́ і твої́ми моли́твами от всіх бід ізба́ви, да зову́ тебі́: Ра́дуйся, о́тче Ону́фріє, пресві́тлий світи́льниче всея́ вселе́нния."]},{"h":"Молитва перша","ps":["Опреїзя́щний і превели́кий пустинножи́телю, преподо́бне о́тче Ону́фріє! Похваля́ю твоя́ неізрече́нная чудотворе́нія і житіє́ пресві́тло, є́же єси́ препроводи́л от ю́ности твоєя́, да́же і до ста́рости: нікто́же бо ісчести́ возмо́же терпі́нія і по́двигов твої́х, пречестне. Удиви́ся преподо́бний Пафну́тій твоєму́ жесто́кому є́же в пусти́ні житію́, вку́пі же і зіло́ возра́довася, обрі́т тя єди́наго толи́ких по́двигов і соверше́нства су́ща о́браз. Сего́ ра́ди і по́длинно іспита́ о труді́х твої́х святи́х і о є́же коли́ко імі́л єси́ вре́меннаго житія́. Ті́мже і написа́, я́ко шестьдеся́т літ і три в трудолю́бії пребива́я, в наготі́ претерпіва́я мраз і зной, в глубо́цій пусти́не со звірми́ і пти́ці обита́я, моли́тви непреста́нно творя́, пожи́л єси́. Сего́ ра́ди ни́ні ра́дость тебі́ приношу́ от недосто́йних усте́н мої́х, преподо́бне о́тче, преподо́бному Пафну́тію ра́досте вели́кая (сподо́бися бо при кончи́ні с льви послужи́ти тебі́, погребсти́ ті́ло твоє́ і с тобо́ю на небесі́ жи́ти), Ілії́ Фесви́тянину ревни́телю, Іоа́нну Крести́телю наслі́дниче, дру́же Христо́в і снаслі́дниче і́стинний, Єги́пту у́мная красото́, Фиве́ом вели́коє світи́ло, Ливи́ї кра́сная добро́то, фи́никс краснопроцвета́ющий, орле́ високопа́рний, лета́ющий в поднебе́сная, на небесі́х гражда́нство обріти́й, іді́же і водвори́ся у Престо́ла Влади́ки Сла́ви, с два́десять чети́рми ста́рці жили́ще обріти́й, с ни́ми же і пребива́єши. І ни́ні молю́ тя, пречу́дний граждани́не небе́сний, святи́х лико́в А́нгельських совсе́льниче, усли́ши м'я, грі́шнаго і недосто́йнаго раба́ твоєго́, в час сей і прийми́ сіє́ ма́лоє моле́ніє моє́ Ака́фистово, вели́кий засту́пниче, ско́рий помо́щниче притека́ющим к тебі́ усе́рдно. Загла́ди рукописа́ніє діл мої́х скве́рних і нечи́стих, я́же держа́ть де́монськия полки́. Покри́й м'я твої́м заступле́нієм, причти́ м'я ко угото́ванному пресві́тлому мі́сту моли́твами твої́ми і сподо́би м'я ви́шняго Ієрусали́ма, і́бо по Преблагослове́нній Влади́чиці на́шей Богоро́дице і Присноді́ві Марі́ї, тебі́ между́ теплі́йшими помо́щници, моле́бници і засту́пниці мої́ми почита́ю. Присіща́єши бо і дає́ши ру́ку по́мощі припа́дающим к тебі́ в хра́мі твоє́м і повсю́ду. Тім же і аз недосто́йний ни́ні тебі́ молю́ся і призива́ю: умоли́ ми́лостиваго Бо́га, да отпу́стить мі вся прегріше́нія моя́, во́льная і нево́льная, сотворе́нная вся зла́я діла́ моя́, і да ізба́вить м'я твої́м предста́тельством от ві́чних мук, научи́ть м'я твори́ти до́брая діла́, наста́вить м'я на путь к спасе́нію і́стинному і сподо́бит м'я ку́пно ра́дости ві́чния наслади́тися со всі́ми святи́ми, ни́ні і при́сно, і во ві́ки віко́в, амі́нь."]},{"h":"Молитва друга","ps":["Опречу́дне і преблаже́нне уго́дниче Христо́в і а́вво наш, Ону́фріє Вели́кий! Ти ди́вную любо́в ко Го́споду твоєму́ показа́л єси́, і на ди́вния по́двиги благода́тію Єго́ укріпи́лся єси́, і сего́ ра́ди ве́лія дерзнове́нія к Нему́ сподо́бился єси́: мно́га бо чудеса́ і зна́менія си́ли Бо́жия лю́дем о тебі́ яви́шася. Воззри́ у́бо і ни́ні, о́тче преди́вний, благосе́рдим о́ком любве́ твоєя́ на ни недосто́йния раби́, і да́руй всім по коєго́ждо потре́бі, по ві́рі же і упова́нію: скорб'я́щия обра́дуй, пла́чущия уті́ши, неду́гующия ісціли́, тружда́ющимся помози́, борю́щияся со страстьми́ і прило́ги вра́жіїми укріпи́ і благослови́, ізнемога́ющия поддержи́, оби́тель твою́ і всіх нас от враг ви́димих і от вся́каго зла сохрани́. Возвели́чи ві́ру святу́ю правосла́вную во оте́чествії на́шем, обрати́ заблу́ждшия, вразуми́ отпа́дшия, утверди́ коле́блющияся, ум'ягчи́ упо́рствующия, просвіти́ неві́рния, і вся приведи́ в ти́хоє приста́нище Оте́чествія Небе́снаго. О преди́вноє сло́во мона́шествующих і всіх ві́рних утіше́ніє! Сла́вними по́двиги твої́ми і сла́дким лицезрі́нієм чудотво́рнаго о́браза твоєго́ і нас озари́ і на всяк по́двиг, труд і терпі́ніє укріпи́ во сла́ву І́мені Бо́жия, да спасе́ннії сподо́бимся с тобо́ю і всі́ми святи́ми Ві́чнаго і Преблагослове́ннаго Ца́рствія сла́ви Отця́, і Си́на, і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["Опреподо́бне о́тче Ону́фріє! Мо́лим тя: усли́ши нас, грі́шних і недосто́йних раб Бо́жиїх (імена́), в час сей. І прийми́ сіє́ ма́лоє моле́ніє на́ше: рукописа́ніє діл на́ших скве́рних і нечи́стих моли́твою твоє́ю ізгла́ди, твої́м заступле́нієм при́сно нас покрива́й і ко угото́ванному ві́рним пресві́тлому черто́гу моли́твами твої́ми приведи́; умоли́ у́бо Ми́лостиваго Бо́га, да отпу́стить нам вся прегріше́нія на́ша во́льная і нево́льная і вся зла́я діла́, на́ми сотворе́нния, і да ізба́вить нас твої́м предста́тельством от ві́чних мук і сподо́бит нас ра́дости ві́чния наслади́тися, ку́пно со всі́ми святи́ми, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Жела́нієм духо́вним пусти́ні дости́гл єси́, / Богому́дре Ону́фріє, / і, я́ко безпло́тен, в ней многолі́тні подвиза́лся єси́ трудолю́бні, / соревну́я проро́кам Ілії́ і Крести́телю, / і, от руку́ а́нгельську Та́їн Боже́ственних наслади́вся, / ни́ні во сві́ті Святи́я Тро́йці ку́пно с ни́ми весели́шися, / моли́ спасти́ся нам, // твою́ па́м'ять почита́ющим."]},{"h":"Кондак, глас 3","ps":["Сія́нієм Ду́ха Пресвята́го, / Богому́дре, просві́щся, / оста́вил єси́ я́же в житії́ молви́, / пусти́ню же дости́гл єси́, преподо́бне о́тче, / возвесели́л єси́ І́же над всі́ми Бо́га і Зижди́теля, / сего́ ра́ди прославля́єть тя Христо́с, блаже́нне, // вели́кий Дарода́тель."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Ону́фріє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст великомучениці Анастасії Узорішительці","e":"Akathist to the Great Martyr Anastasia the Deliverer from Bonds","secs":[{"h":"Кондак 1","ps":["Ізбра́нній уго́днице Христо́вой, всеблаженней великому́ченице Анастасі́ї похва́льноє пі́ніє прино́сим, я́ко іму́щей мно́гоє дерзнове́ніє ко Го́споду є́же от вся́ких бід, скорбе́й і болі́зней свобожда́ти ві́рния, і с любо́вію взива́єм си́це:","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Ікос 1","ps":["А́нгелом уподо́билася єси́ ра́зумом чи́стим, позна́вши Того́, І́же єсть всего́ ви́димаго і неви́димаго ві́чноє нача́ло і єди́ний коне́ць жела́ній всіх благочести́вих; ми же, восхваля́юще му́дроє обуче́ніє твоє́ от свята́го му́ченика Хрисого́на, с любо́вію вопіє́м ті:","Ра́дуйся, возлюби́вшая ві́ру Христо́ву;","ра́дуйся, последовавшая благоче́стію ма́тере твоєя́ Фавсти.","Ра́дуйся, соблю́дшая чистоту́ ді́вства твоєго́;","ра́дуйся, всегда́ неви́димо охраняємая А́нгелами.","Ра́дуйся, чистото́ю твоє́ю к Бо́гу приблизившаяся.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ви́дящи свята́я Анаста́сія, я́ко мно́зі христия́не стра́ждуть в темни́цях за І́м'я і уче́ніє Ісу́с Христо́во, нача́ть со усе́рдієм служи́ти їм, утіша́ти же і ціли́ти я, соді́йствующу Бо́гу, со благогові́нієм пою́щи: Аллилу́я."]},{"h":"Ікос 2","ps":["Уразумі́ богому́драя Анаста́сія, я́ко вся ми́ра сего́ кра́сная тлі́нію прича́стна суть, і того́ ра́ди презрі́вши сві́тлия оде́жди і у́твари многоці́нни, та́йно обо́лкшися во оде́жди ни́щих, вхожда́ше в темни́ці послужи́ти іспові́дником Христо́вим; ми же, ми́сленно споследствующе єй, взива́єм к ней с любо́вію:","Ра́дуйся, посіти́тельнице заключе́нних в темни́цях;","ра́дуйся, уті́шительнице іспові́дников Христо́вих.","Ра́дуйся, зла́то і сребро́ твоє́ на них расточившая;","ра́дуйся, ті́ми стяжа́вшая Ца́рствіє Небе́сноє.","Ра́дуйся, ру́ці і но́зі святи́х омивавшая і власи́ їх очищавшая;","ра́дуйся, подражательнице Христо́ва.","Ра́дуйся, неду́ги їх врачевавшая;","ра́дуйся, тілеса́ їх че́стне погребавшая.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́лою укріпля́єма сви́ше, свята́я му́ченице, послужи́ благоче́стно святи́м і посрами́ ненави́стника вся́кия доброді́телі дия́вола, наустившаго раби́ню откри́ти дія́нія твоя́ пред муже́м неві́рним; ми же, восхваля́юще благотворе́нія твоя́, Анастасі́є, поє́м вку́пі с тобо́ю: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи вели́кую любо́в о Го́споді ко всім, в темни́цях стра́ждущим за і́м'я Христо́во, єя́же ра́ди мно́жицею бієна би́вши от неві́рнаго му́жа, напослі́док в до́му єго́ себі́ темни́цю обрі́те; ті́мже му́жеству єя́ див'я́щеся, вопіє́м к ней:","Ра́дуйся, за́повідей Христо́вих усе́рдная храни́тельнице;","ра́дуйся, не сло́вом то́чію, но і ді́лом сія́ іспо́лнившая.","Ра́дуйся, ду́шу свою́ за дру́ги положи́ти гото́вая;","ра́дуйся, мно́гоє озлобле́ніє за Христа́ прия́вшая.","Ра́дуйся, терпі́нієм свої́м адама́нту крі́пкому уподо́бившаяся.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 4","ps":["Бу́рю я́рости своєя́ воздви́же на тя нечести́вий мучи́тель муж твой, я́ко плі́нницю і рабу́ вміни́ тя, свята́я Анастасі́є; ми же, воспомина́юще озлобле́нія от него́ і страда́нія твоя́, поє́м укреплявшему тя Го́споду: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша блаже́нная Анаста́сія, я́ко мно́го претерпі́ святи́й учи́тель єя́ Хрисого́н за Христа́, єму́ же і послі́дова страда́ньми свої́ми і та́йно восписа́ єму́ си́це: \"Учи́телю! Ча́ю умре́ти і нічто́же і́но остає́ться, то́чію да іспустивши дух, паду ме́ртва\". Ми же, чудя́щеся терпі́нію твоєму́, глаго́лем си́це:","Ра́дуйся, не пощадившая пло́ті своєя́ честни́я;","ра́дуйся, желавшая расточи́ти бога́тство твоє́ Бо́га ра́ди неімущим.","Ра́дуйся, му́дро ку́плю ді́ющая;","ра́дуйся, єди́но іму́щая попече́ніє о стра́ждущих во у́зах.","Ра́дуйся, с усе́рдієм їм служившая;","ра́дуйся, небоя́зненно входившая в темни́ці.","Ра́дуйся, невозбра́нно вше́дшая в Черто́г Небе́сний.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 5","ps":["Я́ко боготе́чная звізда́ яви́лася єси́ в ри́мстій страні́, великому́ченице Анастасі́є, посіща́ющи стра́ждущих за Христа́ в темни́цях і се́рдця їх во ві́рі утвержда́ющи, да при́сно взива́ють с тобо́ю Спаси́телю всіх Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́ді тя богоно́сний учи́тель твой Хрисого́н в смуще́нії і волне́нії ми́ра сего́ су́щу, повелі́ с проро́ком взива́ти тебі́: \"Вску́ю приско́рбна єси́, душе́ моя́, і вску́ю смуща́єши м'я, упова́й на Бо́га», ми же, помина́юще скорб і печа́ль твою́, я́же по Бо́зі, зове́м ті:","Ра́дуйся, возложившая все упова́ніє твоє́ на Го́спода;","ра́дуйся, претерпі́вшая тісноту́ Ца́рствія ра́ди Небе́снаго.","Ра́дуйся, чистото́ю твоє́ю со А́нгели жи́ти на небесі́х сподо́бившаяся;","ра́дуйся, скорбми́ твої́ми к Бо́гу приблизившаяся.","Ра́дуйся, сподо́бльшаяся зрі́ти разу́мними очеси́ Го́спода Вседержи́теля;","ра́дуйся, моли́твами твої́ми ізбавля́ющая нас от мно́гих скорбе́й.","Ра́дуйся, хода́тайством твої́м свобожда́ющая от іскуше́ній.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 6","ps":["Пропові́дуєть весь мир христия́нський честни́я по́двиги твоя́, великому́ченице Анастасі́є, і страда́нія твоя́ сла́вить, му́ченичеськую кончи́ну твою́ ублажа́єть і поє́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ па́че со́лнця доброді́тельми твої́ми во вели́ком гра́де Ри́мі, єгда́ іспо́лнися предрече́ніє учи́теля твоєго́ свята́го Хрисого́на о поги́белі безбо́жнаго му́жа твоєго́. Свобо́дна бо су́щи, с вя́щшим усе́рдієм нача́ла єси́ пещи́ся о му́чениціх Христо́вих; ми же, взира́юще с любо́вію на дія́нія твоя́, глаго́лем ті си́це:","Ра́дуйся, усе́рдная помо́щнице стра́ждущим;","ра́дуйся, боже́ственними словеси́ утешавшая друзі́й Христо́вих.","Ра́дуйся, наста́внице, імі́вшая ве́ліє попече́ніє о трех ді́вах: Ага́пії, Хіоні́ї і Ірине;","ра́дуйся, тіх на по́двиг му́ченичества укріпи́вшая.","Ра́дуйся, честна́я ті́ла їх на ізбранном мі́сті положившая;","ра́дуйся, ум твой го́ре імі́вшая.","Ра́дуйся, се́рдце твоє́ жили́ще Свята́го Ду́ха соді́лавшая;","ра́дуйся, огне́м любві́ к Бо́гу всеці́ло возгоревшая.","Ра́дуйся, в кро́ві крил Єго́ небе́сний покро́в обрі́тшая;","ра́дуйся, му́жеством твої́м врага́ спасе́нія до конця́ низложи́вшая.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 7","ps":["Хоті́ніє свята́го Хрисого́на, є́же умре́ти за Христа́, іспо́лнися Бо́жиїм Про́мислом; єгда́ же узрі́ла єси́ честни́я мо́щі своєго́ учи́теля страстоте́рпця, любе́зно їх лобиза́ющи, восплакалася єси́, із глубини́ душі́ ізнося́щи Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую благода́ть і си́лу дарова́ тебі́ Госпо́дь наш, єгда́ восприя́ла єси́ по́двиг преходи́ти із гра́да в град, посіща́ющи во у́зах сідя́щих. Ми же, послі́дующе странствованію твоєму́, уми́льно вопіє́м ті:","Ра́дуйся, последовательнице стопа́м Христо́вим;","ра́дуйся, служи́тельнице мно́гим святи́м.","Ра́дуйся, отра́до тя́жко іспитуємих;","ра́дуйся, наде́ждо ненаде́жних.","Ра́дуйся, зла́том твої́м купующая свобо́ду ві́рним от уз темни́чних;","ра́дуйся, Боже́ственними словеси́ у́зи стра́ха разріша́ющая.","Ра́дуйся, моли́твами твої́ми ізбавля́ющая нас уз гріхо́вних;","ра́дуйся, узоріши́тельниці проіменованная.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 8","ps":["Стра́нствованіє твоє́ со свято́ю му́ченицею Феодо́тією мно́гим осла́бу подаде́: боля́щим дарова́ ісціле́ніє, мно́гим уме́ршим угото́ва погребе́ніє, живи́м на вя́щшія по́двиги доброді́телі укріпле́ніє; нас же недосто́йних сподо́би, свята́я, моли́твами твої́ми пі́ти разу́мно Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся хра́мина темни́ці іспо́лнися мно́гим пла́чем і риданіями твої́ми, єгда́ ра́но прите́кши в ню по оби́чаю твоєму́ і ні єди́наго же обрі́тши от у́зник, за і́м'я Христо́во всажде́нних, всі бо в нощ єди́ну повелі́нієм злочести́ваго царя́ сме́рті пре́дани би́ша; ми же, вспоминающе скорб твою́ о друзі́х Бо́жиїх, взива́єм та́ко:","Ра́дуйся, со усе́рдієм поіскавшая в темни́цях рабо́в Христо́вих;","ра́дуйся, па́ки обрі́тшая тіх в небе́сних селе́ніїх.","Ра́дуйся, вземшая с любо́вію на ра́мо своє́ крест Госпо́день;","ра́дуйся, сподо́бльшаяся всю́ду зрі́ти разу́мними очеси́ Го́спода Вседержи́теля.","Ра́дуйся, за любо́в твою́ к бли́жнім ве́ліє дерзнове́ніє к Бо́гу стяжа́вшая;","ра́дуйся, врачева́ніє больни́м ниспосилающая.","Ра́дуйся, Бо́жиїм велі́нієм полумертвих возставля́ющая;","ра́дуйся, чистото́ю уневі́стившаяся Христу́.","Ра́дуйся, великому́ченице просла́вленная.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 9","ps":["Нечести́вії мучи́теліє сові́т сотвори́ша на тя, страстоте́рпице непобіди́мая, хотя́ще приклонити тя ко ідольському служе́нію; ти же небоя́зненно взива́ла єси́ к ним: \"Раба́ Христо́ва єсьм, і пою́ Єму́ день і нощ: Аллилу́я\"."]},{"h":"Ікос 9","ps":["Витийствова с тобо́ю начальнейший жрець і́дольський, хотя́й ле́стію улови́ти святу́ю ду́шу твою́; ти же, позна́вши всю хи́трость вра́жию, посрами́ла єси́ мучи́теля і преміни́ла вся зла́я во блага́я, безтрепетно взира́ющи на ору́дія мучи́тельськая і на вся муки́; ми же, див'я́щеся му́жеству твоєму́, зове́м ті умиле́нними гла́си:","Ра́дуйся, отве́ргшая вся ми́ра сего́ кра́сная;","ра́дуйся, ізбра́вшая прия́ти разли́чния муки́ за Христа́.","Ра́дуйся, с любо́вію на смерть ідти́ возхотевшая;","ра́дуйся, і самі́х мучи́телей терпі́нієм твої́м удиви́вшая.","Ра́дуйся, страданіями твої́ми Це́рков Христо́ву украси́вшая;","ра́дуйся, ізбра́вшая жизнь ві́чную - Христа́.","Ра́дуйся, жреця́ і́дольськаго посрами́вшая;","ра́дуйся, де́мони нога́ма твої́ма попра́вшая.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 10","ps":["Спасти́ся всім хотя́щим людям споспі́шествуй моли́твами твої́ми, великому́ченице, пред Го́сподем і іспроси́ разріше́ніє гріхо́в почита́ющим страда́нія твоя́, да вопіє́м с тобо́ю: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго возлюби́ всім се́рдцем свої́м свята́я Анаста́сія і в темни́цю вве́ржена бисть за Сладча́йшаго Ісу́са, надо́лзі гла́дом і жа́ждею істаявающи і моли́твою укрепляющися; ті́мже прославля́юще тоя́ честна́я страда́нія, возсила́єм к ней пі́ніє таково́є:","Ра́дуйся, последовательнице страсте́м Христо́вим;","ра́дуйся, украси́вшаяся побідоно́сною сла́вою.","Ра́дуйся, земно́ю темни́цею в Небе́сний Черто́г восте́кшая;","ра́дуйся, та́мо с му́ченики водвори́вшаяся.","Ра́дуйся, моли́твою твоє́ю у Престо́ла Бо́жия воспомина́ющая нас;","ра́дуйся, у́зи гріхо́вния ско́ро разріша́ющая.","Ра́дуйся, де́мони от челові́к прогоня́ющая;","ра́дуйся, разбо́йники на путь пра́вди наставля́ющая.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим ті, прославля́юще твоя́ за Христа́ страда́нія, і мо́лим тя: свята́я страстоте́рпице, іспроси́ у ми́лостиваго Го́спода всім лю́дем здра́віє, долгоде́нствіє і на враги́ побі́ду і одолі́ніє. Нам же, восхваляющим муче́нія твоя́, пода́ждь мир і спасе́ніє, да поє́м Бо́гу во ві́ки: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлим і ра́достним лице́м послі́довала єси́ на страда́ніє, угото́ванноє ті от мучи́телей, є́же помишля́юще с ра́достію зове́м:","Ра́дуйся, в темни́ці Іллиристийстей гла́дом моримая;","ра́дуйся, питавшаяся наде́ждою своє́ю – Христо́м.","Ра́дуйся, от потопле́нія на мо́рі Бо́жиїм смотре́нієм ізба́вльшаяся;","ра́дуйся, меж чети́ріх столпо́в протяженная.","Ра́дуйся, уподобльшаяся расп'я́тому на Кресті́ Си́ну Бо́жию;","ра́дуйся, жегомая огне́м да́же до сме́рти.","Ра́дуйся, Узоріши́тельниці, от уз і пло́ті разрешившаяся.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 12","ps":["Благода́ть сви́ше ниспосли́ всім нам, притекающим с любо́вію к іко́ні твоє́й, і іспроси́ у Го́спода проще́ніє согріше́ній на́ших, боля́щим же і стра́ждущим ісціле́ніє, да благода́рственно всі вопіє́м ди́вному во святи́х Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще по́двиги твоєго́ во́льнаго муче́нія за Христа́, покланя́ємся страда́нію твоєму́, великому́ченице досточу́дная, почита́єм святу́ю кончи́ну твою́ і мо́лим тя, простри́ твою́ с небесе́ по́мощ і на нас, живу́щих во тьмі страсте́й і іскуше́ній і вопію́щих ті:","Ра́дуйся, великому́ченице свята́я;","ра́дуйся, прине́сшая ті́ло своє́ в богоприя́тную же́ртву во многообра́зних муче́ніїх.","Ра́дуйся, го́рлице, взлетевшая во Ієрусали́м Ви́шній;","ра́дуйся, чи́стая і непоро́чная неві́сто Христо́ва.","Ра́дуйся, кади́льнице духо́вная, фиміа́м моли́тви о нас к Бо́гу принося́щая;","ра́дуйся, сокровищнице ісціле́ній неоску́дная.","Ра́дуйся, ча́ше даро́в Бо́жиїх преізоби́льная;","ра́дуйся, всіх благи́х жела́ній ско́рая ісполнительнице.","Ра́дуйся, сві́тлий о́бразе житія́ всім ча́ющим спасе́нія.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 13","ps":["О многострада́льная і преди́вная свята́я великому́ченице Анастасі́є! Ни́нішнєє на́ше ма́лоє моле́ніє прийми́ от недосто́йних раб твої́х, с любо́вію приноси́моє тебі́, і іспроси́ нам у Христа́ Бо́га гріхо́вних уз разріше́ніє, да ізба́вимся моли́твами твої́ми гні́ва Бо́жия і ві́чнаго осужде́нія, і да удосто́їмся в Небе́сном Ца́рствії ку́пно с тобо́ю во ві́ки пі́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом уподо́билася єси́ ра́зумом чи́стим, позна́вши Того́, І́же єсть всего́ ви́димаго і неви́димаго ві́чноє нача́ло і єди́ний коне́ць жела́ній всіх благочести́вих; ми же, восхваля́юще му́дроє обуче́ніє твоє́ от свята́го му́ченика Хрисого́на, с любо́вію вопіє́м ті:","Ра́дуйся, возлюби́вшая ві́ру Христо́ву;","ра́дуйся, последовавшая благоче́стію ма́тере твоєя́ Фавсти.","Ра́дуйся, соблю́дшая чистоту́ ді́вства твоєго́;","ра́дуйся, всегда́ неви́димо охраняємая А́нгелами.","Ра́дуйся, чистото́ю твоє́ю к Бо́гу приблизившаяся.","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нній уго́днице Христо́вой, всеблаженней великому́ченице Анастасі́ї похва́льноє пі́ніє прино́сим, я́ко іму́щей мно́гоє дерзнове́ніє ко Го́споду є́же от вся́ких бід, скорбе́й і болі́зней свобожда́ти ві́рния, і с любо́вію взива́єм си́це:","Ра́дуйся, всеблаже́нная великому́ченице Анастасі́є, у́зников свята́я посіти́тельнице і моли́твеннице о душа́х на́ших."]},{"h":"Молитва","ps":["О, многострада́льная і прему́драя великому́ченице Христо́ва Анастасі́є! Ти душе́ю на Небесі́ у Престо́ла Госпо́дня предстої́ши, на землі́ же да́нною тебі́ благода́тію разли́чная соверша́єши ісціле́нія; при́зри у́бо ми́лостивно на предстоя́щия лю́ди і моля́щіяся пред іко́ною твоє́ю, прося́щия твоєя́ по́мощі, простри́ ко Го́споду святи́я моли́тви о нас і іспроси́ нам оставле́ніє согріше́ній на́ших, по́мощі в труда́х милосе́рдих, укрепле́нія ду́ха в служе́нії, кро́тости, смире́нія і послуша́нія, неду́жним ісціле́ніє, скорб'я́щим і во у́зах су́щим ско́рую по́мощ і заступле́ніє, умоли́ Го́спода, да пода́сть всім нам христия́нськую кончи́ну і до́брий отві́т на Стра́шнім Суди́щі Своє́м, да сподо́бимся і ми ку́пно с тобо́ю сла́вити Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Побідоно́снаго Воскресе́нія / істинноімени́тая нарече́на єси́, му́ченице Христо́ва, / побі́ди на враги́ поста́вила єси́ мук терпі́нієм, / Христа́ ра́ди, Жениха́ твоєго́, / Єго́же возлюби́ла єси́. / Того́ моли́ // спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["Во іскуше́ніїх і ско́рбіх су́щії, / к твоєму́ хра́му притека́юще, / приє́млють честна́я дарова́нія / от живу́щия в тебі́ Боже́ственния благода́ті, Анастасі́є: // ти бо при́сно ми́ру то́чиши ісціле́нія."]},{"h":"Величання","ps":["Велича́єм тя, / страстоте́рпиця Христо́ва Анастасі́є, / і чтим честно́є страда́ніє твоє́, / я́же за Христа́ // претерпі́ла єси́."]}],"notes":[]},{"u":"Акафіст преподобному Пімену, архімандриту Угрешському","e":"Akathist to our Venerable Father Pimen, Archimandrite of Ugresha","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от Воєво́ди Сил Небе́сних Го́спода Ісу́са Христа́, оби́телі Угре́шськия возобнови́телю, преподо́бне о́тче наш Пи́мене, я́ко імі́яй ве́ліє дерзнове́ніє к Бо́гу, моли́ся ви́ну о спасе́нії душ на́ших і ізбавле́нії нас от вся́ких бід і напа́стей, да зове́м ті:","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Ікос 1","ps":["А́нгельський о́браз от ю́ности возлюби́в, всего́ себе́ преда́л єси́ Го́споду і ми́ра злоко́зненнаго отре́клся єси́, і бил єси́ і́стинний мона́х. Сего́ ра́ди ми воспіва́єм ті си́це:","Ра́дуйся, родителями твої́ми во благоче́стії возраще́нний,","Ра́дуйся, Отця́ Небе́снаго си́не, благода́тію озаре́нний.","Ра́дуйся, земно́є оте́чество твоє́, град Во́логду, свя́тостію просла́вивий,","Ра́дуйся, к Небе́сному Оте́честву от ю́ности устреми́вийся.","Ра́дуйся, Свяще́нноє Писа́ніє, єще́ о́трок сий, чита́ти возлюби́вий,","Ра́дуйся, Алфави́ть Духо́вний ізуча́я, за́повіді Бо́жії позна́вий.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 2","ps":["Ви́дя мно́жество страсте́й от ди́явола, бо́рющих тя, преподо́бне Пи́мене, возопи́л єси́ ко Го́споду і, получи́в благода́тную по́мощ, Тому́ воспі́л єси́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Бо́жий жела́я хотя́ отча́сти уразумі́ти, преподо́бне Пи́мене, Свяще́нноє Писа́ніє усе́рдно чита́л єси́ єще́ юн сий і в ста́рости масти́тій, сего́ ра́ди Бог іско́мому тя приобщи́. Ми же, своє́ неві́жество разумі́юще, глаго́лем ті:","Ра́дуйся, во о́трочестві ста́рцем Бо́жиїм во благоче́стії наста́вленний,","Ра́дуйся, от ю́ности нави́кнувий богоуго́дному добронра́вію;","Ра́дуйся, Феофа́на Новоє́зерськаго і Льва О́птинськаго зрі́ти і слу́шати сподо́бльшийся.","Ра́дуйся, блаже́ннаго Никола́я Волого́дськаго предрече́нія удосто́ївийся.","Ра́дуйся, к Анто́нію Ра́донежському сові́т імі́вий,","Ра́дуйся, святи́теля Філаре́та Моско́вськаго благослове́ніє на устроє́ніє общежи́тія іспо́лнивий.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 3","ps":["Си́лою Бо́га Всеви́шняго, все́льшеюся в тя, преподо́бне Пи́мене, возлюби́л єси́ бли́жніх і яви́лся єси́ а́лчущим пита́тель, ни́щим і си́рим защи́тник, неду́гующим помо́щник, поя́ Пода́телю всіх благ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я і́скреннєє послуша́ніє ко святи́телю Филаре́ту, преподо́бне Пи́мене, Угре́шськую оби́тель обнови́л єси́ і я́ко іну́ю Ла́вру соді́лал єси́, сего́ ра́ди ми благода́рственно поє́м ті:","Ра́дуйся, приби́во в Угре́шськую оби́тель, а́нгельськоє пі́ніє усли́шавий,","Ра́дуйся, сіє́ пі́ніє, я́ко благода́ть, до кончи́ни в се́рдці сохрани́вий.","Ра́дуйся, мона́шеськоє общежи́тіє во Угре́шстей оби́телі учреди́вий,","Ра́дуйся, сіє́, я́ко найлу́чшій путь ко спасе́нію, просла́вивий.","Ра́дуйся, виді́нієм птиць ве́ліїх, на Угре́шу летя́щих, обра́дованний,","Ра́дуйся, сіє́ виді́ніє, я́ко зна́меніє благоволе́нія Бо́жия, прия́вий.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 4","ps":["Бу́ря недоумі́нія смуща́єть мі ум, ка́ко по достоя́нію воспі́ти труди́ твоя́, преподо́бне о́тче Пи́мене, ї́миже труди́лся єси́ во сла́ву Єди́наго І́стиннаго Бо́га. Єму́же ми со а́нгели воспіва́єм: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше благочести́вії лю́діє о труді́х і по́двизіх твої́х, преподо́бне Пи́мене, притеко́ша к тебі́, я́ко і́стинному па́стирю, і принесо́ша да́ри, да обнови́ши Угре́шськую оби́тель. Ми же, я́ко дар, прино́сим тебі́ хвали́ сія́:","Ра́дуйся, к покая́нію во грісі́х і смире́нію лю́ди приводя́й,","Ра́дуйся, во о́них упова́ніє о спасе́нії в Бо́зі утвержда́яй.","Ра́дуйся, дара́ми благоді́телей Угре́шеськую оби́тель обнови́вий,","Ра́дуйся, сердца́ тіх па́стирською любо́вію согре́вий.","Ра́дуйся, благоді́телем Угре́шськия оби́телі би́вий і́стинний наста́вниче,","Ра́дуйся, о тіх при́сний богомо́льниче.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́ мно́жеству мона́хов, преподо́бне Пи́мене, наставля́я і окормля́я їх ко спасе́нію і науча́я при́сно Бо́гу взива́ти: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше жела́ющії житія́ і́ночеськаго, я́ко во Угре́шстей оби́телі общежи́тіє мона́шеськоє і благочи́ніє храни́мо єсть тобо́ю, преподо́бне Пи́мене, стека́хуся во мно́жестві к тебі́. Ми же, прославля́юще о тебі́ Го́спода Бо́га, вопіє́м ті:","Ра́дуйся, равноа́нгельнаго житія́ о́браз і́стинний нам яви́вий;","Ра́дуйся, жа́ждавших вступи́ти на путь і́ночеський с любо́вію во оби́тель прийма́вий.","Ра́дуйся, провини́вшихся і́ноков увеща́ньми свої́ми к сле́зному раска́янію приводи́вий;","Ра́дуйся, о́вці Христо́ви на живоно́сних па́житіх воспита́вий;","Ра́дуйся, і́ночеськаго общежи́тія велегла́сний пропові́дниче;","Ра́дуйся, па́стви твоєя́ до́брий наста́вниче.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 6","ps":["Пропові́дници Христа́ Бо́га би́вше ученици́ Угре́шськаго учи́лища благодари́ша тя, преподо́бне Пи́мене, я́ко і́стиннаго отця́ і учи́теля, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ в землі́ Моско́встей, преподо́бне Пи́мене, я́ко світи́льник, Бо́гом возже́нний, тім же мно́жество люде́й стека́хуся во Угре́шськую оби́тель ви́діти і сли́шати тя. Ми же, па́м'ять твою́ творя́ще, вопіє́м си́це:","Ра́дуйся, Моско́встей землі́ негаси́мий світи́льниче,","Ра́дуйся, сві́том Христо́вим просвіща́яй ду́ші на́ша.","Ра́дуйся, обурева́ємим душе́вними скорбми́ уті́шителю,","Ра́дуйся, неду́гующим болі́зньми помо́щниче.","Ра́дуйся, от находя́щих обстоя́ній моли́твою огражда́яй,","Ра́дуйся, о прося́щих по́мощі Бо́жієй хода́тайствуяй.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 7","ps":["Хотя́ ду́шу твою́ спасти́, мир Бо́жий стяжа́л єси́ внутр себі́, преподо́бне Пи́мене, ті́мже і спаса́хуся о́крест тебі́ мно́жество душ, благода́рственно пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя Пи́мена почита́єм, преподо́бне о́тче, наста́вника мона́хов і собесі́дника а́нгелов, ста́до слове́сноє, вруче́нноє ті Бо́гом, до́брі пасу́ща. Сего́ ра́ди ублажа́єм тя, вопію́ще:","Ра́дуйся, слове́сних ове́ць до́брий па́стирю,","Ра́дуйся, тезоіме́нному ті Пи́мену Вели́кому подража́телю.","Ра́дуйся, труди́ ра́ди Бо́га і бли́жняго возлюби́вий,","Ра́дуйся, пра́зден нікогда́же преби́вий.","Ра́дуйся, о грісі́х і не́мощіх твої́х рида́вий,","Ра́дуйся, па́ству к покая́нію призива́вий.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 8","ps":["Стра́нника і прише́льця себе́ на землі́ би́ти помишля́я, час кончи́ни твоєя́ пред очи́ма твої́ма при́сно імі́л єси́ і сего́ ра́ди к ві́чному животу́ стреми́лся єси́, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Бил єси́ всім воі́стину па́стир до́брий, преподо́бне Пи́мене, та́же і пита́тель, помо́щник і защи́тник, нам же ни́ні ти єси́ моли́твенник усе́рдний і хода́тай у престо́ла Влади́чня, сего́ ра́ди восхваля́єм тя си́це:","Ра́дуйся, па́стирською любо́вію приходя́щих к тебі́ об'є́млющий,","Ра́дуйся, упова́нієм о Христі́ о́ния ра́дующий.","Ра́дуйся, а́лчущих безме́здний пита́телю.","Ра́дуйся, нужда́ющимся странноприї́мници устрої́телю.","Ра́дуйся, найпа́че о душа́х пасо́мих пеки́йся.","Ра́дуйся, і тіле́сния ну́жди тіх забо́тою не оставля́яй.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 9","ps":["Вся́кия ско́рби і болі́зні со смире́нієм претерпі́л єси́, преподо́бне Пи́мене, нікогда́же прекосло́в'я во́лі Госпо́дней, но благода́рственно поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многоуче́ния недоуміва́ють, ка́ко ублажа́ти тя, преподо́бне Пи́мене, не от челові́чеськія му́дрости, но от прему́дрости Бо́жия ра́зум прия́вшего, сего́ ра́ди ми возглаша́єм ті сицева́я:","Ра́дуйся, во Христі́ Прему́дрость Бо́жию возлюби́вий,","Ра́дуйся, діла́ми за́повіді Бо́жії позна́вий.","Ра́дуйся, лі́ствицю доброді́телей зако́нно проше́дий,","Ра́дуйся, нищету́ ду́ха і смире́ніє во главу́ у́гла поста́вивий.","Ра́дуйся, ско́рби і болі́зні с терпі́нієм понеси́й,","Ра́дуйся, проще́нія проси́ти у ме́ньших себ'я́ нави́кнувий.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 10","ps":["Спасти́ся в Бо́зі хотя́й, всего́ себе́ покори́л єси́ во́лі Бо́жієй і да́же до сме́рти нічто́же о себі́ висо́кая поми́слил єси́, преподо́бне Пи́мене, но я́ко раб тружда́яся по вся дні, син Бо́жий по благода́ті во Ца́рствії Небе́снім яви́лся єси́, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ мона́хом, прибега́ющим с ві́рою к тебі́, преподо́бне Пи́мене, і́бо ді́лом і сло́вом о і́ночеськом житії́ ревнова́л єси́, тім же і нас, по́двиги твоя́ ублажа́ющих, от вся́ких напа́стей защити́, вопію́щих к тебі́ такова́я:","Ра́дуйся, мона́шеськоє зва́ніє і благоче́стіє возлюби́вий,","Ра́дуйся, є́же утверди́ти общежи́тіє в монастирі́х Моско́вських ревнова́вий.","Ра́дуйся, благогові́йний Та́їн Бо́жиїх служи́телю,","Ра́дуйся, церко́вного уста́ва стро́гий блюсти́телю.","Ра́дуйся, ко клевета́вшим на тя благоду́шіє стяжа́вий,","Ра́дуйся, на во́лю Бо́жию, но не челові́чеськую полага́вийся.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 11","ps":["Пі́ніє святи́телю Никола́ю со усе́рдієм приноси́л єси́, преподо́бне Пи́мене, оби́тель того́ обновля́я і лю́ди ко прославле́нію чуде́с того́ призива́я і науча́я о всіх і за вся благодари́ти Бо́га: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную лучу́ во мра́ці разоре́нія Угре́шськия оби́телі от безбо́жних зрим тя, преподо́бне Пи́мене, ти бо не убоя́вся ску́дости веще́ственния, до́брий і іску́сний строї́тель тоя́ бил єси́, о́браз упова́нія на Бо́га нам явля́я, сего́ ра́ди восхваля́єм тя си́це:","Ра́дуйся, Угре́шськия оби́телі возобнови́телю,","Ра́дуйся, і нам во возрожде́нії тоя́ помога́ющий.","Ра́дуйся, труда́ми, болі́зньми і моли́твою бра́тію во Угре́шськую оби́тель собра́вий,","Ра́дуйся, і ни́ні о бра́тії оби́телі твоєя́ усе́рдно моля́щийся.","Ра́дуйся, жив сий, все упова́ніє твоє́ на Бо́га возложи́вий,","Ра́дуйся, в преставле́нії твоє́м к Бо́гу нас не оставля́ющий.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 12","ps":["Благода́ть Ду́ха Свята́го стяжа́в, ще́дро всім тре́бующим подає́ши, преподо́бне Пи́мене, і ни́ні, со дерзнове́нієм престо́лу Бо́жию предстоя́, мо́лишися о нас, пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще обрі́теніє честни́х моще́й твої́х, преподо́бне Пи́мене, і благода́тную по́мощ, тобо́ю подава́ємую нам, прославля́єм Бо́га, прославля́ющего святи́я Своя́ і воспіва́єм тебі́ си́це:","Ра́дуйся, от святи́теля Філаре́та благослове́ніє Бо́жиє на обновле́ніє Угре́шськия оби́телі получи́вий,","Ра́дуйся, я́ко сам ни́ні в со́нном виді́нії па́ки возобнови́ти оби́тель повелі́вий.","Ра́дуйся, я́ко у мі́ста погребе́нія твоєго́ а́нгельськоє пі́ніє сли́шано бисть,","Ра́дуйся, я́ко честни́я мо́щі твоя́ ни́ні чудоді́йствують.","Ра́дуйся, я́ко у престо́ла Бо́жия об оби́телі твоє́й хода́тайствуєши,","Ра́дуйся, я́ко і за всіх моля́щихся тебі́ те́плі предста́тельствуєши.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 13","ps":["О па́стирю до́брий / і ревни́телю мона́шеського чи́на, / об Угре́шськия оби́телі при́сний хода́таю на Небесі́, / преподо́бне Пи́мене, / ни́нішнія на́ша прийми́ приноше́нія / і моли́ Христа́ Бо́га ізба́витися нам ві́чнаго осужде́нія, / да предстоя́ одесну́ю Єго́, / с тобо́ю воспіва́єм: // Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельський о́браз от ю́ности возлюби́в, всего́ себе́ преда́л єси́ Го́споду і ми́ра злоко́зненнаго отре́клся єси́, і бил єси́ і́стинний мона́х. Сего́ ра́ди ми воспіва́єм ті си́це:","Ра́дуйся, роди́телями твої́ми во благоче́стії возраще́нний,","Ра́дуйся, Отця́ Небе́снаго си́не, благода́тію озаре́нний.","Ра́дуйся, земно́є оте́чество твоє́, град Во́логду, свя́тостью просла́вивий,","Ра́дуйся, к Небе́сному Оте́честву от ю́ности устреми́вийся.","Ра́дуйся, Свяще́нноє Писа́ніє, єще́ о́трок сий, чита́ти возлюби́вий.","Ра́дуйся, Алфави́ть Духо́вний ізуча́я, за́повіді Бо́жії позна́вий.","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Кондак 1","ps":["Ізбра́нний от Воєво́ди Сил Небе́сних Го́спода Ісу́са Христа́, оби́телі Угре́шськия возобнови́телю, преподо́бне о́тче наш Пи́мене, я́ко імі́яй ве́ліє дерзнове́ніє к Бо́гу, моли́ся ви́ну о спасе́нії душ на́ших і ізба́вленії нас от вся́ких бід і напа́стей, да зове́м ті:","Ра́дуйся, Пи́мене, те́плий о нас пред Бо́гом моли́твенниче."]},{"h":"Молитва","ps":["О свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Пи́мене! Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х твої́х і благоприя́тних моли́твах к Бо́гу. Пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́; не премолчи́ за ни ко Го́споду і не пре́зри нас, ві́рою і любо́вію чту́щих тя. Помина́й нас, недосто́йних, у престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу; і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва; а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия і ко́зней дия́вольських, па́стирю наш до́брий. А́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со а́нгельськими во́їнстви, со безпло́тними ли́ки, с небе́сними си́лами, у престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться. Ві́дуще у́бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу о по́льзі душ на́ших і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на не́бо, от мита́рств же го́рких, бісо́во возду́шних князе́й і от ві́чной му́ки да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́: Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 2","ps":["Мона́шеськоє житіє́ от ю́ности возлюби́в, / во оби́тель Угре́шськую всели́лся єси́, / іді́же труди́ ко трудо́м прилага́я, / мона́хов мно́жество собра́л єси́, / ї́хже сердца́ согріва́я і тяготи́ нося́, / путе́м Христо́вим ше́ствовал єси́. / Пи́мене преподо́бне, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 1","ps":["Тобо́ю, преподо́бне о́тче Пи́мене, / оби́тель Угре́шськая благослове́нієм Бо́жиїм процві́тшая, / па́м'ять твою́ ни́ні пра́зднуєть / і лику́ющи зове́ть ті; / сла́ва Да́вшему тебі́ крі́пость, / сла́ва Вінча́вшему тя, // сла́ва Ді́йствующему тобо́ю всім ісціле́нія."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Пи́мене, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Никифору Прокаженному","e":"Akathist to our Venerable Father Nicephorus the Leper","secs":[{"h":"Кондак 1","ps":["Ізбра́ннаго во́їна Влади́ки Небе́снаго, адама́нта терпі́нія, небосветлую ста́мну Свята́го Ду́ха, сше́дшеся, ві́рнії, да восхва́лим. Ти же, преми́рний о́тче, я́ко о́бщник страда́ній на́шего Іскупи́теля, дерзнове́нно моли́ся о нас, прокаже́нних страстьми́, да зове́м ті:","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Ікос 1","ps":["А́нгельськую душі́ чистоту́ і к ви́шнім стремле́ніє ізді́тська яви́л єси́, преподо́бне, ті́мже ми́ра Зижди́тель лише́ньми тя в часть Себі́ отділи́ і в ча́до возлю́бленноє восприя́. Ти же, ді́тище благоуго́дливоє бив, от земни́х роди́телей сиро́тноє, оба́че Бо́га отце́м неразлу́чно іме́вшеє, ни́ні от нас прийми́ славосло́вія сицева́я:","Ра́дуйся, і́мже уті́шаться ско́рбная сердца́;","ра́дуйся, і́мже стра́ждущії просла́в'ять Творця́.","Ра́дуйся, кро́тостію от ю́ности преудобре́нний;","ра́дуйся, послуша́нієм преукраше́нний.","Ра́дуйся, к житію́ кре́стному от ю́ности предизбра́нний;","ра́дуйся, к по́двигу доблему́дренному призва́нний.","Ра́дуйся, ти́хостноє і незло́бивоє отроча́;","ра́дуйся, на па́житіх смиренному́дрія упасе́нноє овча́.","Ра́дуйся, я́ко в ско́рбіх і болі́зніх ру́ці о нас воздіва́єши;","ра́дуйся, я́ко крестоноше́нію ві́рния науча́єши.","Ра́дуйся, кри́тяном те́плоє заступле́ніє;","ра́дуйся, малоду́шним нам в біда́х укріпле́ніє.","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Кондак 2","ps":["Ви́дя тя Бог челові́ка і́стинна, непоро́чна, пра́ведна, ве́ліє іспита́ніє тебі́ посила́єть, а́ки зла́то в горни́лі тя іскуша́я, я́ко да І́овле крепкоду́шіє во о́браз всім ві́рним яви́ши, і́мже і стал єси́ проти́ву уни́нія волн, находя́щих на тя, єгда́ я́зя прока́зи на ті́лі твоє́м узрі́ся. Тім, сію́ потаї́ти хотя́, на чужеда́льній кора́бль восхо́диши і гра́да Александрі́ї достиза́єши. Ми же, упова́ніє твоє́ на Єди́наго Благоутро́бнаго зря́ще, вопіє́м Тому́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом любому́дрим слу́жби Бо́жия во гра́ді вели́цім воспіва́єши, отону́дуже і во Святу́ю Зе́млю во ісполне́ніє жела́нія твоєго́ те́плаго преплива́єши, та́мо пред Кресто́м Христо́вим і Гробо́м Єго́ живоно́сним моли́тви серде́чния вознося́ і глубину́ печа́лі своєя́ обнажа́я. Ті́мже, в Александрі́ю обрати́вся, єди́ному от архієре́єв ту́гу свою́ іспове́даєши і на Хіо́с ко свято́му Анфи́му а́біє отсила́єшися. Ми же, прему́дрому Про́мислу о тебі́ див'я́щеся, воспіва́єм:","Ра́дуйся, в ско́рбі вели́цій наде́ждою на Отця́ Небе́снаго себі́ огражда́яй;","ра́дуйся, в печа́лі денноно́щно моли́тву серде́чную пролива́яй.","Ра́дуйся, сладкопі́снивий Це́ркве Христо́ви сла́віє;","ра́дуйся, рук воздія́нієм низпосила́яй разсла́бленним здра́віє.","Ра́дуйся, лі́потою піснопі́ній свяще́нних ізмла́да пліне́нний;","ра́дуйся, ангелогла́сним мно́гими нарече́нний.","Ра́дуйся, неду́гом прия́вий Бо́жиє всиновле́ніє;","ра́дуйся, в не́мощі яви́вий Єва́нгельських доброді́телей прозябе́нія.","Ра́дуйся, я́ко бисть Весе́ліє се́рдця тебі́ Ісу́с Сладча́йший;","ра́дуйся, пе́рвіє бив отре́біє ми́ру, ни́ні же єму́ — дар височа́йший.","Ра́дуйся, єго́же побі́дами Хіо́с велича́ється;","ра́дуйся, єго́же жи́тельством ко́зні вра́жия облича́ються.","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго укріпля́єм, во ото́ці Хіо́сстем на мно́гая лі́та водворя́єшися, і зді, я́ко А́нгела Бо́жия, тя преподо́бний Анфи́м сріта́єть, в наро́читую прокаже́нних враче́бницю тя поселя́я, ра́ни твоя́ тіле́сния об'язу́я і духо́вноє попече́ніє взе́мля о крестоно́сней душі́ твоє́й. Ти же, такови́я ми́лости от во́лею Расп'я́таго і Єго́ уго́дника приє́мля, благода́рственная воспису́єши: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ве́ліє ко хра́му Бо́жию усе́рдіє, в це́рквиці свята́го Ла́заря, дру́га Госпо́дня, у лече́бници на всяк день в моле́ніїх і пі́ніїх привита́єши, пред іко́ною ди́вною Богоро́диці от се́рдця, ско́рбію тесни́маго, вопія́. Єя́ же чудеси́ не то́кмо на ха́ртії, но і в душі́ напечатле́в і благоутро́бія бе́здни от Всеми́лостивия восприя́т, не преста́й і ни́ні ру́ці к Ней простира́ти о спасе́нії нас, вознося́щих ті сицева́я:","Ра́дуйся, Це́рковію Бо́жиєю воспита́нний;","ра́дуйся, ма́нною слове́с Єва́нгельських препита́нний.","Ра́дуйся, я́ко ціли́ши печа́лі лю́тоє неможе́ніє;","ра́дуйся, я́ко хода́тайстви врачу́єши уни́нія сме́ртноє болі́ніє.","Ра́дуйся, я́ко душе́вния на́ші стру́пи моли́твою за ни ум'ягча́єши;","ра́дуйся, я́ко разсла́бленния ті́лом і неради́вия бо́дростію своє́ю духо́вною возставля́єши.","Ра́дуйся, удаля́яйся от вся́кия лука́вия ве́щі;","ра́дуйся, ізведе́нний от ми́сленнаго Єги́пта желі́зния пе́щі.","Ра́дуйся, Богоро́дице сві́тлоє гласова́ніє;","ра́дуйся, ум огради́вий Свяще́нним Писа́нієм.","Ра́дуйся, о́бразе і пра́вило Бо́жиїх песнопе́вцев;","ра́дуйся, соприча́стниче страстоте́рпцев.","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Кондак 4","ps":["Бу́рю см'яте́ній і попече́ній мирськи́х на приста́нище ти́хоє преміни́л єси́, і, гнуша́єм от челові́к, маргари́ть драгоці́нний Всетворцю́ показа́ся. Тім, нічесо́же стяжа́в, сокро́вищем му́дрих сові́тов от богопросвеще́ннаго ста́рця і писа́ній святооте́чеських обогаща́єшися, непреста́нно хваля́ та́ко к по́льзі душе́вній Устро́ївшаго: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Христо́с Многоми́лостивий моли́тви твоя́ і зря се́рдця твоєго́ сокруше́ніє, ру́ку к тебі́ простира́єть: прийди́ ко Мні, ча́до тружда́ющеєся і обремене́нноє, і Аз упоко́ю тя. Ти же, от отця́ духо́внаго постриже́ніє восприї́м, взем і́го Госпо́днє благо́є на ра́мо, кро́тости і смире́нію по вся дні от Него́ науча́шеся і благода́рственная возноша́ше. Ми же, такови́м щедро́там Спа́са див'я́щеся, похва́льная ті воспіва́єм:","Ра́дуйся, в но́ваго челові́ка богосотворе́ннаго облече́нний;","ра́дуйся, во оде́жду весе́лія оболче́нний.","Ра́дуйся, цілому́дрія ди́вноє благоуха́ніє;","ра́дуйся, по́мощі Бо́жия прия́вий обітова́ніє.","Ра́дуйся, горково́дная ми́ра Кресто́м Христо́вим услади́вий;","ра́дуйся, себі́ укоре́ніє в краєуго́льний ка́мень терпі́нія положи́вий.","Ра́дуйся, житія́ су́єтнаго печа́лей Про́мислом отсіче́нний;","ра́дуйся, не ктому́ себі́ жи́ти, но Уме́ршему за ни і Воскре́сшему посвяще́нний.","Ра́дуйся, в ру́ці Созда́теля всеці́ло себі́ преда́вий;","ра́дуйся, во́лі своєя́ отверже́нія возжела́вий.","Ра́дуйся, я́ко тобо́ю мона́шеський лик украша́ється;","ра́дуйся, я́ко тобо́ю су́щії в лю́тих не́мощіх укріпля́ються.","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Кондак 5","ps":["Боготе́чно твоє́ житіє́ і преди́вно яви́ся, к разсужде́нію бо послуша́нієм устреми́лся єси́, преподо́бне, в лече́бней кали́бице, я́ко в пусти́ні, со страстьми́, я́ко звірми́ до́блественне боря́ся, побіжда́я і побежда́яся, па́дая і возставая, моли́тви ніка́коже отступа́я і простира́я дла́ни своя́ Просте́ршему дла́ни Боже́ственнії на Пречи́стім і Живоно́снім Кре́сте, я́ко да в бу́дущем Ца́рстві Єго́ пі́ти возмо́жеши немо́лчноє: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дим тя, преподо́бне о́тче, вертогра́даря, цві́ти прекра́сния і древа́ благови́дная ізраща́юща, Ви́шнему же Вертогра́дарю доброді́телей сад преіспещре́нний, посреді́ те́рній, скорбе́й і напа́стей процві́тшій. Ті́мже, уго́дниче Бо́жий і ди́вний о́тче, припа́дающе к стопа́м твої́м, про́сим: Тро́йце Пресвяті́й благосе́рдствуй о нас, я́ко да согріше́нія своя́ у́зрим і, покая́нієм умудре́ннії, не преста́нем, благодаря́ще, возсила́ти тебі́ такова́я:","Ра́дуйся, я́ко от ко́рене повинове́нія смире́ніє прораща́єши;","ра́дуйся, я́ко на ві́тві духо́вній я́коже но́вий крин прозяба́єши.","Ра́дуйся, бді́нія і трезві́нія ди́вноє благоуха́ніє;","ра́дуйся, терпеливоду́шію ві́ру вміни́вий во основа́ніє.","Ра́дуйся, розго́, отребле́нная Ви́шнім, ті́мже і многопло́дная;","ра́дуйся, гріхми́ іссуше́нним ріко́ многово́дная.","Ра́дуйся, умо́м зловре́днаго цілому́дренно отбега́яй;","ра́дуйся, Свяще́нним Писа́нієм при́сно внима́яй.","Ра́дуйся, я́коже кипари́с, посреді́ хла́да мук благоду́шієм зелене́єши;","ра́дуйся, я́коже медуни́ця мироуха́нная, пред Зижди́телем благогові́єши.","Ра́дуйся, от єго́же усте́н Госпо́дня хвала́ возсила́ється;","ра́дуйся, і́мже стропти́вії і ропотли́вії славосло́вію науча́ються.","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жних ско́рий помо́щниче."]},{"h":"Кондак 6","ps":["Пропові́дник святооте́чеських мона́шеських ді́ланій явля́ється ті богогла́сний Анфи́м, ко трезве́нію, стра́ху Бо́жию, па́м'яті сме́ртній і молча́нію тя управля́я, і та́ко за́повідьми Єва́нгельськими устроя́єть душе́вния стру́ни твоя́, я́ко да мусикі́йськая Ду́ху Свято́му цівни́ця соде́лаєшися, і о тебі́ воспіва́єть Тро́йце Пресвяті́й: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в тебі́ ра́зум і́стинний, і́мже вся́чеськи к послуша́нію устреми́лся єси́, богоно́се, открове́ніє бо стяжа́л єси́, о́тче, і́скреннєє, по́мисли істязу́я, кормчему своєму́ корми́ло вручи́в і тім основа́ніє духо́внаго восхожде́нія полага́я; в такові́м преди́внем смире́нії пом'яну́ Тя Госпо́дь і украси́ доброді́тельми ду́шу твою́. Ті́мже от нас прийми́ такова́я:","Ра́дуйся, високому́дріє ми́ра в бу́йство вміни́вий;","ра́дуйся, Ісу́сову па́м'ять в се́рдці своє́м водрузи́вий.","Ра́дуйся, Христу́ подража́телю, нас ра́ди обнища́вшему;","ра́дуйся, о́бщниче пре́жде би́вшим отце́м, до́льній поко́й попра́вшим.","Ра́дуйся, Бо́жиїх ра́ди хоті́ній своя́ потреби́вий хоті́нія;","ра́дуйся, в простоті́ повину́яся, до́брі пре́йде тече́ніє.","Ра́дуйся, па́че ке́дра лива́нськаго в і́стиннім ді́ланії укорени́вийся;","ра́дуйся, Послушли́вому да́же до сме́рти кре́стния вослі́д устреми́вийся.","Ра́дуйся, я́ко псалти́р яснозву́чная, стезю́ к покая́нію воспіва́яй;","ра́дуйся, я́ко труба́ богогла́сная, неради́вия к ді́ланію пробужда́яй.","Ра́дуйся, і́ноком новонача́льним звіздо́ путево́дная;","ра́дуйся, путе́м істомле́нним дре́во висо́коє і сладкопло́дноє.","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Кондак 7","ps":["Хотя́щу ті за́повідь Єва́нгельськую іспо́лнити, во озлобле́нії болі́зненном вся́чеськи незло́бієм і благоду́шествієм сія́ше, многострада́льне о́тче Ники́форе, кади́ло Христу́ благово́нноє і приноше́ніє свято́є. Ті́мже бла́гості і братолю́бія дости́гл єси́ висоти́, Ду́хом Святи́м ісполня́яся, іни́м прокаже́нним, і́нокиням оби́телі Пренепоро́чния Помо́щници і нам, немощни́м, о́браз бив, ка́ко подоба́єть любо́вію к Бо́гу і бли́жнему преспіва́ти, с ни́миже вку́пі воспису́єм о тебі́ Ви́шнему: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий яви́ся І́ов, до́блестію в страда́ніїх і по́двигом великоду́шія вся боля́щия укріпля́яй і наставля́яй, Бо́гом возлю́бленний тру́дниче, мужему́дренний ратобо́рче, ти́хости і покорности во́лі Бо́жії о́бразе. Ті́мже, сам бив острупле́н, на́ша ра́ни благосе́рдними заступле́нії об'язу́єши, по достоя́нію воздаю́щих ті такова́я:","Ра́дуйся, душе́внаго ми́ра гу́сле согла́сная;","ра́дуйся, моли́тви серде́чния песне прекра́сная.","Ра́дуйся, душі́ своєя́ ри́зу слеза́ми радостотво́рними очища́яй;","ра́дуйся, пла́чем Вседержи́теля к ми́лости приклоня́яй.","Ра́дуйся, всеусе́рдно устреми́вийся к богоугожде́нію;","ра́дуйся, пред оча́ми Влади́ки обріти́й благоволе́ніє.","Ра́дуйся, уя́звленним самолю́бієм целе́бнейший пла́стирю;","ра́дуйся, блужда́ющим в по́хотіх пло́ті до́брий путевождю́ і па́стирю.","Ра́дуйся, я́ко Христо́с твоя́ при́сно соді́лася Ра́дость;","ра́дуйся, я́ко і́м'я Єго́ бисть тебі́ ви́шняя сла́дость.","Ра́дуйся, і́мже саможале́ніє і малоду́шіє ісправля́ються;","ра́дуйся, і́мже прему́дрость Про́мисла Бо́жия познава́ється.","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жних ско́рий помо́щниче."]},{"h":"Кондак 8","ps":["Стра́нен, преми́рні, ти показа́ся ми́ру, нечистоті́ єго́ не прикаса́яся, ті́мже і це́рков соді́лася Бо́гу Живу́, Дух бо Святи́й при́йде і всели́ся в тя, до́бляя му́жества глави́зно, і очи́сти тя от вся́кия скве́рни. Ти же, моли́твою священноді́йствуя і при́сно грі́шника себі́ мня, во удивле́нії зов'я́ше: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бі ура́нен, і в ребро́ прободе́н, і осліпле́н, благода́рною же душе́ю па́че со́лнця сія́я; злий же неду́г, я́ко мучи́тель, неща́дно тя істяза́ше. Оба́че у́дом твої́м отсекаємим, ти немо́лчно поя́ше: да бу́деть, Го́споди, же́ртва моя́ душе́вния благоприя́тна пред Тобо́ю. Не оста́ви, о́тче, предста́тельством нас, такові́й твоє́й до́блести ужасающихся, острупле́нних гріхми́, похотьми́ осліпле́нних, любо́вію Ті вопію́щих:","Ра́дуйся, Ви́шнему всесожже́ніє слове́сноє;","ра́дуйся, су́щим до́лу дарова́ніє Небе́сноє.","Ра́дуйся, па́костника пло́ті смире́нієм попали́вий;","ра́дуйся, тіле́сному крестоношенію ми́сленноє расп'я́тіє совокупи́вий.","Ра́дуйся, славосло́вія Всеще́драго кимвале богокра́сний;","ра́дуйся, трезві́нія орга́не златогла́сний.","Ра́дуйся, я́ко крепкостоянієм твої́м в ско́рбіх науча́ємся;","ра́дуйся, я́ко ху́достію риз твої́х вразумляємся.","Ра́дуйся, я́ко терпі́ніє ни́щаго Ла́заря показа́л єси́;","ра́дуйся, я́ко Мойсе́єву кро́тость яви́л єси́.","Ра́дуйся, уни́нієм істязує́мим духо́вная отра́до;","ра́дуйся, гні́вом жегомим Небе́сная прохладо.","Ра́дуйся, многотерпеливне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Кондак 9","ps":["Вся́коє благодаре́ніє поощря́єть Даю́щаго є́же умно́жити дарова́нія; твоя́ же душа́ в славосло́вії отню́д не престава́ше, сего́ ра́ди сви́ше вели́кия да́ри прия́л єси́, Ду́ха Свята́го сосу́де ізбра́нний. Іспроси́ нам в терпі́нії обстоя́ній поне́ ма́ло ті подража́ти, і в болі́зніх благода́рственная при́сно от се́рдця сокруше́ннаго Бо́гові возноси́ти: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я лжемудрствующия умолка́ють, недоумі́юще кре́стнаго житія́ си́ли: єли́ці бо Крест приє́млють жела́нієм, душе́вноє ісціле́ніє взе́млють. Ти же, преми́рний о́тче, от претерпе́нія ско́рби плотські́я к виді́нію і сла́ві Креста́ возше́л єси́ і ве́лію благода́ть притяжа́л єси́ болі́зні ціли́ти к тебі́ приходя́щих любо́вію і воспіва́ющих такова́я:","Ра́дуйся, благословля́яй Го́спода на вся́коє вре́м'я;","ра́дуйся, безро́потно пронеси́й тягча́йшеє бре́м'я.","Ра́дуйся, возненави́дівий сла́ву мимотеку́щую;","ра́дуйся, отве́ргий суєту́ многослову́щую.","Ра́дуйся, па́че бога́тства тлі́ннаго Христо́во поноше́ніє вміни́вий;","ра́дуйся, ті́сний путь благослови́вий.","Ра́дуйся, купе́ле Силоа́мськая разсла́бленним гріхми́;","ра́дуйся, цельбо́ ослепленним похотьми́.","Ра́дуйся, ломо́тния і опу́хольния болі́зні отгоня́яй;","ра́дуйся, мори губи́тельния уставля́яй.","Ра́дуйся, я́ко в прокаже́нней пло́ті А́нгельською чистото́ю сія́ше;","ра́дуйся, я́ко во озлобле́ніїх бла́гость явля́ше.","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ лю́ди Афи́нськия, душе́вними і тіле́сними болі́зньми стра́ждущия, Промисли́тель Прему́дрий тя, кротча́йший Ники́форе, я́ко а́нгела уті́шителя к ним посила́єть, наста́вник же твой словеси́ такови́ми свяще́ннику при лече́бниці Євме́нію тя предваря́єть: сей маргари́ть прекра́снійший, сокро́вище Бо́жиє і соверше́нна мона́ха ра́достію всі приймі́те, воздаю́ще Бо́гу по достоя́нію: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ соді́лался єси́ прокаже́нним і стра́ждущим во гра́ді Афи́нстем, ти́хостію і благоволе́нієм Апо́столу подража́я, во вся́цім внима́нії жи́тельствуя, к согла́сію, ми́ру, святи́не і благогове́нію вся наставля́я. Ті́мже і о́браз нам показа́лся єси́, є́же ка́ко подоба́єть серде́чним служе́нієм во псалмі́х, і пі́ніїх, і пі́сніх духо́вних преспіва́ти, сего́ ра́ди я́ко єди́німи усти́ возноси́м ті сицева́я:","Ра́дуйся, благодаре́нія ра́достію блиста́яй;","ра́дуйся, сострада́нія сві́тлостію вся увеселя́яй.","Ра́дуйся, Дави́довою простото́ю отгна́вий вра́жия злокова́рствія;","ра́дуйся, нището́ю ду́ха блаже́нство стяжа́вий Ві́чнаго Ца́рствія.","Ра́дуйся, суєсло́віє попали́вий молча́нієм;","ра́дуйся, малоду́шіє потреби́вий Ви́шняго велича́нієм.","Ра́дуйся, я́ко Єва́нгеліє достоя́ніє ума́ своєго́ сотвори́ся;","ра́дуйся, я́ко люби́ неотпа́дающая в тебі́ воцари́ся.","Ра́дуйся, я́ко к моле́нію непреста́нному ві́рния наставля́єши;","ра́дуйся, я́ко к духо́вному ра́зуму стра́ждущия управля́єши.","Ра́дуйся, в пе́щі безмі́рних болі́зней пали́мия ороси́вий;","ра́дуйся, мно́зі во глубині́ не́мощі су́щия ісціли́вий.","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє подоба́єть ті, моли́твенниче неуси́пний: служи́телю бо Євме́нію в ке́ллію к тебі́ та́йно вше́дшу, узрі́ тя на возду́сі моля́щася, і, разслабле́ніє члено́в твої́х, зрі́нія і ног лише́ніє ві́дая, ужа́сся той, возопи́в: Аллилу́я."]},{"h":"Ікос 11","ps":["Светосія́єть нам о́браз твой, і́менем і ді́ли побідоно́сче, к позна́нію не́мощі своєя́ нас, малоду́шних і ропотливих, управля́я і вразумля́я. Ті́мже недоумі́юще, ка́ко сме́ртній пло́ті твоє́й істлевающей, по вся дні обновляшеся, я́ко духодви́жная арфа, ви́ну богосла́вная бряця́я, диві́мся і прино́сим ті такова́я:","Ра́дуйся, любо́вію Христо́вою прободе́нний;","ра́дуйся, живоно́сним Кресто́м Єго́ оживотворе́нний.","Ра́дуйся, я́коже Данії́л во рву на Єди́наго упова́яй;","ра́дуйся, я́коже о́троци в пе́щі Благоутро́бнаго восхваля́яй.","Ра́дуйся, Це́ркве златокова́нний світи́льниче;","ра́дуйся, раче́нія є́же к Бо́гу таї́нниче.","Ра́дуйся, я́ко огне́м боленія ві́чнаго пла́мене ізбі́гл єси́;","ра́дуйся, я́ко си́лою Ду́ха не́мощ пло́ті препрі́л єси́.","Ра́дуйся, сладкопе́вче, А́нгелом собесі́дниче;","ра́дуйся, гу́сле моли́тви, благода́тния жи́зні снаслі́дниче.","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Кондак 12","ps":["Благода́ті чудотворе́ній ковче́г яви́лся єси́, богатода́рний о́тче, і по блаже́нній кончи́ні нас благоутро́бієм і по́мощію не оставля́єши. Всім же в ско́рбі к моще́м твої́м і о́бразу притекающим, подає́ши осла́бу душе́вную і тіле́сную, с ни́ми Всемилостивому́ возсила́я те́плоє: Аллилу́я."]},{"h":"Ікос 12","ps":["Пі́ніє всеумиле́нноє не престає́м приноси́ти тебі́, благоуві́тливий о́тче, ти же сіє́ прийми́ от недосто́йних усте́н і к Бо́гу ру́ці твоя́ воздіва́ти о нас не преста́й, вопію́щих ті такова́я:","Ра́дуйся, печа́льми болі́зненними обріти́й безпеча́льноє упокоє́ніє;","ра́дуйся, до конця́ претерпі́в, ра́йськая улучи́вий Селе́нія.","Ра́дуйся, гро́здіє, в точилі скорбе́й вино́ істочи́вшеє;","ра́дуйся, ми́ро, благоуха́нієм доброді́телей вся ни увесели́вшеє.","Ра́дуйся, то́ки чуде́с ізлива́яй;","ра́дуйся, ми́лостію к боля́щим не оскудіва́яй.","Ра́дуйся, муче́ній пучи́ну окормле́нієм Сло́ва препли́вий;","ра́дуйся, во́ї лука́ваго крепкоду́шієм погуби́вий.","Ра́дуйся, тряса́вицею і огне́вицею стра́ждущия уврачева́вий;","ра́дуйся, мно́гія біди́ от почита́ющих тя отгна́вий.","Ра́дуйся, ми́лостиве, блаже́нства Небе́снаго ни́ні наслажда́яяйся;","ра́дуйся, ни́щий ду́хом, благода́ті бога́тно при́сно причаща́яйся.","Ра́дуйся, многотерпеливне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Кондак 13","ps":["О богому́дре Ники́форе Прокаже́нний! Ти болі́зньми ссека́єм, неду́гами стру́жем, житіє́ на одрі́ болі́зні лю́тия препровожда́я, во́лю Бо́жию о Христі́ вся́ко іспо́лнил єси́, є́же єсть всегда́ ра́доватися, непреста́нно моли́тися, о всем благодари́ти. Ни́ні же, світоявле́нні, на́шу печа́ль утоли́ і у́хо твоє́ к проше́нієм на́шим ми́лостивно приклони́, і к ра́дованію, моли́тві і благодаре́нію упра́ви о тебі́ вопію́щия: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськую душі́ чистоту́ і к ви́шнім стремле́ніє ізді́тська яви́л єси́, преподо́бне, ті́мже ми́ра Зижди́тель лише́ньми тя в часть Себі́ отділи́ і в ча́до возлю́бленноє восприя́. Ти же, ді́тище благоуго́дливоє бив, от земни́х роди́телей сиро́тноє, оба́че Бо́га отце́м неразлу́чно іме́вшеє, ни́ні от нас прийми́ славосло́вія сицева́я:","Ра́дуйся, і́мже уті́шаться ско́рбная сердца́;","ра́дуйся, і́мже стра́ждущії просла́в'ять Творця́.","Ра́дуйся, кро́тостію от ю́ности преудобре́нний;","ра́дуйся, послуша́нієм преукраше́нний.","Ра́дуйся, к житію́ кре́стному от ю́ности предизбра́нний;","ра́дуйся, к по́двигу доблему́дренному призва́нний.","Ра́дуйся, ти́хостноє і незло́бивоє отроча́;","ра́дуйся, на па́житіх смиренному́дрія упасе́нноє овча́.","Ра́дуйся, я́ко в ско́рбіх і болі́зніх ру́ці о нас воздіва́єши;","ра́дуйся, я́ко крестоноше́нію ві́рния науча́єши.","Ра́дуйся, кри́тяном те́плоє заступле́ніє;","ра́дуйся, малоду́шним нам в біда́х укріпле́ніє.","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Кондак 1","ps":["Ізбра́ннаго во́їна Влади́ки Небе́снаго, адама́нта терпі́нія, небосветлую ста́мну Свята́го Ду́ха, сше́дшеся, ві́рнії, да восхва́лим. Ти же, преми́рний о́тче, я́ко о́бщник страда́ній на́шего Іскупи́теля, дерзнове́нно моли́ся о нас, прокаже́нних страстьми́, да зове́м ті:","Ра́дуйся, многотерпели́вне о́тче Ники́форе, неду́жним ско́рий помо́щниче."]},{"h":"Молитва","ps":["О, благода́рний страда́льче, моли́тви таї́нниче, ми́лостивий чудотво́рче, преподо́бне о́тче Ники́форе!","Кто у́бо терпі́нію, смире́нію, трезве́нію, благоуве́тливости, до́блести і кро́тостной прему́дрости твої́м не подиви́ться?","Ві́руєм, я́ко по преселе́нії твоє́м ко Го́споду ве́лію мзду улучи́л єси́ і мно́гою благода́тію обле́клся єси́, многоболі́зненния бо, стра́ждущия, нича́щия ни́зу, разсла́бленния, ни́щія і убо́гія заступле́нієм і попече́нієм свої́м не оставля́єши і мно́гая і ди́вная чудеса́ на них ізлива́єши.","Ті́мже, сам іскуше́н бив, помози́ і нам, страстьми́, і похотьми́, і своєволієм іскуша́ємим. Ві́ми, я́ко вся находя́щая на ни гріх ра́ди на́ших восприя́хом. Оба́че дерзнове́нним заступле́нієм твої́м пред Человеколюбцем воздви́гни ни, в пучи́ні не́мощей обдержи́мия, возста́ви на одрі́ озлобле́нія су́щия, облегчи́ неду́ги, здра́вія іспроси́, болі́зні укроти́, утіше́ніє боже́ственноє да́руй.","Припади́ в Небе́сних Черто́зіх к подно́жію но́гу на́шего Іскупи́теля, не преста́й воздіва́ти ру́ці твої́ о нас, недосто́йних і окая́нних, по вся дні па́дающих і возстаю́щих, оба́че наде́жди на Єго́ милосе́рдіє не оставля́ющих, я́ко да твої́ми хода́тайстви укріпля́ємі і ісціле́нія душ восприє́мше, гріхо́в проще́ніє улучи́м і Ца́рство Єго́ ві́чноє наслі́дим і с тобо́ю ку́пно да воспоє́м благода́рственная в Тро́йці слави́мому Бо́гу на́шему, Отцю́, і Си́ну, і Свято́му Ду́ху, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Пло́ті твоєя́ прокаже́ніє / мужему́дренно, я́ко І́ов, / претерпі́л єси́, Ники́форе, / ри́зу же душі́ твоєя́ / сві́тлі очи́стил єси́, / соверше́нне же на лі́ствицю доброді́телей восше́д, / по́двиги твої́ми / жи́тельства А́нгельськаго дости́же, / непреста́нно Бо́гу поя́: / Тебі́ сла́ва подоба́єть, // Тро́йце Єдиносу́щная."]},{"h":"Інший тропар, глас 1","ps":["Ники́фора преподо́бнаго прокаже́наго боре́нієм / і є́же в по́двизіх му́жеству / удиви́шася А́нгели, / я́ко други́й бо І́ов / боле́знная претерпі́, сла́в'я Бо́га, / ни́ні же сла́вою увінчава́ється от Него́, / чуде́с раздая́нієм. / Ра́дуйся, мона́хов наста́вниче, / ра́дуйся, челові́ком укріпле́ніє, / ра́дуйся, благоуха́нія обра́дованіє // ізлива́яй от моще́й твої́х."]},{"h":"Кондак, глас 2","ps":["Неду́га у́зький путь проше́л єси́, Ники́форе, / і вся́чеськи послі́довал єси́ Влади́ці, / я́ко послушли́вий і досто́йний син, / і́го же Того́ благо́є і бре́м'я ле́гкоє / на ра́міх поне́сл єси́, / ті́мже лику́я возше́л єси́ / к сла́ви ві́чния поко́ю кра́сному, // ра́достно веселя́ся."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Ники́форе, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобним Зосимі, Савватію і Герману, Соловецьким чудотворцям","e":"Akathist to our Venerable Fathers Zosimas, Sabbatius and Herman of Solovki, the Wonderworkers","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії уго́дниці Госпо́дні і вели́ції чудотво́рці, світи́льници Христо́ви Це́ркве пресві́тлії, облиста́вшії благоче́стія світлостьми́ пусти́ні Сі́вернаго Помо́рія, і всей страні́ Росси́йстій сія́ющії ви́ну чуде́с мно́жеством, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане, я́ко іму́щії дерзнове́ніє ко Го́споду, благоприя́тними свої́ми к Тому́ мольба́ми от вся́ких нас бід і зол сохраня́йте, да ра́дующеся зове́м вам:","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Ікос 1","ps":["А́нгели воі́стину яви́стеся земні́ї і челові́ци небе́снії житіє́м ва́шим, преблаже́ннії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане: во пло́ті бо, я́ко безпло́тнії, а́нгельськоє соверши́сте жи́тельство на землі́, вся красоти́ ми́ра і наслажде́нія вре́менная я́ко уме́ти вміня́юще, чистото́ю же і поще́нієм ви́ну к Бо́гу приближа́ющеся. Єму́же ни́ні досто́йно со безпло́тними предстоя́ще, приймі́те от любве́ на́шея приноси́мая вам хвале́нія сицева́я:","Ра́дуйтеся, Єди́наго Бо́га от всея́ душі́ своєя́ возлюби́вшії;","Ра́дуйтеся, от ю́ности Тому́ преподо́бієм і пра́вдою послужи́вшії.","Ра́дуйтеся, возненави́дівшії ми́ра сего́ тлі́нния красоти́;","Ра́дуйтеся, ізбіжа́вшії му́дре жите́йських собла́знов і суєти́.","Ра́дуйтеся, к ді́ланію за́повідей Госпо́дніх все́ю любо́вію приліпи́вшіїся;","Ра́дуйтеся, ми́ра сего́ і вся́каго пристра́стія ко о́ному удали́вшися.","Ра́дуйтеся, і́ночеськоє житіє́ богоугожде́нія ра́ди себе́ предизбра́вшії;","Ра́дуйтеся, ті́сний і приско́рбний путь все́ю душе́ю возлюби́вшії.","Ра́дуйтеся, му́дрії взиска́теліє Христа́, би́сера вожделі́ннаго і драга́го;","Ра́дуйтеся, люботру́днії носи́теліє Христо́ва бре́мене, ле́гкаго і блага́го.","Ра́дуйтеся, А́нгелом безпло́тним во пло́ті бре́нній подража́вшії;","Ра́дуйтеся, на землі́ жи́тельство небе́сноє нам показа́вшії.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 2","ps":["Ви́дя себі́, свя́те Савва́тіє, ра́ди мно́гих свої́х доброді́тельних ісправле́ній, всю́ду в сопребива́ніїх і́ночеських почита́єма і ублажа́єма, і бі́гая су́єтния ми́ра сего́ сла́ви, взиску́я же ві́чнаго воздая́нія на небесі́х, устреми́лся єси́ ко ото́ку Солове́цькому, да та́мо вта́йні і ники́мже ви́димий порабо́таєши неви́димому і вся ви́дящему Бо́гу. Ті́мже і улучи́в жела́ємоє, блаже́нним Ге́рманом к сему́ наставля́єм, ра́достно возопи́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум неукло́нно впери́в от утро́би ма́терні к Бо́гу, і го́рняя ви́ну му́дрствуя і взиску́я, до́льних же всеці́ло отверга́яся, богому́дре Зоси́мо, поревнова́л єси́ житію́ преподо́бнаго Савва́тія, і во ото́ці пу́сті, іді́же сей богоуго́дні соверши́ по́двиги своя́, всели́лся єси́, да с ним наслі́дуєши жи́тельство го́рняго Ієрусали́ма. Ті́мже во обої́х восхваля́юще пустинножи́тія рачи́тельство, зове́м вам:","Ра́дуйтеся, любве́ ра́ди Христо́ви, любо́во в себі́ к ми́ру попра́вшії;","Ра́дуйтеся, вся́кую гріхо́вную сла́дость ві́ка сего́ презрі́вшії.","Ра́дуйтеся, подо́бници Авраа́му не то́чію ві́рою і упова́нієм, но і доброво́льним от ро́да своєго́ і до́ма оте́чеськаго преселе́нієм;","Ра́дуйтеся, пусти́ні всекра́сная і благозла́чная насажде́нія.","Ра́дуйтеся, безмо́лвія тщали́війшії рачи́теліє;","Ра́дуйтеся, тру́дних подвиго́в пусти́нних і́скреннії люби́теліє.","Ра́дуйтеся, в де́бріх і гора́х па́че, не́же в се́ліх ми́ра, ізво́лившії примета́тися;","Ра́дуйтеся, в пусти́нях непроходи́мих, єди́ни во труді́х і соблюде́нії за́повідей Госпо́дніх возлюби́вшії подвиза́тися.","Ра́дуйтеся, я́ко зла́то, іскуси́вшіїся в горни́лі пусти́ннаго озлобле́нія;","Ра́дуйтеся, до́блественне претерпі́вшії от бісо́в же і от люде́й мно́гая іскуше́нія.","Ра́дуйтеся, проро́ку Бо́жию Ілії́ і крести́телю Госпо́дню Іоа́нну нра́вом пустиннолю́бія подража́теліє;","Ра́дуйтеся, до́блему Ге́рману єдиноми́сленнії сподви́жници любобезмо́лвнії купножи́теліє.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 3","ps":["Си́ли небе́сния, в служе́ніє посила́ємия хотя́щим наслі́довати спасе́ніє, ди́вно послужи́ша вам, о дво́їце боголюби́вая. Єгда́ бо насе́льници мирсті́ї, стужа́юще безмо́лвію твоєму́, о́тче Савва́тіє, жи́ти хотя́ху во о́строві близ тебі́ с жена́ми і ча́ди, а́нгели гро́зним преще́нієм і наказа́нієм жени́ ри́бареви восп'яти́ша сих от начина́нія богопроти́внаго: тебі́ же, о́тче Зоси́мо, во озимі́нії пребива́вшему кромі́ бра́шна, а́нгельським служе́нієм препода́шася потре́бная ко препита́нію. Сего́ ра́ди Бо́гу, спаса́ющему уго́дники Своя́, пої́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще ото́к морськи́й во оби́телище себі́, ники́мже населя́ємий, і в нем пребива́юще, а́ки в раї́ богозда́ннім, вні м'яте́жей і волне́ній жите́йських, і кромі́ су́єтних попече́ній, благоче́стно і богоуго́дно подвиза́стеся, о богоблаже́ннії, во дні і но́щі поуча́ющеся в зако́ні Госпо́дні, і на вся́кий час умо́м несмуще́нним і се́рдцем чи́стим вознося́ще усе́рдния к Бо́гу моли́тви і моле́нія. Сего́ ра́ди ра́достію вопіє́м вам:","Ра́дуйтеся, в зако́ні Госпо́дні непоро́чно ходи́ти всегда́ восхоті́вшії;","Ра́дуйтеся, Го́спода своєго́ пред очи́ма свої́ма при́сно імі́вшії.","Ра́дуйтеся, стра́хом Госпо́днім вся путі́ своя́ огражда́вшії;","Ра́дуйтеся, в трезве́нії у́мнім все житіє́ своє́ провожда́вшії.","Ра́дуйтеся, вся по́мисли ума́ в послуша́ніє Христо́во всеці́ло пліни́вшії;","Ра́дуйтеся, чи́стия ва́ша сердца́ в жили́ще Свято́му Ду́ху предста́вившії.","Ра́дуйтеся, не да́вшії сна очи́ма во всено́щних Го́сподеві предстоя́ніїх;","Ра́дуйтеся, ви́ну претерпіва́вшії ско́рби в поуче́нії сме́ртнім і в серде́чних ко Го́споду воздиха́ніїх.","Ра́дуйтеся, с і́скреннею любо́вію подвиза́вшіїся на славосло́віє Бо́жиє і псалмопі́нія;","Ра́дуйтеся, се́рдцем і усти́ непреста́нния возсила́вшії к Бо́гу моле́нія.","Ра́дуйтеся, внутр се́рдця своєго́ сокрове́нноє Ца́рствіє Бо́жиє обрі́тшії;","Ра́дуйтеся, восхожде́нії у́мними к небе́сним виді́нієм восте́кшії.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 4","ps":["Бу́рю житія́ сего́ многом'яте́жнаго безбі́дно премину́сте, отці́ Преподо́бнії, і свирі́пия во́лни страсте́й же і іскуше́ній, от ми́ра і пло́ті і от духо́в зло́би воздвиза́ємия, не погрузи́ша і не поколеба́ша корабля́ душ ва́ших, ві́трили моли́тви непреста́нния окриля́ємаго, і нестяжа́нієм облегчава́ємаго, благода́тію же Бо́жиєю управля́ємаго. Ті́мже і достиго́сте к безм'яте́жному приста́нищу живота́ ві́чнаго, вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще і ві́дуще от писа́ній Боже́ственних, я́ко всі подвиза́вшіїся во благоче́стії, распина́ху плоть свою́ со страстьми́ і похотьми́, благочестному́дренно, о преподо́бнії, сих по́двигом послі́дствующе, подвиза́стеся умертви́ти у́ди своя́ су́щия на землі́, в поще́ніїх, бді́ніїх і во вся́ких труді́х і́ночеськаго житія́ му́жеськи претерпіва́юще ско́рби. Сего́ ра́ди, я́ко до́блія подви́жники благоче́стія, вінча́єм ви хвале́нії сицеви́ми:","Ра́дуйтеся, тілеса́ своя́ труди́ і болі́зньми воздержа́нія ув'яди́вшії;","Ра́дуйтеся, вся плотська́я мудрова́нія, на дух вою́ющая, ду́ху покори́вшії.","Ра́дуйтеся, покая́нними слеза́ми пла́мень страсте́й угаси́вшії;","Ра́дуйтеся, в пещі́ воздержа́нія ду́ші своя́ я́ко зла́то очи́стившії.","Ра́дуйтеся, ве́тхаго челові́ка со страстьми́ єго́ совле́кшіїся;","Ра́дуйтеся, оде́ждею безстра́стія і сла́вою нетлі́нія досто́йно обле́кшіїся;","Ра́дуйтеся, возненави́дівшії вре́менную гріха́ сла́дость;","Ра́дуйтеся, наслі́довавшії на небесі́ несконча́ємую ра́дость.","Ра́дуйтеся, пре́жде сме́рти, ми́ру і сласте́м єго́ плоть свою́ распе́ншії;","Ра́дуйтеся, пре́жде воскресе́нія, сла́ву бу́дущия жи́зні в себі́ прояви́вшії.","Ра́дуйтеся, стезе́ю поста́ к наслі́дію рая́, поте́ряннаго невоздержа́нієм, путь нам указа́вшії;","Ра́дуйтеся, в тілесі́ ме́ртвеннім і тлі́ннім безсме́ртіє і нетлі́ніє бу́дущаго ві́ка всім пред'яви́вшії.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 5","ps":["Боготе́чния і многосві́тлия зві́зди яви́лися єсте́, преподо́бнії отці́ Зоси́мо, Савва́тіє і Ге́рмане, світоза́рними ісправле́нії за́повідей Госпо́дніх озаря́ющії ду́ші і сердця́ ві́рних, і препла́вающим в нощі́ гріхо́внаго омраче́нія пучи́ну жите́йськаго мо́ря указу́ющії благонаде́жний путь ко блаже́нному приста́нищу Небе́снаго Ца́рствія. Ті́мже яви́вшему ви, я́ко руководи́тели і наста́вники ко спасе́нію, благоді́телю Бо́гу пої́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше злоко́зненнії ненави́стници спасе́нія челові́чеськаго, нечи́стії ду́си тьми, богоуго́дноє житіє́ ва́ше, отці́ преблаже́ннії, многообра́зная воздвига́ху на ви іскуше́нія і страхова́нія, овогда́ в ми́слі і се́рдце всіва́юще боя́знь і смуще́ніє, овогда́ же преобразу́ющеся; в разли́чная привиді́нія ди́віїх звіре́й і гад, с я́ростію устремля́хуся на ви, ча́юще отврати́ти от по́двига богоуго́днаго і ізгна́ти от пребива́нія пусти́ннаго: ви же, тве́рдою ві́рою в Бо́га Промисли́теля возмога́юще і ору́жієм моли́тви і воздержа́нія проти́ву враго́во ва́ших ополча́ющеся, до конця́ побіди́сте і низложи́сте їх держа́ву. Сего́ ра́ди, побіди́тельную піснь пою́ще, взива́єм к вам:","Ра́дуйтеся, во́їни духо́внії непобіди́мії;","Ра́дуйтеся, ору́жници Христо́ви добропобі́днії.","Ра́дуйтеся, подви́жници, проти́ву ко́зней лука́ваго му́жеськи ополчи́вшіїся;","Ра́дуйтеся, столпи́ крі́пції, от нападе́ній вра́жиїх не поколеба́вшіїся.","Ра́дуйтеся, вся стрі́ли дия́воли а́ки хвра́стіє сокруши́вшії;","Ра́дуйтеся, вся стуже́нія того́ і страхова́нія ні во что́же вміни́вшії.","Ра́дуйтеся, я́ко во пло́ті су́ще, побіди́сте враги́ безпло́тния і неви́димия;","Ра́дуйтеся, я́ко і во гробі́х лежа́ще, низлага́єте вра́жія ополче́нія.","Ра́дуйтеся, побідоно́сці сла́внії, вінча́ннії от Небе́снаго Вінцеда́теля;","Ра́дуйтеся, спобо́рници до́блії ра́тующим на миродержи́теля тьми ві́ка сего́.","Ра́дуйтеся, я́ко по́двигом ва́шим А́нгели удиви́шася;","Ра́дуйтеся, я́ко о сла́ві ва́шей собо́ри ві́рних возвесели́шася.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 6","ps":["Пропові́данноє от а́нгел ізволе́ніє Бо́жиє о населе́нії і́ночествующими ото́ка Солове́цькаго іспо́лнися ва́ми, отці́ преблаже́ннії Зоси́мо, Савва́тіє і Ге́рмане: се бо пусти́ня непло́дная і ненаселе́нная, по́ти же і слеза́ми ва́шими оби́льно напоє́нная, показа́ся я́ко вертогра́д благоцвіту́щий і рай слове́сний, іді́же ли́ци і́ночестії, ва́ми благонауче́ннії, плоди́ богоуго́дния принося́ще, пою́ть а́нгельськую Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́сте, отці́ богоно́снії, сві́том благоче́стія, я́ко світи́ла богосві́тлая, світоно́сними луча́ми ва́ших подвиго́в і доброді́телей просвіща́ющії всю́ду. Отону́дуже ми, грі́шнії і тьмо́ю страсте́й помраче́ннії, во сві́ті ва́ших богоуго́дних дія́ній теку́ще ко дню сві́та і спасе́нія, восхваля́єм ви, пою́ще си́це:","Ра́дуйтеся, ученици́ Христо́ві благопослу́шнії;","Ра́дуйтеся, Влади́ки своєго́ раби́ блазі́ї і ві́рнії.","Ра́дуйтеся, трудолю́бнійшії виногра́да Христо́ва ді́лателіє;","Ра́дуйтеся, тщали́війшії за́повідей Христо́вих ісполни́теліє.","Ра́дуйтеся, і́гу Христо́ва смире́нія і кро́тости благопоко́рні ра́мо своє́ подклони́вшії;","Ра́дуйтеся, во слід Христа́ Го́спода, учи́вшаго о нищеті́, усе́рдно в нищеті́ і нестяжа́нії послі́довавшії.","Ра́дуйтеся, по словесі́ Го́спода, преше́дшії путь вре́меннаго житія́ сего́, стезя́ми приско́рбними і ті́сними;","Ра́дуйтеся, а́ки дожде́м, ізми́вшії ду́ші своя́ то́ки сле́зними.","Ра́дуйтеся, красні́йшему душ Жениху́ красоту́ ді́вства своєго́ сохрани́вшії;","Ра́дуйтеся, во вся́кой святи́ні, всі́ми до́брими ді́ли Тому́ благоугоди́вшії.","Ра́дуйтеся, Го́спода своєго́ просла́вившії в душа́х ва́ших і тілесі́х;","Ра́дуйтеся, от Го́спода по достоя́нію просла́вленнії на землі́ і на небесі́х.","Ра́дуйтеся, Преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 7","ps":["Хотя́й спасти́ ва́ми мно́гія, Премилосе́рдий Бог яви́ вас би́ти не то́чію наста́вники со́нма і́ночествующих, но я́коже боговіща́нния пропові́дники, возвести́вшия і́м'я Бо́жиє в страна́х Лапла́ндії. Лю́діє бо, во о́ніх мі́стіх обита́ющії, і не ві́дівшії дото́лі Бо́га, но приліжа́вшії весьма́ ідолопоклоне́нію і нече́стію, во сві́тлості ва́шего, о преподо́бнії, житія́, зна́меній же і чуде́с, узрі́ша пе́рвую зарю́ спаси́тельнаго богові́дінія і благоче́стія, і от вас научи́шася воспіва́ти і́стинному Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно і пресла́вно соверши́вше путь своєго́ спасе́нія, чу́дную же і боголі́пную основа́вше оби́тель во спасе́ніє і́ночествующим, блаже́нную восприя́сте живота́ своєго́ кончи́ну, приснопа́м'ятнії отці́ на́ші, Зоси́мо, Савва́тіє і Ге́рмане: оба́че, і по сме́рті ва́шей, при́сно жи́ви су́ще, нас, чад свої́х, нікогда́же оставля́єте, не ду́хом то́чію нам при́сно спребива́юще, но і мо́щі своя́ цільбоно́сния нам преда́вше, я́ко сокро́вище безці́нноє. Сего́ ра́ди с ра́достію ублажа́єм ви, зову́ще:","Ра́дуйтеся, до́брим по́двигом во всем житії́ своє́м подвиза́вшіїся;","Ра́дуйтеся, сла́вою і че́стію от Влади́ки своєго́ Христа́ увінча́вшіїся.","Ра́дуйтеся, я́ко привре́менно потруди́вшеся, во ві́чний поко́й внидо́сте;","Ра́дуйтеся, я́ко ті́сним ше́ствовавше путе́м, к блаже́нству Ца́рства Небе́снаго достиго́сте.","Ра́дуйтеся, а́ще і не єдиноку́пно, но в ра́вних по́двизіх подвиза́вшіїся на землі́;","Ра́дуйтеся, за равноподви́жноє житіє́, ра́достію і весе́лієм вку́пі наслажда́ющіїся на небесі́.","Ра́дуйтеся, во ото́ці пу́сті, я́ко град, оби́тель і́ноком основа́вшії;","Ра́дуйтеся, со́нми і́ноков о Христі́ Бо́зі во о́ній собра́вшії.","Ра́дуйтеся, стра́жи ста́ду своєму́ приснобо́дреннії, і по днех вре́менния жи́зні от діл благотворе́ній не почива́ющії;","Ра́дуйтеся, си́нове Ца́рствія, на Небесі́х живу́щії і земни́х не оставля́ющії.","Ра́дуйтеся, ду́хом ва́шим горі́ со А́нгели святи́ми, і до́лу с на́ми грі́шними при́сно пребива́ющії;","Ра́дуйтеся, от честни́х моще́й ва́ших струї́ ми́лости на всіх істоча́ющії.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 8","ps":["Стра́нную і пречу́дную, ве́лію же і прекра́сную узрі́в на возду́сі я́вльшуюся це́рков, все же мі́сто о́но, на не́мже ім'я́ше возгради́тися оби́тель і́ноков, ви́дя неізрече́нним сві́том осіява́ємо, у́жасом іспо́лнился єси́, о́тче Зоси́мо, от преди́внаго виді́нія. Оба́че, Бо́жиє во о́ном открове́ніє поразумі́в, на созида́ніє оби́телі тебі́ поощря́ющеє, ку́пно же і гряду́щую сла́ву мі́ста сего́ прозря́, умиле́нним се́рдцем і усти́ воспі́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі правові́рнії росси́йстії лю́діє, прославля́юще ва́ше свято́є і равноа́нгельноє житіє́, во вся́ких ну́ждах і ско́рбіх притека́ють к ва́шей по́мощі і заступле́нію, отці́ досточу́днії: дана́ бо єсть вам от Бо́га благода́ть, є́же моли́тися за ни, ізбавля́ти же і спаса́ти от вся́ких бід і зол притека́ющия к ра́кам честни́х моще́й ва́ших, і на вся́ком мі́сті призива́ющия свято́є ва́ше і́м'я. Ті́мже, іспові́дающе чу́дная ва́ша благодія́нія, благода́рственная воспису́єм вам, зову́ще:","Ра́дуйтеся, істо́чници Боже́ственних дарова́ній неізчерпа́ємії;","Ра́дуйтеся, ми́лованія і любве́ к лю́дем сосу́ди неіждива́ємії.","Ра́дуйтеся, я́ко кади́ло благово́нноє, о ми́рі моли́тви к Бо́гу вознося́щії;","Ра́дуйтеся, немо́лчними ва́шими хода́тайстви вся́коє благослове́ніє от десни́ці Бо́жия на ни низводя́щії.","Ра́дуйтеся, су́щим в ско́рбіх і ну́ждах ізві́стнії помо́щници;","Ра́дуйтеся, во обстоя́ніїх і напа́стіх ско́рії посо́бници.","Ра́дуйтеся, в неду́зіх ціли́телі, і в бу́рі стра́ждущим благонаде́жнії ко́рмчії і ізба́вители;","Ра́дуйтеся, во вся́ких бі́дах і іскуше́ніїх те́плії предста́телі і уті́шители.","Ра́дуйтеся, ві́рним, благоче́стно чту́щим вас, на сопроти́вния спобо́рници;","Ра́дуйтеся, всея́ землі́ Россі́йськия ізбра́ннії моле́бници і засту́пниці.","Ра́дуйтеся, на землі́ і на мо́рі чудеса́ пресла́вная содіва́ющії;","Ра́дуйтеся, во вся конці́ призива́ющим ви ско́рую по́мощ незави́стно простира́ющії.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 9","ps":["Всі́ми богокра́сними лі́потами доброді́телей украси́в себі́, прехва́льне Зоси́мо, найпа́че яви́лся єси́ красні́йшій душе́ю же і ті́лом, досто́йно пома́зався свяще́нства Боже́ственною ма́стію. Ті́мже, єгда́ во святі́м хра́мі соверша́л єси́ пред престо́лом Госпо́днім пе́рвую Боже́ственную слу́жбу, ви́діша всі лице́ твоє́, облиста́нноє сві́том благода́ті, я́ко лице́ а́нгелово: весь же храм, во ізві́стноє свиді́тельство досто́їнства твоєго́, іспо́лнися ве́лія благоуха́нія. Сего́ ра́ди всі, благодаря́ще Бо́га о своє́м па́стирі, ра́достним се́рдцем взива́ху: Аллилу́я."]},{"h":"Ікос 9","ps":["Віти́йственними добровіща́ньми ність возмо́жно по достоя́нію воспі́ти і просла́вити мно́гая і неісче́тная, ве́лія же і пресла́вная, і вся́коє разумі́ніє земно́є превосходя́щая, соверша́ємая ва́ми, отці́ преподо́бнії, на вся́коє вре́м'я чудотворе́нія. Оба́че, да не яви́мся чрез німотствова́ніє подо́бни рабу́, сокри́вшему сокро́вище своєго́ Влади́ки, от уст, а́ще і не обуче́нних і сло́ва прему́дрости отню́д не іму́щих, любо́вію же то́чію і благодаре́нієм дви́жимих, дерза́єм простира́ти піснь благодаре́нія в па́м'ять і прославле́ніє чуде́с ва́ших, зову́ще си́це:","Ра́дуйтеся, чудотво́рці великоімени́тії і благосла́внії;","Ра́дуйтеся, душ і тіле́с вра́чеве немздоприє́мнії.","Ра́дуйтеся, очеса́ сліпи́х благода́тію Бо́жиєю просвіща́ющії;","Ра́дуйтеся, німото́ю св'я́занния уста́ ко благоглаго́ланію разріша́ющії.","Ра́дуйтеся, рассла́бленних удеси́ ісправля́ющії неможе́ніє;","Ра́дуйтеся, хроми́м да́рующії правохожде́ніє.","Ра́дуйтеся, пліне́нних предста́тельством свої́м от уз і пліне́нія свобожда́ющії;","Ра́дуйтеся, ме́ртвия си́лою Бо́жиєю, ва́шим же умоле́нієм воскреша́ющії.","Ра́дуйтеся, во вся́ких страстеіх і неду́зіх соверша́ющії благода́тноє ісціле́ніє.","Ра́дуйтеся, томи́мим во обстоя́ніїх і напа́стіх да́рующії мир і духо́вноє просвітле́ніє;","Ра́дуйтеся, іду́щим во слід Го́спода путе́м ті́сним і приско́рбним подаю́щії боже́ственноє вспоможе́ніє.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 10","ps":["Спасе́нія по́двиг до́брі соверши́в, житія́ же сего́ вре́меннаго отріша́яся і отходя́ к животу́ ві́чному і блаже́нному, Зоси́мо богоблаже́нне, утіша́л єси́ ученики́ твоя́, глаго́ля я́ко, разлуча́яся с ни́ми тіле́сні, неотсту́пен бу́деши от них і оби́телі твоєя́ твої́м ду́хом. Отону́дуже і самі́ми ді́ли сло́во твоє́ ісполня́яй явля́єшися, не то́чію неви́димо сопрису́тствуя нам і назира́я вся, но і ви́димо мно́гажди, вку́пі со блаже́нним Савва́тієм, явля́яся во вре́м'я благопотре́бно призива́ющим вас в по́мощ і вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ необори́мая і покро́в тве́рдий, спасе́нія забра́ло і ору́жіє побі́ди би́ша нам, отці́ преподо́бнії, те́плиє ва́ша к Бо́гу моли́тви, в день бра́ні о́ния лю́тия, єгда́, по гріхо́м і беззако́нієм на́шим, вразі́ крі́пції і бранноїску́снії со огне́м і мече́м нападо́ша на ни в достоя́нії ва́шем, во є́же сокруши́ти святи́ні ва́ша і положи́ти я в разоре́ніє і попра́ніє, духо́вная же ча́да ва́ша побіди́ти і погуби́ти сме́ртію безго́дною; оба́че, ніко́єже зло возмо́гше сотвори́ти, са́мі найпа́че ті́ї іспо́лнишася студа́ і безче́стія, упова́ющії же на по́мощ ва́шу препоя́сашася ра́достію і весе́лієм о своє́м спасе́нії. Благодаря́ще у́бо о сем Бо́га, іспові́дуєм ку́пно ва́ше хода́тайство і заступле́ніє, і вопіє́м вам те́плі із глубини́ душі́:","Ра́дуйтеся, па́стиріє до́брії, от враго́в губи́тельних ста́до своє́ защища́ющії;","Ра́дуйтеся, я́ко орли́ под крило́ма свої́ма птенці́ своя́ покрива́ющії.","Ра́дуйтеся, покро́вом моли́тв свої́х в день бра́ні нас осіни́вшії;","Ра́дуйтеся, гнів Бо́жий, пра́ведно на ни дви́жимий, хода́тайством свої́м утоли́вшії.","Ра́дуйтеся, не да́вшії своєго́ достоя́нія в попра́ніє і расхище́ніє;","Ра́дуйтеся, па́че наде́жди сохрани́вшії є от о́гненнаго запале́нія.","Ра́дуйтеся, упова́ющия на ви от губи́тельства сме́ртнаго свободи́вшії;","Ра́дуйтеся, от ра́ни і я́зви, от уз і пліне́нія ди́вно тіх сохрани́вшії.","Ра́дуйтеся, враго́в горди́ню і дерзнове́ніє обрати́вшії во студ їм і безче́стіє;","Ра́дуйтеся, ни, жи́тельствующия в оби́телі ва́шей, неіскусобра́нния і безору́жния, оді́явшії в ра́дость і весе́ліє.","Ра́дуйтеся, ві́ри і благоче́стія оте́чеськаго неуси́пнії охрани́тели;","Ра́дуйтеся, за Оте́чество я́вльшіїся і по сме́рті му́жественнії воі́тели.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 11","ps":["Пі́сні хвале́бния і моле́нія всеумиле́нная принося́ще, долготу́ же пу́тную і опа́сности мо́ря ні во что́же вміня́юще, притека́ють к цільбоно́сним моще́м ва́шим ца́ріє і кня́зі, святи́телі і вельмо́жи, бога́тії і убо́зії, бли́жнії і да́льнії, всяк во́зраст і пол, і вся́коє ві́рних совокупле́ніє, і я́ко от неістощи́маго істо́чника, по коєго́ждо своє́й потре́бі, приє́млюще оби́льная врачева́нія душе́вная же і тіле́сная, прославля́ють і велича́ють Бо́га, такову́ю благода́ть вам дарова́вшаго, пою́ще: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том Боже́ственния благода́ті, в ні́дріх землі́, в преди́вних зна́меніїх і чудесі́х, от пе́рвих дній упокоє́нія возблиста́вшия ва́ша мо́щі, достодо́лжно і пра́ведно ли́ци і́ночестії, от многолі́тнаго покрове́нія ізне́сше, поста́виша со благогові́нієм на сві́щниці церко́внім, во хра́мі, і́мені ва́шему созда́ннім, благоче́стієм вели́каго і свята́го подража́теля ва́ших подвиго́в, іспові́дника і му́ченика, Святи́теля і первопресто́льника Россі́йськаго Фили́ппа. І ми ни́ні, благоче́стно о сла́ві ва́шей веселя́щеся, обстоя́ще честни́я ра́ки моще́й ва́ших і любе́зно ти́я облобиза́юще, велегла́сно зове́м вам:","Ра́дуйтеся, світи́льници пресві́тлії, на сві́щниці церко́внім пресла́вно поста́вленнії;","Ра́дуйтеся, киво́ти честні́ї, не ка́менієм і зла́том, но благода́ті дарова́ньми украше́ннії.","Ра́дуйтеся, я́ко три зві́зди, озаря́ющії тьму полу́нощную;","Ра́дуйтеся, я́ко три столпа́, в преді́ліх Сі́вернаго Помо́рія утвержда́ющії ві́ру правосла́вную.","Ра́дуйтеся, істо́чници ра́йстії, моря́ чуде́с ізлива́ющії;","Ра́дуйтеся, би́серіє дража́йшії, Це́рков Христо́ву украша́ющії.","Ра́дуйтеся, благоче́стія і доброді́телі світлі́йшая зерца́ла;","Ра́дуйтеся, Це́ркві і Оте́чества необори́мая забра́ла.","Ра́дуйтеся, ра́йськаго ісполне́нія кри́ни благово́ннійшії;","Ра́дуйтеся, лози́ Боже́ственния ро́зги благопло́днейшия.","Ра́дуйтеся, отці́ всеблаже́ннії, прославля́ємії го́ре от Бо́га і А́нгел, і до́лу ублажа́ємії от челові́к;","Ра́дуйтеся, я́ко ра́дость ва́ша, свята́я і соверше́нная, пребива́єть во вік.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 12","ps":["Благода́ть свою́ Боже́ственную, в тілесі́х ва́ших обита́ющую, яви́ іногда́ Преблаги́й Бог благогові́йному і́ноку Іо́сифу во о́бразі двух столпо́в огнезра́чних, от землі́ до небе́с над гроби́ ва́шими вознося́щихся і сія́ющих сві́том неізрече́нним: воі́стину бо ви єсте́, отці́ преподо́бнії, духо́внії світоза́рнії столпи́, сві́тлостію висо́ких доброді́телей і сві́том богозна́нія, зна́меній же і чуде́с, озари́вшії пресві́тло духо́вную тьму в страна́х полу́нощних. Сего́ ра́ди Бо́гу, прославля́ющему святи́я Своя́, пої́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще в пі́сніх по́двиги і труди́ ва́шего богоуго́днаго житія́, пресла́вная же соді́яная і содіва́ємая во вся́ком ро́ді благотворе́нія і чудотворе́нія восхваля́юще і прославля́юще, недоумі́єм, отці́ досточу́днії, ка́ко вас по до́лгу возимену́єм: мно́гія бо суть ва́ша доброді́телі і дарова́нія, сего́ ра́ди мно́гая прили́чествують вам і іменова́нія. Оба́че, во мно́гих ма́лими удовля́ющеся, сія́ вам с любо́вію воспису́єм:","Ра́дуйтеся, а́нгели земні́ї, я́ко а́нгельським жи́тельством на землі́ пожи́сте;","Ра́дуйтеся, челові́ци небе́снії, я́ко земноро́дні су́ще, возненави́дісте земна́я, небе́сная же возлюби́сте.","Ра́дуйтеся, по́стници терпіли́війшії, в при́снім поще́нії все житіє́ своє́ проводи́вшії;","Ра́дуйтеся, пусти́нници достохва́льнії, в пусти́нях незаходи́мих Го́сподеві послужи́вшії.","Ра́дуйтеся, учи́теліє і наста́вници, руководя́щії свої́ми ді́ли на путі́ спасе́нія;","Ра́дуйтеся, вожди́ духо́внії, мно́гих ду́ші возводя́щії в небе́сная селе́нія.","Ра́дуйтеся, му́чеником єдинонра́внії, я́ко му́жеськи бра́вшіїся со страстьми́;","Ра́дуйтеся, апо́столом подража́теліє, просвіти́вшії тьму неві́рія богові́дінія світлостьми́.","Ра́дуйтеся, проро́ком подо́бници, та́йних і бу́дущих прові́дінієм і прорече́нієм;","Ра́дуйтеся, всім святи́м єдиноче́стнії, подвиго́в ра́ди і богоугожде́нія.","Ра́дуйтеся, таї́нници благода́ті і чуде́с соверши́теліє преди́внії;","Ра́дуйтеся, гра́ждане небе́снії і дру́зі Бо́гу і святи́м Єго́ при́снії.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 13","ps":["Опреподо́бнії отці́ на́ші, Зоси́мо, Савва́тіє і Ге́рмане! Приймі́те благоутро́бно от нас смире́нних і недосто́йних сія́ возноси́мая вам хвале́нія, і благоприя́тними ва́шими к Бо́гу мольба́ми огради́те ни от вся́кия біди́ і напа́сти, от неду́га і гла́да, от огня́ і меча́, і наше́ствія іноплеме́нних. Найпа́че же сохрані́те ни ва́шим заступле́нієм крі́пким от враго́в неви́димих, і́щущих ни погуби́ти, да ізби́вше їх многоко́зненних сіте́й, пра́ведно і богоуго́дно поживе́м в ни́нішнем ві́ці, і сподо́бимся в Небе́снім Ца́рствії ку́пно с ва́ми воспіва́ти Христу́ Бо́гу: Аллилу́я, аллилу́я, аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели воі́стину яви́стеся земні́ї і челові́ци небе́снії житіє́м ва́шим, преблаже́ннії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане: во пло́ті бо, я́ко безпло́тнії, а́нгельськоє соверши́сте жи́тельство на землі́, вся красоти́ ми́ра і наслажде́нія вре́менная я́ко уме́ти вміня́юще, чистото́ю же і поще́нієм ви́ну к Бо́гу приближа́ющеся. Єму́же ни́ні досто́йно со безпло́тними предстоя́ще, приймі́те от любве́ на́шея приноси́мая вам хвале́нія сицева́я:","Ра́дуйтеся, Єди́наго Бо́га от всея́ душі́ своєя́ возлюби́вшії;","Ра́дуйтеся, от ю́ности Тому́ преподо́бієм і пра́вдою послужи́вшії.","Ра́дуйтеся, возненави́дівшії ми́ра сего́ тлі́нния красоти́;","Ра́дуйтеся, ізбіжа́вшії му́дре жите́йських собла́знов і суєти́.","Ра́дуйтеся, к ді́ланію за́повідей Госпо́дніх все́ю любо́вію приліпи́вшіїся;","Ра́дуйтеся, ми́ра сего́ і вся́каго пристра́стія ко о́ному удали́вшися.","Ра́дуйтеся, і́ночеськоє житіє́ богоугожде́нія ра́ди себе́ предизбра́вшії;","Ра́дуйтеся, ті́сний і приско́рбний путь все́ю душе́ю возлюби́вшії.","Ра́дуйтеся, му́дрії взиска́теліє Христа́, би́сера вожделі́ннаго і драга́го;","Ра́дуйтеся, люботру́днії носи́теліє Христо́ва бре́мене, ле́гкаго і блага́го.","Ра́дуйтеся, А́нгелом безпло́тним во пло́ті бре́нній подража́вшії;","Ра́дуйтеся, на землі́ жи́тельство небе́сноє нам показа́вшії.","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Кондак 1","ps":["Ізбра́ннії уго́дниці Госпо́дні і вели́ції чудотво́рці, світи́льници Христо́ви Це́ркве пресві́тлії, облиста́вшії благоче́стія світлостьми́ пусти́ні Сі́вернаго Помо́рія, і всей страні́ Росси́йстій сія́ющії ви́ну чуде́с мно́жеством, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане, я́ко іму́щії дерзнове́ніє ко Го́споду, благоприя́тними свої́ми к Тому́ мольба́ми от вся́ких нас бід і зол сохраня́йте, да ра́дующеся зове́м вам:","Ра́дуйтеся, преподо́бнії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане."]},{"h":"Молитва","ps":["Опреподо́бнії і богоно́снії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане, земні́ї а́нгели і небе́снії челові́ци, бли́жнії дру́зі Христо́ви і уго́дниці Бо́жії, оби́телі ва́шея сла́во і украше́ніє, всея́ же сі́верния страни́, па́че і всего́ правосла́внаго Оте́чества на́шего необори́мая стіно́ і вели́коє заступле́ніє! Се ми недосто́йнії і многогрі́шнії, с благогові́йною любо́вію ко святи́м моще́м ва́шим припа́дающе, ду́хом сокруше́нним і смире́нним се́рдцем прилі́жно мо́лим вас: молі́те непреста́нно благосе́рдаго Влади́ку і Го́спода на́шего Ісу́са Христа́, я́ко дерзнове́ніє ве́ліє к тому́ іму́щії, да не отсту́пить от нас Єго́ вседі́йствующая благода́ть, Покро́в же і заступле́ніє Пресвяти́я Влади́чиці на́шея Богоро́диці на мі́сті сем да пребу́деть, і да не оскуді́ють нікогда́же і́стиннії ревни́тели а́нгельськаго житія́ во святі́й оби́телі сей, іді́же ви, богоно́снії отці́ і нача́льниці, безмі́рними труди́ і поще́нії, то́ки же сле́зними і всено́щними бді́нії, непреста́нними моли́твами і моле́нії нача́ло і́ночеському житію́ положи́сте. Єй, уго́дниці святі́ї, моли́твенниці к Бо́гу благоприя́тнійшії, те́плими ва́шими к Нему́ мольба́ми огради́те і сохрані́те ни і свято́є селе́ніє сіє́ ва́ше от тру́са, пото́па, огня́ і меча́, наше́ствія іноплеме́нних і смертоно́сния я́зви, от вражди́ і вся́ких нестроє́ній, от вся́кия біди́ і ско́рби і от вся́каго зла: да непреста́нно на мі́сті сем, в ми́рі і безмо́лвії, благоче́стно сла́виться пресвято́є і́м'я Го́спода і Бо́га, і обріта́ють ві́чноє спасе́ніє і́щущії Єго́. О преблаже́ннії отці́ на́ші Зоси́мо, Савва́тіє і Ге́рмане! Усли́шіте ни грі́шния, во святі́й оби́телі ва́шей і под кро́вом ва́шего защище́нія недосто́йно жи́тельствующия, і благомо́щними ва́шими к Бо́гу хода́тайстви іспросі́те душа́м на́шим гріхо́в оставле́ніє, житія́ ісправле́ніє і ві́чних благ восприя́тіє в Небе́снім Ца́рствії: всім же ві́рующим, і́же на вся́ком мі́сті і во вся́кой ну́жді призива́ють вас в по́мощ і заступле́ніє, і і́же с благогові́йною любо́вію во оби́тель ва́шу притека́ють, не преста́ніте ізлива́ти вся́кую благода́ть і ми́лость, сохраня́юще їх от вся́кия сопроти́вния си́ли, от вся́кия напа́сти і от вся́каго зла́го обстоя́нія, і подаю́ще їм вся потре́бная к душе́вній і тіле́сній по́льзі. Найпа́че же молі́те премилосе́рдаго Бо́га, да утверди́ть і укріпи́ть Це́рков Свою́ святу́ю і все на́ше правосла́вноє Оте́чество в ми́рі і тишині́, в любві́ і єдиноми́слії, в правові́рії і благоче́стії да сохрани́ть і соблюде́ть во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["Опреподо́бнії отці́, вели́ції засту́пниці в ско́рбі і усли́шателіє моли́тв, уго́дниці Бо́жії і чудотво́рці Зоси́мо, Савва́тіє і Ге́рмане! Не забу́діте, я́коже обіща́стеся, посіща́ти ча́да ва́ша. А́ще бо і отидо́сте от нас ті́лом, но ду́хом при́сно с на́ми пребива́єте. Мо́лим у́бо ви, о преподо́бнії: ізба́віте ни от огня́, от наше́ствія іноплеме́нников і междоусо́бния бра́ні, от тлітво́рних ві́тров, і от напра́сния сме́рти, і от всіх прило́гов бісо́вських, находя́щих на ни. Усли́шіте нас грі́шних, і приймі́те моли́тву сію́ і моле́ніє на́ше, я́ко кади́ло благово́нноє, я́ко же́ртву богоуго́дну, і ду́ші на́ша, зли́ми ді́ли і сові́ти і по́мисли умерщвле́нния, оживі́те, і я́коже уме́ршую отрокови́цю возста́висте, я́коже неісці́льния ра́ни мно́гих ісціли́сте, от духо́в нечи́стих злі му́чимих ізба́висте, та́ко і нас, содержи́мих во у́зах вра́жиїх, ізмі́те, і от сіте́й дия́вола ізба́віте, із глубини́ прегріше́ній ізведі́те, і ми́лостивим ва́шим посіще́нієм і хода́тайством от враго́во ви́димих і неви́димих огради́те ни благода́тію і си́лою Всесвяти́я Тро́йці, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар преподобному Зосимі Соловецькому, глас 4","ps":["Ізволе́нієм Боже́ственнаго ра́зума / всели́лся єси́ в пусти́ню, / і та́мо, впери́в ум твой в Небе́сния оби́телі, / ра́вно А́нгелом житіє́ на землі́ пожи́в, / в моли́твах, і труді́х, і поще́ніїх / о́браз бил єси́ твої́м ученико́м. / Отону́дуже Бог, ви́дя твоє́ благо́є ізволе́ніє, / умно́жи тебі́ ча́да в пусти́ні, слез твої́х тече́ньми напая́ємій. / Но, я́ко імі́я дерзнове́ніє к Бо́гу, / помина́й ста́до, є́же собра́л єси́, му́дре, / і не забу́ди я́коже обіща́лся єси́, / посіща́я чад твої́х, // Зоси́мо преподо́бне, о́тче наш."]},{"h":"Кондак преподобному Зосимі Соловецькому, глас 8","ps":["Христо́вою любо́вію уязви́ся, преподо́бне, / і Того́ Крест сла́вний, на ра́мо взем, / поне́сл єси́, боже́ственне вооружи́вся, / і непреста́нния моли́тви, я́ко копіє́ в руці́, іми́й, / крі́пко ссікл єси́ бісо́вськая ополче́нія. / Тім зове́м ті: // ра́дуйся, преподо́бне о́тче Зоси́мо, мона́хов удобре́ніє."]},{"h":"Величання преподобному Зосимі Соловецькому","ps":["Ублажа́єм тя, / преподо́бне о́тче Зоси́мо, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]},{"h":"Тропар преподобному Савватію Соловецькому, глас 3","ps":["Удали́вся ми́ра і водвори́вся в пусти́ню, / до́брим по́двигом подвиза́лся єси́, / злострада́нієм, і внима́нієм, і моли́твами, / отону́дуже і по сме́рті істоча́єши ісціле́нія, / Савва́тіє о́тче наш, / моли́ Христа́ Бо́га, // спасти́ся душа́м на́шим."]},{"h":"Кондак преподобному Савватію Соловецькому, глас 2","ps":["Жите́йськія молви́ отбі́г, / всели́лся єси́ в морськи́й о́стров, му́дре, / і крест твой взем, Христу́ послі́довал єси́, / в моли́твах, і во бді́ніїх, і в поще́ніїх / злострада́ньми плоть твою́ ізнуря́я. / Тім бил єси́ преподо́бних удобре́ніє. / Сего́ ра́ди любо́вію па́м'ять твою́ пра́зднуєм, / преподо́бне Савва́тіє, // моли́ Христа́ Бо́га непреста́нно о всіх нас."]},{"h":"Величання преподобному Савватію Соловецькому","ps":["Ублажа́єм тя, / преподо́бне о́тче Савва́тіє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]},{"h":"Тропар преподобному Герману Соловецькому, глас 8","ps":["Жела́нієм духо́вним от ю́ности распаля́єм, преподо́бне Ге́рмане, / Христу́ ті́сним житія́ путе́м послі́довал єси́ / і, в морськи́й пусти́нний о́стров, а́ки в ти́хоє приста́нище, всели́вся, / в нем мно́га лі́та по́стничеськи пожи́л єси́, / іді́же блаже́нним отце́м Зоси́мі і Савва́тію сожи́тель бил єси́, / с ни́миже моли́ Христа́ Бо́га о нас, // любо́вію чту́щих святу́ю па́м'ять твою́."]},{"h":"Кондак преподобному Герману Соловецькому, глас 4","ps":["Ви́шніх жела́я, / вся до́лу влеку́щая возненави́діл єси́ / і, отече́ство своє́ оста́вль, / в помо́ріє пусти́нноє отше́л єси́, / та́же в морськи́й о́стров удали́вся, / в нем мно́га лі́та Го́сподеві порабо́тал єси́. / Ті́мже, па́м'ять твою́ пра́зднующе, / любо́вію вопіє́м ті: // ра́дуйся, Ге́рмане Богому́дре, о́тче наш."]},{"h":"Величання преподобному Герману Соловецькому","ps":["Ублажа́єм тя, / преподо́бне о́тче Ге́рмане, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобним отцям, на святій горі Афонській просіяним","e":"Akathist to the Venerable Fathers who shone forth on the Holy Mountain of Athos","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії уго́дниці Госпо́дні, духо́вно благоуха́ющії цві́ти са́да Ісу́сова, от Святи́я Гори́ Афо́нськия во вертогра́д небе́сний вознесеннії, і дерзнове́ніє ко Го́споду стяжа́вшії, мо́лим вас, отці́ богоно́снії, моли́твами ва́шими от вся́ких нас бід свободи́те, да зове́м вам хвале́бно:","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Ікос 1","ps":["А́нгели во пло́ті і челові́ци небе́снії воі́стину би́сте, отці́ богоно́снії, равноа́нгельноє житіє́ в пусти́нях Афо́на пожи́вше, равностоя́теліє А́нгелов на небесі́ яви́стеся, отню́дуже сві́тлими луча́ми моли́тв ва́ших мрак душ на́ших ви́ну благода́тію озаря́єте, о́бразом же ва́шего богоуго́днаго житія́ на спасе́нія стезю́ нас путеводіте, зову́щих вам от душі́:","Ра́дуйтеся, світи́льници немерцающії Бо́жия благода́ті.","Ра́дуйтеся, столпи́ непоколеби́мії Святи́я Правосла́вния Це́ркве.","Ра́дуйтеся, подви́жници до́блії, по́двиги ва́шими Афо́н удобри́вшії.","Ра́дуйтеся, по́стници богому́дрії, во всю вселе́нную чудеси́ сія́ющії.","Ра́дуйтеся, би́серіє духо́внії, от удо́лій Афо́на в Сіо́ні го́рнем возблиставшії.","Ра́дуйтеся, добро́тою душ ва́ших Го́споду Ісу́су благоугоднії я́вльшіїся.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 2","ps":["Ви́дим вас, преподо́бнії отці́ Пе́тре і Афана́сіє, в собо́рі преподо́бних Афо́нських пе́рвенство приє́мших, і явле́ніє вам Пресвяти́я Богоро́диці зіло́ облагодатствованних; ті́мже, я́ко дво́їцю богому́друю, Тро́йце Боже́ственній до́брі послужи́вшую, ублажа́єм вас пі́сньми хвале́бними, отці́ досточу́днії, і вопіє́м просла́вльшему вас Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний стяжа́сте, отці́ богому́дрії, і вся кра́сная ми́ра сего́ презрі́вше, в Горі́ Афо́нстій мир душе́вний о Христі́ обріто́сте, і со Христо́м во Ца́рствії Небе́снім пребива́єте; отню́дуже і нас, треволне́нієм мо́ря жите́йськаго обурева́ємих, моли́твами ва́шими благода́тно умирі́те, да в тишині́ ду́ха воспоє́м вам, засту́пником на́шим, пі́сні такови́я:","Ра́дуйтеся, мо́ря стра́стнаго пучи́ну окормле́нієм Христо́вим до́брі преминувшії.","Ра́дуйтеся, в при́стань спасе́нія благополу́чно дости́гшії.","Ра́дуйтеся, вітри́лом ві́ри, наде́жди і любве́ кора́бль душ ва́ших от бу́рі страсте́й неви́димо сохра́ншії.","Ра́дуйтеся, котвою поста́ і моли́тви крі́пці єго́ утверди́вшії.","Ра́дуйтеся, зві́зди богосві́тлия, нощ гріхо́вную на́шу благода́тно озаря́ющия.","Ра́дуйтеся, сві́том доброді́телей ва́ших і на́ша мра́чния душі́ духо́вно просвіща́ющії.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 3","ps":["Си́лою Христо́вою преісполненнії святи́теліє богому́дрії, Афана́сіє, Ка́ллисте, Ни́фонте, Феоно, Григо́ріє і іні́ї мно́зі, во Афо́ні просія́вшії, па́стиріє Христо́ви Це́ркве, молі́те, мо́лим ви, Пастиренача́льника Христа́, да нас, ове́ць заблу́ждших, упасе́ть во спасе́ніє і сподо́бит ни богому́дрію ва́шему подража́ти, богоуго́дні же і пра́ведно во ві́ці сем пожи́ти, благу́ю живота́ кончи́ну улучи́ти і вку́пі с ва́ми пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще єди́но раче́ніє, є́же єди́ному Христу́ благоугожда́ти, преподо́бієм же і пра́вдою ві́рно Єму́ служи́ти, отці́ всеблаже́ннії, Афо́ну похвала́ і утвержде́ніє яви́стеся і жре́бій Богома́тере святи́ми по́двиги ва́шими духо́вно благоукрасисте, с Не́ю же вку́пі помолі́теся ко Го́споду, Си́ну Єя́ і Бо́гу, не лише́нним би́ти і нам благи́я ча́сти спаса́ємих человіколю́бієм Христо́вим, да зове́м вам благода́рственно і хвале́бно:","Ра́дуйтеся, Царя́ Небе́снаго во́їни непобіди́мії, под зна́менієм Креста́ со враги́ неви́димими ратовавшії.","Ра́дуйтеся, Цари́ці Небе́сния служи́теліє ізбра́ннії, жре́бій Єя́ земни́й доброді́тельми ва́шими до́брі просла́вльшії.","Ра́дуйтеся, ра́дости небе́сния і сла́ви святи́х досто́йнії наслі́дници.","Ра́дуйтеся, блаже́нства ра́йськаго і сві́та невече́рняго соприча́стници.","Ра́дуйтеся, от го́рних висо́т сла́ви ва́шея к земноро́дним ми́лостивно приникающії.","Ра́дуйтеся, нас, чад ва́ших і ове́ць слове́сних па́стви ва́шея, оте́чеськи посещающії.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 4","ps":["Бу́ри жите́йськія му́дре ізбіжа́сте, і ца́рствіє земно́є на Ца́рствіє Небе́сноє до́брі ізміни́сте, мироточиве Симео́не і святи́телю Са́вво, се́рбськая похвало́ і Хилендарськия оби́телі ктитори ізря́днії; ті́мже Христо́с чудеси́ пресла́вними вас просла́ви, і вмі́сто вре́менних благ, ва́ми оста́вленних любве́ Єго́ ра́ди, благами нетлі́нними і ві́чними вас обогати́, Єму́же молі́теся прилі́жно, отці́ достохва́льнії, спасе́ніє о Христі́ улучи́ти і нам, грі́шним, благоумиле́нно Єму́ зовущим: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше о по́двизіх ва́ших, диві́мся, преподо́бнії отці́ Афо́нстії, Го́ру Святу́ю жи́тельством ва́шим не́бо друго́є соді́лавшії, і от нея́ на го́ру небе́сную удо́б восте́кшії, іді́же душа́ми ва́шими в Ієрусали́мі го́рнем ни́ні обита́єте і сла́дкаго лицезрі́нія Христо́ва ви́ну наслажда́єтеся. Но я́ко до́брії подража́теліє милосе́рдія Спасова, нас, смире́нних і грі́шних, моли́твами ва́шими ми́лостивно осіні́те, і на спасе́нія стезю́ наста́віте, да вам зове́м все ра́достно:","Ра́дуйтеся, орли́ небопа́рнії, от удо́лій Афо́на на го́ру небе́сную возлетевшії.","Ра́дуйтеся, ла́стовиці сладкопесненнії, пусти́ню Афо́на пі́нії моли́твенними огласившії.","Ра́дуйтеся, трисо́лнечним сві́том го́ре озареннії.","Ра́дуйтеся, чуде́с благода́тію і ісціле́нія дарова́нієм до́лу от Го́спода просла́вленнії.","Ра́дуйтеся, я́ко мзда ва́ша мно́га єсть на небесі́х.","Ра́дуйтеся, я́ко душі́ ва́ша подо́бні со́лнцю сія́ють во сві́тлостіх святи́х.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 5","ps":["Богосві́тлия зві́зди яви́стеся, Іоа́нне, Гео́ргіє і Євфи́міє І́верстії, Неофі́те і Євфи́міє Дохіярстії, Симео́не, Па́вле, Діоні́сіє і Григо́ріє, оби́телей Афо́нських первонача́льници і основателіє всечестні́ї, к вам же Григо́рій Синаї́ть, Діони́сій Олимпійський, Симео́н, Феофа́н і Євдоки́м чудотво́рці, Генна́дій і Некта́рій по́стници, я́ко сія́ющії доброді́тельми, да сопричтуться. Мо́лим вас, отці́ всеблаже́ннії, во оби́теліх нерукотворних і ві́чних ни́ні обита́ющії: не преста́йте моли́твами ва́шими сохраня́ти і соблюда́ти ни, ча́да ва́ша духо́вная, от лови́тви і сіте́й врага́ дия́вола, да, спаса́ємі святи́м небе́сним предста́тельством ва́шим, зове́м Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дим вас, отці́ богоно́снії, вся за́повіді Христо́ви до́брі сохранших, і любому́дрію духо́вному усе́рдно прилежавших, і ва́шим о́бразом наставля́ємі, лі́ность душевре́дную от себе́ оттряса́єм, на по́двиги же духо́вния простира́ємся, іму́ще вас к подви́жничеству духо́вному учи́телей і руководителей. Сего́ ра́ди благода́рственно вам зове́м:","Ра́дуйтеся, сле́знії іскателіє блаже́нства ра́йськаго.","Ра́дуйтеся, неуси́пнії моли́твенниці к Бо́гу о ми́рі всего́ ми́ра.","Ра́дуйтеся, посто́м душі́ ва́ша во спасе́ніє напитавшії.","Ра́дуйтеся, бді́нії всено́щними і долулега́нії врага́ неви́димаго крі́пці низложи́вшії.","Ра́дуйтеся, пла́чем умиле́нним разжже́нния стрі́ли дия́вольських іскуше́ній угаси́вшії.","Ра́дуйтеся, і́же із глубини́ воздиха́ньми пусти́ню Афо́на духо́вно уплодоносившії.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 6","ps":["Пропові́дником святи́я ві́ри, Апо́столом Христо́вим, усе́рдні подражасте в про́повіді Єва́нгелія пра́вди, Космо́ равноапо́стольне, Дамія́не, Ники́то, Киприя́не і Іа́кове с двіма́ ученико́ма твої́ма, за і́м'я Христо́во до кро́ве подвиза́вшеся, му́ченичеськую кончи́ну получи́сте, вінцено́сці добропобі́днії, і ни́ні со Христо́м ві́чно ца́рствуєте в оби́теліх ра́йських, Єго́же прилі́жно молі́те, нелишенним би́ти і нам наслі́дія небе́снаго, вопію́щим Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́сте на Афо́ні, я́ко світи́льници богосія́ннії, отці́ преблаже́ннії, і всю вселе́нную озаря́єте чудеси́ ва́шими, от восто́ка бо і до сі́вера прославля́ються хвале́бно, святі́ї, імена́ ва́ша і ублажа́ються по́двиги раноангельськаго житія́ ва́шего благохвале́нії такови́ми:","Ра́дуйтеся, всерадостнії ві́стници Христо́ва всемогу́щества і си́ли.","Ра́дуйтеся, кріпкоду́шнії подви́жници, сокруши́вшії главу́ прего́рдаго велія́ра.","Ра́дуйтеся, до́брії целебници неду́гов душе́вних і тіле́сних.","Ра́дуйтеся, ізві́стнії умилостивителіє Царя́ Небе́снаго Христа́ Бо́га.","Ра́дуйтеся, одеяннії в преподо́біє і пра́вду ратобо́рці духо́внії.","Ра́дуйтеся, приє́мшії власть от Го́спода на ду́хи нечи́стия.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 7","ps":["Хотя́щим благоче́стно о Христі́ жи́ти, о́браз богоуго́днаго і безмо́лвнаго житія́ являєте в себі́, преподо́бнії пустинножи́теліє Макси́ме, Космо́ і Ака́кіє, і мироточці Ни́ле і Фео́филе, в пусти́нях Афо́на подвиза́вшіїся равноа́нгельно, к вам же і преподо́бний Анто́ній Пече́рський, во Афо́ні духо́вно воспита́нний, досто́йно сопричтеся, і́же і первонача́льник і́ночеськаго в Русі́ житія́ соді́лася. Молі́теся ко Го́споду, отці́ богоно́снії, да вку́пі с ва́ми сподо́бимся і ми, смире́ннії, Ца́рствіє Небе́сноє унаслі́дити і в ра́дості святи́х воспіва́ти Созда́телю на́шему во ві́ки: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий Сіо́н яви́ся Свята́я Гора́ Афо́нськая, в не́йже от восто́ка, сі́вера і ю́га прийдо́ша ча́да духо́вная, благословляющая в ней Го́спода в пі́сніх хвалебних: се бо собо́р богосві́тлий преподо́бних оте́ць, во Афо́ні свя́то пожи́вших, созива́єть нас днесь чествова́ти їх по́двиги і труди́ і вопи́ти к ним си́це:","Ра́дуйтеся, вели́ції уго́дниці Бо́жії, вели́чієм по́двигов ва́ших А́нгелов удиви́вшії.","Ра́дуйтеся, пресла́внії чудотво́рці, в біда́х і ско́рбіх челові́ком помога́ющії.","Ра́дуйтеся, пусти́ні Афо́на благода́тная прозябе́нія.","Ра́дуйтеся, святи́я Правосла́вния Це́ркве духо́вная красото́ і ра́дованіє.","Ра́дуйтеся, ра́дости нам і сла́ви ві́чния усе́рднії хода́таї.","Ра́дуйтеся, во благи́х жела́ній на́ших ско́рії ісполни́теліє.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 8","ps":["Стра́нно і пресла́вно по мо́рю немо́кренно проше́л єси́, Гавриї́ле преподо́бне, і іко́ну Боже́ственния Врата́рници Афо́ну прене́сл єси́ в благослове́ніє і освяще́ніє; тебі́ же, богоно́се Іоа́нне Кукузеле, Пресвята́я Богоро́диця Сама́ яви́ся і от рук Свої́х пречи́стих златницю ди́вно подаде́, да поє́ши Єй немо́лчно пі́сні хвале́бния. О толи́ких чудесі́х Бо́жиїх див'я́щеся, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся Свята́я Гора́ Афо́нськая і вся пусти́ня єя́ і удо́лія благослове́ніє Бо́жиє в себі́ проявля́ють: із них бо древеса́ благопло́дная рая́ Ісу́сова прозябо́ша, собо́р вели́кий преподо́бних оте́ць на́ших Афо́нських, ї́хже плода́ми духо́вними насища́ющеся, благода́рним се́рдцем і усти́ глаго́лем к ним такова́я:","Ра́дуйтеся, а́нгели земні́ї і челові́ци небе́снії.","Ра́дуйтеся, кри́ни благоуха́ннії пусти́ннаго прозябе́нія.","Ра́дуйтеся, онебеси́вшії Го́ру Афо́нськую доброді́тельми ва́шими небе́сними.","Ра́дуйтеся, ви́ну ходатайствующії пред Го́сподем за весь мир христия́нський.","Ра́дуйтеся, ізбраници Бо́жії, ізбра́ніє ва́ше чудеси́ мно́гими засвидетельствовавшії.","Ра́дуйтеся, вінцено́сці добропобі́днії, от Христо́ви десни́ці увенчаннії.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 9","ps":["Всі А́нгели небе́снії удиви́шася вели́честву по́двига і терпі́нія ва́шего, преподобному́ченици Зографстії, предо́блії Фомо́ с дружи́ною твоє́ю, от латинян за Правосла́вную ві́ру сожженнії, і же́ртва благоприя́тна Бо́гу я́вльшіїся: ва́ша бо імена́ напи́сана суть на небесі́х, в кни́зі живота́ ві́чнаго, і ісповедаються от Христа́ Бо́га пред Отце́м Небе́сним, Єму́же в ли́ці му́ченичестім ра́достно поєте́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї суєму́дрії человечествії, глаго́лющії бу́йство би́ти подви́жничество духо́вноє, посрами́шася по́двиги ва́шими і чудеси́, преподо́бнії отці́ на́ші Афо́нстії: кто бо не умили́ться ви́дя, ка́ко ви земна́я вся пренебре́гше, к небе́сним вседу́шно устреми́стеся і єго́же іска́сте, того́ і достиго́сте, пресві́тлаго лицезрі́нія Христо́ва. Сего́ ра́ди восхваля́єм вас си́це:","Ра́дуйтеся, язи́к свят, ца́рськоє свяще́ніє, лю́діє обновле́нія.","Ра́дуйтеся, соль духо́вная всея́ землі́, я́же не обуя́єть во ві́ки.","Ра́дуйтеся, провозві́стници пра́вди Христо́ви, ізшедшия от ми́ра на служе́ніє Бо́гу.","Ра́дуйтеся, от вся́каго ро́да призва́ннії в сла́дкую рабо́ту Госпо́дню.","Ра́дуйтеся, яре́м благи́й на ся взе́мшії і вслід Влади́ки Христа́ послі́довавшії Єму́ і́скренно.","Ра́дуйтеся, поко́й душа́м ва́шим ві́чний на небесі́х от Христа́ Подвигополо́жника восприя́вшії.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 10","ps":["Спаси́телю Бо́гу, ізве́дшему ви от го́ркия рабо́ти гріхо́вния, піснь хвале́бную возсила́юще, за Христа́ пострада́ти устреми́стеся, преподобному́ченици вседо́блії Мака́ріє, Іларіо́не, Пахо́міє, Константи́не, Ону́фріє, Проко́піє, Луко́, Тимофе́є, Агафангеле і іні́ї мно́зії, от Афо́на ізше́дшії і Христа́ пред ага́ряни іспові́давшії, за Него́же до кро́ве пострада́сте і душі́ ва́ша положи́сте, ни́ні же с му́ченики ра́дуєтеся і сла́дці поєте́ Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго Христа́ до́блії ору́жници яви́стеся, отці́ богоно́снії, от Него́же мзду трудо́м ва́шим восприє́мше, духо́вних чад ва́ших по ві́рі о́бразом ва́шим путеводствуєте к Нему́ нело́жно, от нас же сли́шіте досто́йния вам пі́сні сицеви́я:","Ра́дуйтеся, о ни́хже ра́дуються А́нгели і Бо́га сла́в'ять челові́ци.","Ра́дуйтеся, о ни́хже духо́вно красу́ється Свята́я Гора́ Афо́нськая от ро́да в род.","Ра́дуйтеся, о́блаці росоноснії, зной страсте́й на́ших прохлаждающії.","Ра́дуйтеся, ма́слини благоплоднії, єле́єм трудо́во ва́ших се́рдця на́ша умащающії.","Ра́дуйтеся, адама́нти терпі́нія, сія́ющії луча́ми Бо́жия благода́ті.","Ра́дуйтеся, столпи́ Правосла́вія, чудеси́ ва́шими утвержда́ющії коле́блющихся во ві́рі.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 11","ps":["Пі́ніє Пресвяті́й Тро́йце принося́ще, тро́йця но́вих новому́чеников во Афо́ні духо́вно возсія́: Євфи́мій, Ігна́тій і Ака́кий вседо́блії, ага́рянськоє злоче́стіє посрами́вшії і і́м'я Христо́во пред ага́ряни іспові́давшії пресла́вно, от ни́хже му́ченичеськую кончи́ну восприє́мше, со Христо́м ни́ні обита́ють, воспіва́я Єму́ побі́дную піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми чуде́с ва́ших, отці́ всеблаже́ннії, Гора́ Афо́нськая духо́вно озаря́ється і блажи́ть вас по до́лгу, я́ко небе́сних єя́ засту́пников і покрови́телей; ми же, чту́ще по́двиги ва́ша і страда́нія, от любве́ душе́вния прино́сим вам со смире́нієм і ві́рою сія́ похвали́:","Ра́дуйтеся, ми́ро целебноє Бо́жия благода́ті оби́льно нам істоча́ющії.","Ра́дуйтеся, неду́гов душе́вних і тіле́сних вра́чеве предо́брії.","Ра́дуйтеся, єди́ния то́кмо ві́ри ко уврачева́нію неду́гов от нас тре́бующії.","Ра́дуйтеся, ту́не приє́мшії, ту́не подаю́щії нам благода́ть ісціле́нія.","Ра́дуйтеся, даро́в духо́вних і душеспаси́тельних блазі́ї нам пода́теліє.","Ра́дуйтеся, в біда́х і ско́рбіх ско́рії нам помо́щници і уті́шителіє.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 12","ps":["Благода́ті Бо́жієй сосу́ди ізбра́ннії, всі преподо́бнії отці́ на́ші Афо́нстії, пойменованнії і непоіменованнії, сві́тлим собо́ром ва́шим на по́мощ к нам ускорі́те во вре́м'я безпомо́щія на́шего і от напра́сния і на́глия сме́рти чтущия ви ізба́віте благоприя́тним предста́тельством ва́шим ко Го́споду, да благода́рственно зове́м Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще свято́є і равноа́нгельноє житіє́ ва́ше і мно́гая ва́ша чудеса́, преподо́бнії отці́ на́ші Афо́нстії, хва́лим, сла́вим і велича́єм просла́вльшаго вас Христа́ Бо́га, Освяти́теля святи́х і Творця́ чудотво́рцев, ізлившаго на вас оби́ліє Свої́х даро́в благода́тних, вас же, святи́х і многомощних предста́телей на́ших, ублажа́єм зва́нії си́ми:","Ра́дуйтеся, наста́вници мона́хов і собесі́дниці А́нгелов.","Ра́дуйтеся, всіх святи́х дру́зі і при́снії Бо́гу.","Ра́дуйтеся, гра́ждане сія́ющаго гра́да Ієрусали́ма го́рняго.","Ра́дуйтеся, оби́телей ва́ших земни́х покрови́теліє небе́снії.","Ра́дуйтеся, і́ноков правосла́вних утвержде́ніє і заступле́ніє.","Ра́дуйтеся, о всем ми́рі неуси́пніі хода́таї.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 13","ps":["О преподо́бнії отці́ на́ші Афо́нстії, Бо́гом дарова́ннії нам засту́пниці і покрови́теліє, ви го́ре, на небесі́, ми же до́лу, на землі́, удале́ннії от вас не толи́ко мі́стом, коли́ко гріхо́вною нечистото́ю на́шею, оба́че дерза́єм приноси́ти вам сіє́ ма́лоє похва́льноє пі́ніє, і о єди́ном вас мо́лим і про́сим: умолі́те Спа́са Христа́ ізба́вити нас ві́чния муки́ і сподо́бити ца́рства небе́снаго, да с ва́ми воспоє́м Єму́ во ві́ки: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели во пло́ті і челові́ци небе́снії воі́стину би́сте, отці́ богоно́снії, равноа́нгельноє житіє́ в пусти́нях Афо́на пожи́вше, равностоя́теліє А́нгелов на небесі́ яви́стеся, отню́дуже сві́тлими луча́ми моли́тв ва́ших мрак душ на́ших ви́ну благода́тію озаря́єте, о́бразом же ва́шего богоуго́днаго житія́ на спасе́нія стезю́ нас путеводіте, зову́щих вам от душі́:","Ра́дуйтеся, світи́льници немерцающії Бо́жия благода́ті.","Ра́дуйтеся, столпи́ непоколеби́мії Святи́я Правосла́вния Це́ркве.","Ра́дуйтеся, подви́жници до́блії, по́двиги ва́шими Афо́н удобри́вшії.","Ра́дуйтеся, по́стници богому́дрії, во всю вселе́нную чудеси́ сія́ющії.","Ра́дуйтеся, би́серіє духо́внії, от удо́лій Афо́на в Сіо́ні го́рнем возблиставшії.","Ра́дуйтеся, добро́тою душ ва́ших Го́споду Ісу́су благоугоднії я́вльшіїся.","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Кондак 1","ps":["Ізбра́ннії уго́дниці Госпо́дні, духо́вно благоуха́ющії цві́ти са́да Ісу́сова, от Святи́я Гори́ Афо́нськия во вертогра́д небе́сний вознесеннії, і дерзнове́ніє ко Го́споду стяжа́вшії, мо́лим вас, отці́ богоно́снії, моли́твами ва́шими от вся́ких нас бід свободи́те, да зове́м вам хвале́бно:","Ра́дуйтеся, преподо́бнії отці́ Афо́нстії, усе́рднії о душа́х на́ших моли́твенниці."]},{"h":"Молитва","ps":["О блаже́ннії і святі́ї отці́, преподо́бнії, святи́теліє, священному́ченици і преподобному́ченици, мироточи́вії і чудотво́рці, земні́ї А́нгели і Небе́снії челові́ци, сея́ Святи́я Гори́ насе́льници і украси́теліє, по Богоро́дице на́ші предста́теліє пред Го́сподем, благоді́теліє і назира́теліє, ца́рськоє побідоно́сноє ополче́ніє, в тілесі́х побіди́вшеє безтіле́сния де́мони, Цари́ці Небе́сния Пречи́стия Богоро́диці мироуха́ннії цві́ти, світлоплодови́тая древеса́ ми́сленнаго сего́ рая́ Присноді́ви, ріки́ приснотеку́щия дарова́ній духо́вних! Приймі́те похва́льная словеса́ сія́, я́же вам прино́сим, я́коже Госпо́дь прия́т вдови́ці дві ле́пті, і о́бщеє пра́зднество, соверша́ємоє на́ми в честь і па́м'ять ва́шу, обиміте, я́ко воню́ благоуха́нія і же́ртву благоприя́тну: не і́мами бо і́но что принести́ по до́лгу благоді́телем на́шим за вели́кая благодія́нія, я́же прия́хом і і́мами прийти́ от вас. Єй, іспові́дуєм, я́ко ми гріх ра́ди на́ших ні́сми досто́йні жи́ти на мі́сті сем і іменова́тися синми́ ва́шими, но ви за благосе́рдіє ва́ше не отриця́йтеся би́ти нам отці́. Не забива́йте нас, смире́нних, но соблю́дайте свяще́нния монастири́ ва́ша і вся ски́ти і ке́ллії і нас, живу́щих в них, сохраня́йте і ізбавля́йте от вся́каго іскуше́нія і напа́сти в житії́ сем, в бу́дущем же ві́ці да сподо́бимся святи́ми ва́шими моли́твами блаже́нства ку́пно с ва́ми, си́нове со отці́ свої́ми, ста́до с па́стирі свої́ми, ученици́ со учи́тели свої́ми, і да усли́шим от вас о́ний блаже́нний глас ко Го́споду: се ми і ді́ти, я́же дал єси́ нам, Го́споди! І, ра́дующеся, воздади́м вся́кую сла́ву, честь і поклоне́ніє Отцю́ і Си́ну і Свято́му Ду́ху во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Пусти́ні Афо́нськия отці́, / А́нгели во пло́ті, / іспові́дники вку́пі і преподо́бния, / святи́телі же і му́ченики в пі́ніїх почти́м, / подража́юще доброді́телем їх, / зову́ще согла́сно і глаго́люще: / сла́ва Просла́вльшему ви, / сла́ва Вінча́вшему ви, // сла́ва в біда́х предста́телі нам ви Показа́вшему."]},{"h":"Кондак, глас 4","ps":["Онебеси́вшия Го́ру сію́, / і показа́вшия в ней житіє́ а́нгельськоє, / і мно́жество мона́хов собра́вшия отці́, / прийді́те, благохва́лим всі, к ним взива́юще: / вся́кия біди́ і іскуше́нія нас ізба́віте, / мно́жество преподо́бних, // Афо́нськая похвало́."]},{"h":"Величання","ps":["Ублажа́єм вас, / преподо́бнії отці́ Афо́нстії, / в горі́ сей пости́вшіїся, / і чтим святу́ю па́м'ять ва́шу, / наста́вници мона́хов / і собесі́дниці / А́нгелов."]}],"notes":[]},{"u":"Акафіст священномученику Йосифу, митрополиту Астраханському","e":"Akathist to the Hieromartyr Joseph, Metropolitan of Astrakhan","secs":[{"h":"Кондак 1","ps":["Ізбра́нний святи́телю і преди́вний уго́дниче Христо́в, Го́спода і лю́ди своя́ всім се́рдцем возлюби́вий, ду́шу свою́ за о́вці своя́ положи́вий, за мучи́телі своя́ Го́споду моли́вийся, священному́чениче Іо́сифе, крі́пкоє гра́да Астрахани огражде́ніє. Похва́льная воспису́єм ті, к ра́ці моще́й твої́х притека́юще, ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких бід нас свободи́ зову́щих:","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь во дні вели́ких бід і напа́стей, обише́дших оте́чество на́ше, восхоті́в лю́дем стра́ждущим утіше́ніє дарова́ти, яви́ тя, святи́телю Іо́сифе, челові́ком наста́вника, от ю́ности і до му́ченичеськой сме́рті возлюби́вшаго боже́ственноє уче́ніє. Сего́ ра́ди тебе́, на небесі́ і на землі́ просла́вленному, вопіє́м си́це:","Ра́дуйся, я́ко Бо́га і́стиннаго Отця́ на́шего із ді́тська позна́вий;","Ра́дуйся, от ю́ности путь мирська́го житія́ оста́вивий.","Ра́дуйся, чистоту́ се́рдця твоєго́ до конця́ сохрани́вий;","Ра́дуйся, осмилетнім от м'яте́жних люде́й во главу́ ударенний.","Ра́дуйся, от удара того́, да́же до сме́рти, главо́ю своє́ю трясенний;","Ра́дуйся, рассужденія да́ром почте́нний.","Ра́дуйся, о́бразом житія́ твоєго́ і нам путь к небесі́ показа́вий;","Ра́дуйся, всю жизнь свою́ Го́сподеві преда́вий.","Ра́дуйся, коєму́ждо во бла́го усе́рдно служи́вий.","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 2","ps":["Ви́дя Благопромислитель Госпо́дь душі́ твоєя́ добро́ту, напра́ви твой по́мисл ко іска́нію єди́наго на потре́бу. Ти же, сего́ возжела́в, єще́ от ю́ности нави́кл взива́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственний іми́й, всю суєту́ привре́менния жи́зні презрі́л єси́, святи́телю Іо́сифе; тім же оста́вив мир і вся я́же в нем, ізмла́да прия́л єси́ о́браз а́нгельський, всего́ себе́ отда́в на служе́ніє Го́споду і бли́жнім твої́м, да́же до сме́рти. Таково́є у́бо ізволе́ніє твоє́ восхваля́юще, глаго́лем ті сицева́я:","Ра́дуйся, я́ко путь пра́вий в Ца́рствіє Небе́сноє обрі́л єси́;","Ра́дуйся, я́ко сим путе́м невозвра́тно шел єси́.","Ра́дуйся, муче́ніє і смерть му́жественно прия́вий;","Ра́дуйся, ду́шу свою́ положи́вий за о́вці своя́.","Ра́дуйся, моли́твенниче ко Го́споду наш непреста́нний;","Ра́дуйся, во́лею своє́ю от беззако́нних в же́ртву принесе́нний.","Ра́дуйся, гра́да Астрахани і оте́чества на́шего святи́й покрови́телю;","Ра́дуйся, от творя́щих беззако́ніє і зло уклони́вийся.","Ра́дуйся, путь незло́бія спаси́тельнаго взиска́вий;","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю укріпля́єм, священному́чениче Іо́сифе, вся послуша́нія до́брі проходи́л єси́ во оби́телі Тро́їцькия і святи́тельськаго са́на дости́гнув, от беззако́нних мучи́телей сверженія со сті́ни гра́да претерпі́л єси́, жизнь свою́ страда́ньми за пра́вду увенчав, пресели́лся єси́ в небе́сния оби́телі, іді́же предстоя́ Престо́лу Святи́я Тро́йці, поє́ши: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я по́мисл чист і ду́шу непоро́чну, свяще́нства благода́ть досто́йно восприя́л єси́, святи́телю Іо́сифе; ті́мже во ігу́мена оби́телі ізбра́н є бил і са́ном архімандрі́та почте́н, ре́вностно подвиза́лся о спасе́нії Бо́гом врученного тебі́ слове́снаго стада́. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, я́ко вся послуша́нія і́ночеськая нелі́ностно проше́л єси́;","Ра́дуйся, я́ко сим на висоту́ доброді́телей возше́л єси́.","Ра́дуйся, і́ночествующих му́дрий наста́вниче;","Ра́дуйся, всіх благоче́стному житію́ науча́ющий.","Ра́дуйся, оте́чество земно́є моли́твами свої́ми не оставля́ющий;","Ра́дуйся, і по сме́рті твоє́й всім, с ві́рою к тебі́ притекающим, благода́ть істоча́ющий.","Ра́дуйся, і святи́ми моща́ми твої́ми с на́ми пребива́ющий;","Ра́дуйся, от святи́х моще́й твої́х ісціле́нія подава́ющий.","Ра́дуйся, путь із тьми гріхо́вной к невече́рнему сві́ту освещающий;","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 4","ps":["Бу́ри злосло́вія і людська́го м'яте́жа не убоя́лся єси́, святи́телю Іо́сифе, єгда́ укри́ в до́мі своє́м лю́ди беззащитния, увіща́я бо беззако́нних преста́ти от зла, не пролива́ти кро́ві, но в покая́нії обрати́тися ко Го́споду, взива́я Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша і ви́дя премно́гую твою́ доброді́тель, блаже́нний Ни́кон патріа́рх святи́теля тя нарече́ і па́ству Астраханськую смотре́нію твоєму́ вручи́. Ми же, о сем веселя́щеся, глаго́лем ті сицева́я:","Ра́дуйся, вся степе́ні і́ночеськаго зва́нія с че́стію і сла́вою проше́дий;","Ра́дуйся, на престо́лі святи́тельстім досто́йно возсі́дий.","Ра́дуйся, стра́же Це́ркви Христо́ви неустраши́мий;","Ра́дуйся, ді́лателю виногра́да Христо́ва неутоми́мий.","Ра́дуйся, о неві́жествіїх людськи́х печа́льниче;","Ра́дуйся, благовре́менні і безвре́менні па́ству твою́ поучавий.","Ра́дуйся, о́вці заблудшия ко Христу́ призва́вий;","Ра́дуйся, лю́ди во тьмі сидящия сві́том Христо́вим озари́вий.","Ра́дуйся, сим от поги́белі їх сохрани́вий;","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 5","ps":["Бу́рями жите́йськими іскушаєм, не убоя́лся єси́, святи́телю, ста́ти проти́ву беззако́нних, ча́шу бо страда́ній за пра́вду іспи́в, со сті́ни гра́да низве́ржен бил єси́ і, кро́вію своє́ю зе́млю обагри́в, непреста́нно взива́л Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя нестроє́нія во гра́ді Астрахани і ско́рбію о сем об'ят, поко́я не позна́л єси́, святи́телю Іо́сифе, Госпо́дь же даде́ зна́меніє с небесі́ о му́ченичеськой кончи́ні твоє́й, єя́же не убоя́вся, священному́ченик бил єси́, і с благоче́стієм к тебі́ прибегающим помо́щник в біда́х і болі́зніх яви́лся єси́, вопію́щим с любо́вію тебі́ такова́я:","Ра́дуйся, непреста́нними моли́твами се́рдце твоє́ освяти́вий;","Ра́дуйся, очеса́ твоя́ к не́бу всегда́, возводи́вий.","Ра́дуйся, сла́ву небе́сную па́че всего́ возлюби́вий;","Ра́дуйся, во єди́нім Бо́зі сла́дость житія́ полага́ти всегда́ вразумля́яй.","Ра́дуйся, до́брий во́їне Христо́в і пропові́дниче спасе́нія;","Ра́дуйся, се́рдця на́ша в єдиноми́слії і любве́ ко оте́честву на́шему направля́яй.","Ра́дуйся, уста́ми твої́ми прему́дрость глаголивий;","Ра́дуйся, світи́льниче Це́ркви Христо́ви, во тьмі ві́ка сего́ возсія́вий.","Ра́дуйся, лю́ди доброді́телі всегда́ науча́яй;","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 6","ps":["Пропові́дник смире́нія і ревни́тель благоче́стія сло́вом і житіє́м твої́м бил єси́, святи́телю Іо́сифе, возлюби́в бо Христа́, не устраши́лся єси́ муче́ній і, хули́ прия́в за ми́рния лю́ди, я́же в до́мі твоє́м укри́, воспі́л єси́ Го́сподеві піснь побі́дную: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ во страні́ Астраханстей і Терстей сві́том Христо́ва уче́нія і ре́вностію твоє́ю о сла́ві Бо́жієй, святи́телю богоблаже́нне, ти бо красоту́ Госпо́дню возлюби́в, о устроє́нії хра́мов святи́х і благочи́нії церковнім всеусе́рдно приліжа́л єси́. Сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, сла́ви Христо́ви ревни́телю;","Ра́дуйся, хра́мов святи́х строї́телю.","Ра́дуйся, благочи́нія церко́внаго стро́гий охрани́телю;","Ра́дуйся, тобо́ю бо це́рков Астраханськая благоукраси́ся.","Ра́дуйся, я́ко в ней ві́ра Христо́ва утверди́ся;","Ра́дуйся, гра́да Астрахани сла́во і украше́ніє.","Ра́дуйся, всім нам защи́та і огражде́ніє;","Ра́дуйся, Го́спода і лю́ди своя́ до конця́ возлюби́вий.","Ра́дуйся, ду́шу за дру́ги своя́ положи́вий;","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 7","ps":["Хотя́ на путь пра́вий покая́нієм лю́ди наста́вити, возстающим на тя дерзнове́нно глаго́лал єси́: “Преста́ніте у́бо от зол ва́ших і ми́лость і проще́ніє обрящіте”, — они́ же глу́си би́ша словесі́ твоєму́, распиха́хуся на тя і Ми́рона Богобоязненна, глаго́люща їм о свя́тости са́на твоєго́, умертви́ша, ти же, свя́те Іо́сифе, все упова́ніє на Бо́га возлага́я, воспіва́л: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя моли́твенника і чудотво́рця преди́вна яви́ Госпо́дь страні́ Росси́йстій і гра́ду Астрахани, святи́телю Іо́сифе убієнне. Взем бо меч духо́вний — сло́во Бо́жиє, беззако́нния от Боже́ственнаго писа́нія увіща́л єси́ пра́вий путь покая́нія обрісти́ в і́стинном от гріхо́в отвраще́нії. Сего́ ра́ди усе́рдно зове́м ті:","Ра́дуйся, ра́бе Госпо́день ві́рний;","Ра́дуйся, уго́дниче Єго́ нелицемі́рний.","Ра́дуйся, на ка́мені за́повідей Госпо́дніх утвержде́нний;","Ра́дуйся, беззако́нними на муки́ огне́м веще́ственним осужде́нний.","Ра́дуйся, рука́ми беззако́нних зауше́нний;","Ра́дуйся, свя́занний по рука́ма і нога́ма, на огні́ опаленний.","Ра́дуйся, от злих люде́й убієнний;","Ра́дуйся, душе́ю на не́бо восхище́нний.","Ра́дуйся, об оте́честві на́шем печа́льниче нелицемі́рний;","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханський землі́ стра́же."]},{"h":"Кондак 8","ps":["Стра́нно бі ви́діти стра́же нощні́й не́бо отве́рсто і огнь, на град ниспадающий. Ти же, свя́те Іо́сифе, сли́ша о сем, го́рко пла́кася в келії своє́й глаго́ля: “Ізлія́ся с небесі́ фія́л гні́ва Бо́жия”. Такова́го гні́ва ізба́ви нас, Го́споди, моли́твами священному́ченика Іо́сифа, Бо́гу воспіва́ющих: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь іспо́лнь любве́ Христо́ви, ду́шу твою́ за о́вці твоя́ положи́ти гото́в бил єси́, священному́чениче, не іски́й своя́, по́двигом до́брим подвиза́лся єси́, блаже́нне, оби́димих защища́я, печа́льних утіша́я, неви́нно убіє́нних благословля́я, продерзних і злих с кро́тостію облича́я і вразумля́я. Ни́ні же сві́тло ра́дуєшися, іді́же пра́вда і мир, і ра́дость о Го́споді на́шем. Сего́ ра́ди чтим святу́ю па́м'ять твою́ і усе́рдно вопіє́м ті:","Ра́дуйся, святи́телю благосе́рдний, о спасе́нії мно́гих поревнова́вий;","Ра́дуйся, не свої́х си, но бли́жняго іска́вий.","Ра́дуйся, стра́же неуси́пний, от волко́в хи́щних о́вці твоя́ охранявий;","Ра́дуйся, си́рих защи́тниче і оби́димих предста́телю.","Ра́дуйся, я́ко і ни́ні во вся́ких ну́ждах ско́ро нам помога́єши;","Ра́дуйся, засту́пниче наш неуси́пний.","Ра́дуйся, і к ра́ці моще́й твої́х с ві́рою притека́ющих ми́лостивно утіша́єши;","Ра́дуйся, я́ко в ра́йських оби́теліх ни́ні пребива́єши.","Ра́дуйся, гра́да Астрахани святи́й покрови́телю;","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 9","ps":["Вся по́мисли к Бо́гу возводи́л єси́, святи́телю Іо́сифе, єгда́ огне́м бо жегом бил єси́ і на смерть ві́домий, о́чі твоя́ го́ре імі́л єси́, моля́ся, я́ко первому́ченик Христо́в Стефа́н: “Го́споди, не пом'яни́ їм гріха́ сего́”. Ми же, воспомина́юще сія́, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не мо́жеть по достоя́нію восхвали́ти тя, ві́чния сла́ви досто́йнаго, священному́чениче Іо́сифе; в ри́зах бо святи́тельських вшел єси́ в нечести́вих собо́рище і дерзнове́нно, я́ко проро́к Бо́жий, глаго́лал єси́: “Почто́ зва́сте мене́? Оста́віте упорство ва́ше і зло́бу!” Они́ же, я́ко зві́ри ди́вії, жа́ждуще кро́ві твоєя́, скрежета́ху на тя зу́би свої́ми, преда́ти сме́рті хотя́. Ми же в похвалу́ тебі́ си́це глаго́лем:","Ра́дуйся, священному́чениче, я́ко в тебі́ всели́ся си́ла Христо́ва;","Ра́дуйся, я́ко і власяниця твоя́ честна́я, на неду́жния полагаємая, да́руєть їм ісціле́ніє.","Ра́дуйся, я́ко і гроб твой святи́й с ві́рою приходящим яви́ся неоскудной врачебницей;","Ра́дуйся, си́лою Христо́вою чудеса́ содіва́ющий.","Ра́дуйся, ми́лостію Бо́жиєю німи́м уста́ отверза́ющий;","Ра́дуйся, в со́нії і виді́нії по́мощ твою́ явля́ющий.","Ра́дуйся, расслабленним дарова́вий укріпле́ніє;","Ра́дуйся, бесноватих от наси́лія дия́вольськаго освобожде́ніє.","Ра́дуйся, врачу́ безме́здний, ту́не врачева́ніє всім подаю́щий;","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 10","ps":["Спасе́ніє ві́чноє унаслі́довал єси́, святи́телю Іо́сифе, я́ко звізда́ пресві́тлая, возсія́л єси́ во гра́ді Астрахани, іді́же роди́лся єси́, і за ві́рность Бо́гу му́ченичеськую смерть прия́л єси́. Ми же, чту́ще страда́нія твоя́, зове́м ті: “Святи́телю Іо́сифе убієнне, моли́ Христа́ Бо́га, да ізба́вить нас ві́чния муки́, вопію́щих Єму́: Аллилу́я”."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго, Го́спода Ісу́са, кро́тости подража́я, до́брими ді́ли зло побіжда́л єси́, богоблаже́нне Іо́сифе. Сам бо ри́зи своя́ совле́кл єси́ пред беззако́нними і, во власяниці (суконной оде́жді) пред ни́ми предста́в, на муче́нія веде́н бил єси́. Таково́є незло́біє твоє́ зря́ще, си́це тебі́ вопіє́м:","Ра́дуйся, священному́чениче, огне́м на землі́ опаленний, пла́мені ві́чнаго ізба́вленний;","Ра́дуйся, ум і се́рдце твоє́ посреді́ о́гненнаго муче́нія ко Го́споду устремивший.","Ра́дуйся, подо́бно отроко́м Вавило́нським, во огні́ пали́мий, взива́л єси́: “Бо́же, благослове́н єси́”;","Ра́дуйся, со о́німи о́троки і всі́ми святи́ми ликовству́єши ни́ні во Ца́рствії Небе́снім.","Ра́дуйся, кро́ткому Ісу́су поревнова́вий;","Ра́дуйся, Того́ благода́тію незло́біє стяжа́вий.","Ра́дуйся, зе́млю бо кро́тких наслі́довавий;","Ра́дуйся, смире́нія ра́ди Сами́м Господом возвеличенний.","Ра́дуйся, незло́бію і любві́ нас науча́ющий;","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 11","ps":["Пі́ніє немо́лчноє соверша́я у святі́й ра́ці моще́й твої́х, святи́телю Іо́сифе, покая́нія моли́тви за безу́міє отцов на́ших прино́сим, сле́зно глаго́ля: “Го́споди, да́руй їм проще́ніє моли́твами священному́ченика Твоєго́”, да всегда́ прославля́юще милосе́рдіє Бо́жиє, пою́ть: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ невеще́ственний ви́діша лю́ди на мі́сті, іді́же от паде́нія со сті́ни гра́да смерть от беззако́нних прия́л єси́, святи́телю Іо́сифе, просвіти́ у́бо моли́твами твої́ми і нас, в пучи́ні гріха́ погиба́ющих, да благода́рно вопіє́м ті:","Ра́дуйся, ві́ру, наде́жду і любо́в да́же до конця́ сохрани́вий;","Ра́дуйся, світи́льниче многосві́тлий, сві́том і́стиннаго богопозна́нія нас озари́вий.","Ра́дуйся, луче́ со́лнця пра́вди, теплото́ю Боже́ственния любве́ душі́ на́ша согріва́ющий;","Ра́дуйся, би́сере честни́й, сія́нієм небе́сния сла́ви се́рдця на́ша увеселивий.","Ра́дуйся, ка́меню драги́й, страну́ поволжськую украси́вий;","Ра́дуйся, бе́здну милосе́рдія Бо́жия нам призива́ющий.","Ра́дуйся, священному́чениче, лю́ди землі́ поволжстей не забива́ющий;","Ра́дуйся, в моли́твах с на́ми всегда́ пребива́ющий.","Ра́дуйся, за Го́спода расп'я́таго опаленний, із'язвленний і убієнний;","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 12","ps":["Благода́тію от Бо́га почте́нний боля́щия ісціля́ти і де́монов прогоня́ти священному́чениче Іо́сифе, тім же і нас, доброді́телі лише́нних і моли́тви не стяжа́вших, па́че же фарисея вознося́щихся, твоє́ю моли́твою ісціли́, да в сокруше́нії пожи́вши, ку́пно с тобо́ю Го́сподеві воспоє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ богоуго́дноє житіє́, святи́телю Іо́сифе, і на небесі́ от Бо́га просла́вленноє, велича́єм бесчисленния чудеса́ і ісціле́нія, у гро́ба твоєго́ би́вшая, і на неусипния моли́тви твоя́ упова́юще взива́єм ті си́це:","Ра́дуйся, посреді́ крамоли́, волне́ній і бі́дствій все земно́є житіє́ твоє́ проведший;","Ра́дуйся, житіє́ сіє́ благоче́стне сконча́вий.","Ра́дуйся, от Царя́ Небе́снаго віне́ць сла́ви приє́мий;","Ра́дуйся, не оста́вивий па́стви своє́й во времена́ напа́сти.","Ра́дуйся, мно́гая лише́нія пра́вди ра́ди претерпі́вий;","Ра́дуйся, се́рдце твоє́ сосу́д благода́ті соді́лавий.","Ра́дуйся, по убіє́нії гробо́м твої́м три лі́та во хра́мі стоявший;","Ра́дуйся, гробо́м сим покая́ніє люде́й принимавший.","Ра́дуйся, гра́да Астрахани і Це́ркві святі́й похвало́;","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 13","ps":["О пресла́вний уго́дниче Бо́жий, священному́чениче Іо́сифе! Прийми́ сіє́ от любве́ на́шея приноси́моє тебі́ благохвале́ніє і твої́м благоприя́тним хода́тайством ізба́ви нас от вся́ких бід і зол. Умоли́ Го́спода Бо́га оставле́ніє прегріше́ній нам дарова́ти, да сподо́бимся ку́пно с тобо́ю во ві́ки пі́ти: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь во дні вели́ких бід і напа́стей, обише́дших оте́чество на́ше, восхоті́в лю́дем стра́ждущим утіше́ніє дарова́ти, яви́ тя, святи́телю Іо́сифе, челові́ком наста́вника, от ю́ности і до му́ченичеськой сме́рті возлюби́вшаго боже́ственноє уче́ніє. Сего́ ра́ди тебе́, на небесі́ і на землі́ просла́вленному, вопіє́м си́це:","Ра́дуйся, я́ко Бо́га і́стиннаго Отця́ на́шего із ді́тська позна́вий;","Ра́дуйся, от ю́ности путь мирська́го житія́ оста́вивий.","Ра́дуйся, чистоту́ се́рдця твоєго́ до конця́ сохрани́вий;","Ра́дуйся, осмилетнім от м'яте́жних люде́й во главу́ ударенний.","Ра́дуйся, от удара того́, да́же до сме́рти, главо́ю своє́ю трясенний;","Ра́дуйся, рассужденія да́ром почте́нний.","Ра́дуйся, о́бразом житія́ твоєго́ і нам путь к небесі́ показа́вий;","Ра́дуйся, всю жизнь свою́ Го́сподеві преда́вий.","Ра́дуйся, коєму́ждо во бла́го усе́рдно служи́вий.","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Кондак 1","ps":["Ізбра́нний святи́телю і преди́вний уго́дниче Христо́в, Го́спода і лю́ди своя́ всім се́рдцем возлюби́вий, ду́шу свою́ за о́вці своя́ положи́вий, за мучи́телі своя́ Го́споду моли́вийся, священному́чениче Іо́сифе, крі́пкоє гра́да Астрахани огражде́ніє. Похва́льная воспису́єм ті, к ра́ці моще́й твої́х притека́юще, ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких бід нас свободи́ зову́щих:","Ра́дуйся, священному́чениче Іо́сифе, ві́рний Астраханськия землі́ стра́же."]},{"h":"Молитва","ps":["О, свяще́нная главо́, пресла́вний чудотво́рче, первопа́стирю святи́я Астраха́нськия це́ркві, святи́телю о́тче Іо́сифе! К тебі́ припа́даєм і мо́лимся ми, смире́ннії і грі́шнії, і я́ко отця́ чадолюби́ваго про́сим: всели́ в сердця́ на́ша любо́в, є́юже к Бо́гу і бли́жнім твої́м при жи́зні земні́й преіспо́лнен бил єси́, я́ко і ду́шу твою́ положи́л єси́, му́ченичеськи пострада́в. Научи́ нас, о́тче, подража́ти тебі́ ві́рно, Бо́га і бли́жніх на́ших люби́ти і́скренні і за́повіді Госпо́дні соверша́ти непогріши́тельно, да бу́дем і ми с тобо́ю ча́да Бо́жия, не по і́мені то́кмо, но і сами́м ді́лом і всім житіє́м на́шим. При́зри благоутро́бно на вся́кую ду́шу христия́нськую, ми́лості і по́мощі от тебе́ і́щущую. Бу́ди всім нам в болі́зніх ціли́тель, в ско́рбіх уті́шитель, в печа́ліх ізба́витель, в біда́х помо́щник, в час сме́ртний покрови́тель, да по́мощію моли́тв твої́х святи́х сподо́бимся і ми грі́шнії спасе́ніє ві́чноє получи́ти і Ца́рство Небе́сноє унаслі́довати. Єй, святи́телю Христо́в, не посрами́ упова́нія на́шего, є́же по Бо́зі і Пресвяті́й Богоро́дице на тя крі́пко возлага́єм, но яви́ нам многомо́щноє заступле́ніє, да хва́лим, сла́вим і велича́єм человіколю́біє ди́внаго во святи́х Свої́х Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 6","ps":["По́двигом до́брим подвиза́вся, / жизнь твою́ страда́ніями за пра́вду увенча́в, / пресели́лся єси́ в Небе́сния оби́телі, / іді́же предстоя́ Престо́лу Святи́я Тро́йці, / моли́, святи́телю Іо́сифе, // гра́ду А́страхани і оте́честву на́шему в ми́рі спасти́ся."]},{"h":"Кондак, глас 2","ps":["Я́ко звізда́ пресві́тлая, / возсія́л єси́, святи́телю Іо́сифе, во А́страхани, / іді́же роди́лся і воспита́лся єси́ / і за ві́рность Бо́гу і власте́м зако́нним му́ченичеськую смерть прия́л єси́. / Ми же, чту́ще страда́нія твоя́, зове́м ті: / святи́телю Іо́сифе, от м'яте́жников убіє́нний, // моли́ Христа́ Бо́га о душа́х на́ших."]},{"h":"Величання","ps":["І нра́вом прича́стник, / і престо́лом намі́стник апо́столом бив, / дія́ніє обрі́л єси́, Богодухнове́нне, / во виді́нія восхо́д, / сего́ ра́ди сло́во і́стини ісправля́я, / і ві́ри ра́ди пострада́л єси́ да́же до кро́ве, / священному́чениче Іо́сифе, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]}],"notes":[]},{"u":"Акафіст преподобній Олександрі Дівеєвській","e":"Akathist to our Venerable Mother Alexandra of Diveyevo","secs":[{"h":"Кондак 1","ps":["Ізбра́нная уго́днице Бо́жия, преподо́бная ма́ти на́ша Алекса́ндро! Велича́юще просла́вльшаго тя Го́спода, воспіва́єм ті похва́льная. Ти же, імі́ющи ве́ліє дерзнове́ніє ко Го́споду і Пречи́стій Єго́ Ма́тері, от вся́ких іскуше́ній і бід свободи́ тебі́ вопію́щих:","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Ікос 1","ps":["А́нгелов ви́шшая Всеми́лостивая Влади́чиця на́ша Пресвята́я Богоро́диця ізбра́ тя, Алекса́ндро чу́дная, я́ко рабу́ Свою́ і́стинную і воздви́же тя просла́вити і́м'я Си́на Своєго́ в землі́, четве́ртим уді́лом Єя́ нарече́нній. Ми же, ви́дяще Бо́жиє о тебі́ благоволе́ніє, со умиле́нієм глаго́лем ті такова́я:","Ра́дуйся, доброде́ланіє от ю́ности возлюби́вшая;","ра́дуйся, блаже́нство єва́нгельськоє стяжа́вшая.","Ра́дуйся, в ско́рбіх к тебі́ прибега́ющим поможе́ніє;","ра́дуйся, в печа́ліх ско́роє утіше́ніє.","Ра́дуйся, дів диве́євських благоти́шноє приста́нище;","Ра́дуйся, жена́м ти́хоє прибі́жище.","Ра́дуйся, вмісти́лище благода́ті Бо́жия;","Ра́дуйся, землі́ Ру́ськия пресла́вноє украше́ніє.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 2","ps":["Ви́дяще ізбра́нничество твоє́ в ди́вном о тебі́ Бо́жії промишле́нії, земна́го бо обру́чника лиши́вшися, і всю печа́ль на Го́спода возложи́вши, путь свой в Ки́єв упра́вила єси́ і та́мо во оби́телі Фло́ровськой под покро́вом Пресвяти́я Богоро́диці Небе́сному Жениху́ обручи́лася єси́, благода́рно взива́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум сви́ше приї́мши сло́ва Бо́жия: \"І́го бо Моє́ бла́го і бре́м'я Моє́ легко́ єсть\", – преподо́бная ма́ти, благо́є і́го Христо́во на себі́ под'я́ла єси́, бога́тство і сла́ву вре́менную презрі́вши, воі́стину Бо́гу послі́довала єси́; ті́мже і ми, прославля́юще Ди́внаго во святи́х Свої́х, воспіва́єм тебі́ си́це:","Ра́дуйся, свіще́, любо́вію Христо́вою горя́щая;","ра́дуйся, нищету́ Христо́ву возлюби́вшая.","Ра́дуйся, путе́м преподо́бних жен ше́ствовавшая;","ра́дуйся, свя́тости і му́дрости духо́вния іспо́лненная.","Ра́дуйся, ієре́єв ти́хая ра́досте;","ра́дуйся, мона́шествующих пра́вило.","Ра́дуйся, призива́ющих тя в моли́твах защи́тнице;","ра́дуйся, о нас пред Бо́гом хода́тайце.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго воі́стину осіни́ тя, єгда́ Небесе́ і землі́ Цари́ця яви́ся ті і повелі́ ізи́ти із оби́телі Фло́ровськия в зе́млю ізбра́нную Свою́, ю́же обіща́ указа́ти тебі́. І ми, сли́шаще о чу́дном повелі́нії сем, поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́ющи тща́ніє о по́двизі і́ночеськаго равноа́нгельнаго житія́, преподо́бная Алекса́ндро, я́ко і́стинний во́їн Христо́в на стра́жи се́рдця своєго́ стоя́щи, не ве́ровала єси́ а́біє виді́нію сему́, а́ки преле́стну могу́щу би́ти, прише́дши же ко отце́м Пече́рським, вся сія́ пове́дала єси́ їм. Усмотри́вше у́бо ті́ї ди́вную на тебі́ Бо́жию ми́лость, і Цари́цю Небе́сную я́ко я́зву бісово́м пропові́давше, благослови́ша іспо́лнити вся повелі́нная ті, нас же научи́ша пі́ти тебі́ такова́я:","Ра́дуйся, я́ко яви́ся тебі́ Воєво́да Взбра́нная;","ра́дуйся, я́ко сподо́билася єси́ сли́шати повелі́нія Честні́йшия Херуви́м.","Ра́дуйся, я́ко сла́вила єси́ Сла́внійшую без сравне́нія Серафи́м;","ра́дуйся, святи́ні чи́стоє і честно́є жили́ще.","Ра́дуйся, по́двига стра́нничества не убоя́вшаяся;","ра́дуйся, Небе́снаго Оте́чества пла́менні возжеле́вшая.","Ра́дуйся, доброді́телей вели́ких вмісти́лище;","ра́дуйся, отці́ Пече́рськими нарече́нная преблаже́нною.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 4","ps":["Бу́рю помишле́ній сумни́тельних утиша́ющи, тве́рдую ві́ру і упова́ніє на Бо́га возложи́вши, преподо́бная ма́ти, вся глаго́ли Цари́ці Небе́сния в се́рдці твоє́м сохрани́ла єси́. І оста́вивши оби́тель, іді́же помишля́ла єси́ до конця́ дній свої́х подвиза́тися, во іно́є мі́сто востекла́ єси́. Ми же, ше́ствію твоєму́ ра́дующеся, поє́м Всеблаго́му Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шащи о свя́тости житія́ і́ноков Саро́вських, ма́ти Алекса́ндро, востече́ ко оби́телі той. На путі́ же, близ хра́ма ві́си Диве́євськия па́ки удосто́їлася єси́ сли́шати пресла́дкий глас Преблагослове́нния Богоро́диці, указу́ющия на мі́сто сіє́, Є́ю возлю́бленноє. І обіща́ ті Пречи́стая умно́жити зді Го́споду Бо́гу служа́щих, тебі́ же ві́рою воспіва́ющих такова́я:","Ра́дуйся, возлю́бленная Цари́цею Небе́сною;","ра́дуйся, ізбра́нная в Христо́ви неві́сти.","Ра́дуйся, прише́дшая в зе́млю обітова́нную;","ра́дуйся, послу́шная во́лі Пречи́стия.","Ра́дуйся, ру́ці свої́ о нас к Бо́гу простира́ющая;","ра́дуйся, ві́ру правосла́вную утвержда́ющая.","Ра́дуйся, свя́тости ревни́тельнице;","ра́дуйся, преподо́бних ра́досте.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́ ви́дим тя, на Небесі́ сія́ющу в со́нмі святи́х, зе́млю Ру́ськую освеща́ющу і на путь пра́вий нас, во тьмі гріхо́вній заблу́ждших, направля́ющу, приводя́щу пі́ти Творцю́ в Тро́йці: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще тя, ма́ти преподо́бная, к наста́вником оби́телі Саро́вськия послуша́нія ра́ди прише́дшую і во́лі своєя́ совле́кшуюся, путе́м многотру́дним і ско́рбним ше́ствующую, Ду́ха Свята́го дара́ми обогати́вшуюся, о́браз смиренному́дрія зрим і поє́м тебі́ си́це:","Ра́дуйся, все своє́ імі́ніє обнища́вшему нас ра́ди Бо́гу преда́вшая;","ра́дуйся, во ве́ліїх труді́х житіє́ провожда́вшая.","Ра́дуйся, в пості́ і моли́тві Бо́гу угожда́ющая;","ра́дуйся, в ми́лості твоє́й не оскудіва́ющая.","Ра́дуйся, хра́ми мно́гія устроя́ющая;","ра́дуйся, су́щим в ну́ждах помога́ющая.","Ра́дуйся, о і́ноціх Саро́вських попече́ніє і промишле́ніє;","ра́дуйся, ни́щих і убо́гих наде́ждо і утіше́ніє.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 6","ps":["Пропові́дуєть житіє́ твоє́, ка́ко невозвра́тним жела́нієм Христу́ послі́довала єси́, блаже́нная ма́ти Алекса́ндро: єгда́ дщи твоя́ в ра́нних лі́тіх преста́вися, в сем Бо́жиє ізволе́ніє усмотри́вши, пі́ти научи́ла єси́ нас і в ско́рбі Творцю́ всіх: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ в тебі́ просвіще́ніє і́стини, єгда́ ра́зумом свої́м удивля́ла єси́ всіх к тебі́ приходя́щих, кро́тостію їх на путь пра́вий наставля́ющи і і́стини ві́ри правосла́вния раз'ясня́ющи, да всі у́зрять світ уче́нія Христо́ва; ми же с любо́вію взива́єм ті:","Ра́дуйся, ма́ти Алекса́ндро, Бо́гом науче́нная;","ра́дуйся, да́ром разсужде́нія от Него́ почте́нная.","Ра́дуйся, в милосе́рдії святи́телю Никола́ю подо́бная;","ра́дуйся, в ді́ліх благи́х стезя́ми єго́ ше́ствующая.","Ра́дуйся, немощни́м земледі́льцем в по́ли хлі́би пожина́ющая;","Ра́дуйся, во вре́м'я жа́тви младе́нці посіща́ющая.","Ра́дуйся, в ді́ліх жите́йських прему́драя упра́вительнице;","ра́дуйся, тепло́м і любо́вію ду́ші согріва́ющая.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 7","ps":["Хотя́щи положи́ти нача́ло устроє́нію оби́телі, преподо́бная ма́ти, три ке́ллії поста́вила єси́: єди́ную моли́тви ра́ди і уєдине́нія, іну́ю сестра́м, прише́дшим Бо́гу угожда́ти, і тре́тію странноприї́мну, да всі пою́ть Єди́ному Бо́гу в Тро́йці: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго хра́ма во сла́ву Преблагослове́нния Богоро́диці строї́тельниця яви́лася єси́, ма́ти Алекса́ндро, і от Каза́ни спи́сок явле́нния чудотво́рния іко́ни Єя́ Каза́нськия принесла́ єси́, да просла́виться і́м'я Присноді́ви Марі́ї на мі́сті сем, Є́ю возлю́бленнім, ми же благода́рственно зове́м ті:","Ра́дуйся, оби́телі Диве́євськия тве́рдоє основа́ніє;","ра́дуйся, я́ко тобо́ю на милосе́рдіє Бо́жиє все на́ше упова́ніє.","Ра́дуйся, в Ки́єві мо́щі преподо́бних Пече́рських іспроси́вшая;","ра́дуйся, во оби́телі Диве́євськой я́ко благослове́ніє сія́ поста́вльшая.","Ра́дуйся, в годи́ну гла́да лю́таго о́крест живу́щих пита́вшая;","ра́дуйся, моли́твою твоє́ю нас от бід сохраня́ющая.","Ра́дуйся, кро́ткая і му́драя в хра́мі Бо́жиєм распоряди́тельнице;","ра́дуйся, уста́ва церко́внаго усе́рдная храни́тельнице.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 8","ps":["Стра́нноє явле́ніє ви́димо бисть, єгда́ в нощі́ колінопреклоне́нно Го́споду моли́лася єси́, да ука́жеть во́лю Свою́ на освяще́ніє приді́ла хра́ма Каза́нськия іко́ни Бо́жия Ма́тере. Сего́ ра́ди явле́н ті бисть незри́мою руко́ю о́браз первому́ченика і архідия́кона Стефа́на. І ми, почита́юще єго́, воспіва́єм Всеблаго́му Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім се́рдцем свої́м, все́ю душе́ю і ми́слію Бо́га возлюби́вшая, ма́ти Алекса́ндро, первонача́льниця непреста́нной моли́тви в Диве́єві яви́лася єси́ і, дар благода́тних слез стяжа́вши, при́сно в трезве́нії пребива́ла єси́. Ми же, ві́дуще духо́вния по́двиги твоя́, глаго́лем такова́я:","Ра́дуйся, у іко́ни Бо́жия Ма́тере Живоно́сний Істо́чник сле́зи умиле́нія пролива́ющая;","ра́дуйся, о заблу́ждших і скорб'я́щих Бо́га умоля́ющая.","Ра́дуйся, преподо́бним Серафи́мом вели́кою і свято́ю нарече́нная;","ра́дуйся, в по́двизіх до́брих благослове́нная.","Ра́дуйся, стезю́ пра́вую нам указу́ющая;","ра́дуйся, во обстоя́ніїх тя зову́щим помога́ющая.","Ра́дуйся, о жи́тельствующих во оби́телі твоє́й я́ко о ча́діх попечи́тельнице;","ра́дуйся, оби́дящим їх стро́гая наказа́тельнице.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 9","ps":["А́нгелов ликостоя́нія див'я́ться твоєму́ милосе́рдію, ка́ко ле́гкими стопа́ми селе́ніє обходи́ла єси́ і, во смире́нії і́стиннім лю́дем по́мощ подава́ющи, о них усе́рдно Бо́гу моли́лася єси́; та́ко і нас научи́ ми́лости твори́ти, воздви́гни от лі́ності і нераде́нія, да всі ра́достно поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї многосло́внії не возмо́гуть ізрещи́ си́лу Бо́жию, в не́мощі тілесе́ твоєго́ я́вльшуюся, єгда́ в час отдохнове́нія от трудо́в і бді́нія, главу́ свою́ на ка́мень приклоня́ла єси́ і оде́ждею ве́тхою в зной і сту́жу ті́ло покрива́ла єси́; ми же, див'я́щеся сему́, вопіє́м ті такова́я:","Ра́дуйся, всім призива́ющим тебі́ ско́рая помо́щнице;","ра́дуйся, о лю́діх к тебі́ приходя́щих моли́твеннице.","Ра́дуйся, в біда́х і го́рестіх ніколи́же оставля́ющая;","ра́дуйся, к ра́йським селе́нієм призива́ющая.","Ра́дуйся, кла́дязь ціле́бния води́ іскопа́вшая;","ра́дуйся, єще́ жива́ су́щи, дар чудоді́йственния по́мощі стяжа́вшая.","Ра́дуйся, неісчерпа́ємая глубино́ любве́ і милосе́рдія;","ра́дуйся, о́бразе вели́каго к Бо́гу усе́рдія.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ всіх притека́ющих во оби́тель Диве́євськую, о отше́ствії во ві́чния оби́телі ізвести́ тя Госпо́дь, да попече́ніє о сестра́х диве́євських преподо́бному Серафи́му запове́дуєши. І ми недосто́йнії, покрови́телей такови́х на Небесі́ улучи́вше, благода́рственно воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ всім святи́м, Пресвята́я Ді́ва, ди́вно упра́ви отше́ствіє твоє́ от житія́ сего́ вре́меннаго: в схи́му бо вели́кую облече́нная, ти в час кончи́ни Святи́х Христо́вих Та́їн приобщи́лася єси́ і, ду́шу святу́ю в ру́ці Бо́жії преда́вши, ни́ні с ли́ки жен преподо́бних зри́ши Пресвяту́ю Тро́йцю. Ми же, восхваля́юще житіє́ твоє́, глаго́лем ті си́це:","Ра́дуйся, сестра́м Диве́євським преподо́бнаго Серафи́ма во отця́ іспроси́вшая;","ра́дуйся, світи́ло землі́ Ру́ськия в нем прозрі́вшая.","Ра́дуйся, чуде́сную по́мощ і по успе́нії твоє́м прося́щим подаю́щая;","ра́дуйся, у Престо́ла Бо́жия нас помина́ющая.","Ра́дуйся, о во́їніх, на по́ли бра́ні живо́т свой полага́ющих, Бо́га умоля́ющая;","ра́дуйся, рида́нія ма́терей о ча́діх утоля́ющая.","Ра́дуйся, пла́чущих і скорб'я́щих уті́шительнице;","ра́дуйся, о ро́ді христия́нстім пред Бо́гом предста́тельнице.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 11","ps":["Пі́ніє вознося́ всім святи́м, в землі́ Ру́сстій просія́вшим, страстоте́рпець цар Никола́й ревнова́ше о прославле́нії твоє́м, ма́ти Алекса́ндро, но пре́жде сам вінце́м му́ченичеським увінча́ся. Ми же, зря́ще ди́вноє ісполне́ніє ча́янія єго́, уми́льно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельная луча́, ко Христу́ устремле́нная, яви́ся житіє́ твоє́, і мно́жество і́нок ко оби́телем го́рнім ти привела́ єси́, і всі ча́ющії благода́тния по́мощі твоєя́ с любо́вію глаго́лють та́ко:","Ра́дуйся, от землі́ челові́ки возвиша́ющая;","ра́дуйся, кро́тости і незло́бію науча́ющая.","Ра́дуйся, із волн жите́йських утопа́ющих ізима́ющая;","ра́дуйся, свіще́, нощ гріхо́в разгоня́ющая.","Ра́дуйся, мона́шествующих укріпле́ніє;","ра́дуйся, слез го́рких осуше́ніє.","Ра́дуйся, істо́чник ціле́бния води́ подаю́щая;","ра́дуйся, больни́я і неду́жния ісціля́ющая.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 12","ps":["Благода́ть і ми́лость ізлива́єши, преподо́бная ма́ти на́ша Алекса́ндро, на всіх к тебі́ приходя́щих і к моще́м твої́м припа́дающих, і проще́ніє нам у Го́спода прося́щи, науча́єши нас пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще тебі́, ма́ти преподо́бная, восхваля́єм чудеса́ і ми́лости Бо́жия, явле́нния ро́ду челові́чеському святи́ми Єго́ уго́дники, і притека́юще во святу́ю оби́тель твою́, благода́рно взива́єм ті такова́я:","Ра́дуйся, ка́меню драги́й, Христо́ву Це́рков украша́яй;","ра́дуйся, оби́тель Диве́євськую от бід огражда́ющая.","Ра́дуйся, святу́ю во́лю Пречи́стия Богоро́диці іспо́лнившая;","ра́дуйся, дар слез благода́тних стяжа́вшая.","Ра́дуйся, я́ко смире́ніє твоє́ бисть неісповіди́мо;","ра́дуйся, я́ко люби́ твоя́ бисть ко всім нелицемі́рна.","Ра́дуйся, ко христия́нському житію́ наставля́ющая;","ра́дуйся, с ві́рою к тебі́ притека́ющим помога́ющая.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 13","ps":["О преди́вная уго́днице Бо́жия, преблаже́нная ма́ти на́ша Алекса́ндро! Прийми́ сіє́ ма́лоє тебі́ возноси́моє моле́ніє на́ше і не отступи́ от нас моли́твами твої́ми, но я́ко іму́щи дерзнове́ніє у Христа́ Бо́га на́шего, іспроси́ нам ми́лості і проще́нія в день су́дний, да проше́дше путь земна́го стра́нствія, невозбра́нно дости́гнем поко́я Ца́рствія Небе́снаго і со всі́ми святи́ми воспоє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов ви́шшая Всеми́лостивая Влади́чиця на́ша Пресвята́я Богоро́диця ізбра́ тя, Алекса́ндро чу́дная, я́ко рабу́ Свою́ і́стинную і воздви́же тя просла́вити і́м'я Си́на Своєго́ в землі́, четве́ртим уді́лом Єя́ нарече́нній. Ми же, ви́дяще Бо́жиє о тебі́ благоволе́ніє, со умиле́нієм глаго́лем ті такова́я:","Ра́дуйся, доброде́ланіє от ю́ности возлюби́вшая;","ра́дуйся, блаже́нство єва́нгельськоє стяжа́вшая.","Ра́дуйся, в ско́рбіх к тебі́ прибега́ющим поможе́ніє;","ра́дуйся, в печа́ліх ско́роє утіше́ніє.","Ра́дуйся, дів диве́євських благоти́шноє приста́нище;","Ра́дуйся, жена́м ти́хоє прибі́жище.","Ра́дуйся, вмісти́лище благода́ті Бо́жия;","Ра́дуйся, землі́ Ру́ськия пресла́вноє украше́ніє.","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Кондак 1","ps":["Ізбра́нная уго́днице Бо́жия, преподо́бная ма́ти на́ша Алекса́ндро! Велича́юще просла́вльшаго тя Го́спода, воспіва́єм ті похва́льная. Ти же, імі́ющи ве́ліє дерзнове́ніє ко Го́споду і Пречи́стій Єго́ Ма́тері, от вся́ких іскуше́ній і бід свободи́ тебі́ вопію́щих:","Ра́дуйся, преподо́бная ма́ти Алекса́ндро, первонача́льнице оби́телі Диве́євськия."]},{"h":"Молитва","ps":["О свята́я уго́днице Бо́жия, преподо́бная ма́ти на́ша Алекса́ндро! Прийми́ усе́рдния моли́тви на́ша, с ві́рою і любо́вію к тебі́ возноси́мия, і помози́ нам христия́нськия доброді́телі стяжа́ти, ві́ру крі́пкую і любо́в к Бо́гу і к бли́жнім імі́ти, крест скорбе́й і болі́зней в терпі́нії носи́ти. О госпожі́ на́ша і ма́ти! Прості́, благослови́, помоли́ся за нас, да і ми проще́ни бу́дем, і пом'яни́ нас у Престо́ла Бо́жия, да твої́ми моли́твами спаса́ємі в ни́нішнем ві́ці і в бу́дущем, сподо́бимся хвали́ти і воспіва́ти всесвято́є і́м'я Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Раба́ Христо́ва і ізбра́ннице Пречи́стия Єго́ Ма́тері, Ки́євського уде́ла Єя́ жи́тельнице і моли́твеннице, землі́ Єя́ обетова́нния іска́тельнице, Диве́євськия оби́телі первонача́льнице і зижди́тельнице, моли́ся за ни, Алекса́ндро преподо́бная, да спасе́ть нас Пресвята́я Богоро́диця і поми́луєть Свята́я Тро́йця, да ізба́вимся ми му́ки а́дськия і наслі́дуєм блаже́нство ра́йськоє."]},{"h":"Кондак, глас 3","ps":["Преподо́бная ма́ти Алекса́ндро, любо́в двуєди́ную к Бо́гу і бли́жнім твої́м стяжа́ла єси́ і ізбра́нницею Бо́жієй Ма́тері яви́лася. Єя́же послі́дній уді́л в землі́ Росси́стей обріла́ єси́, і Диве́євською первонача́льницею ста́ти сподо́бившися, вели́кому Серафи́му печа́ловатися о нем завіща́ла єси́. Зді же і поко́їшися с ним. Ни́ні моле́нія на́ша прийми́ і ко Го́споду вознеси́, да поми́луєть ни."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бная ма́ти Алекса́ндро, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобній Марфі Дівеєвській","e":"Akathist to our Venerable Mother Martha of Diveyevo","secs":[{"h":"Кондак 1","ps":["Ізбра́ннице Царя́ Небе́снаго, преподо́бній ма́тері на́шей Ма́рфі, в біда́х і ско́рбіх ско́рой помо́щнице, благода́рственноє пі́ніє прино́сим. Ти же, іму́щая предста́тельство пред Го́сподем, моли́ся о нас, любо́вію тебі́ зову́щих:","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Ікос 1","ps":["А́нгели на Небесі́ ра́довахуся, ви́дяще доброді́тельноє житіє́ твоє́, преподо́бная ма́ти Ма́рфо: яви́лася бо єси́ воі́стину іска́тельниця Небе́снаго би́сера, Ісу́са Христа́. Ми же, зря́ще по́двиги і труди́ твоя́, благода́рственно воспису́єм ті такова́я:","Ра́дуйся, плоди́ Ду́ха Свята́го в себі́ стяжа́вшая;","ра́дуйся, к ти́хому приста́нищу нас направля́ющая.","Ра́дуйся, окамене́нная сердця́ на́ша во умиле́ніє приводя́щая;","ра́дуйся, посреді́ скорбе́й ди́вний поко́й нам посила́ющая.","Ра́дуйся, от неча́янния сме́рти нас огражда́ющая;","ра́дуйся, от ко́зней дия́вольських нас заступа́ющая.","Ра́дуйся, із пучи́ни гріхо́в нас ізводя́щая;","ра́дуйся, ко Престо́лу Госпо́дню сердця́ на́ша вознося́щая.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 2","ps":["Ви́ді Влади́ка Небе́с душі́ твоєя́ добро́ту, я́ко уподо́билася єси́ му́дрим ді́вам, вся́кую сла́дость і сла́ву земну́ю презрі́вши. І ми всі, іму́ще такову́ю предста́тельницю о нас недосто́йних, прославля́єм просла́вльшаго тя Го́спода і поє́м Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Небе́сний тебі́ дарова́ся, ма́ти Ма́рфо, єгда́ послу́шала єси́ гла́са Бо́жия і, ше́дши с сестро́ю твоє́ю в пу́стинь Саро́вськую, ста́рця Серафи́ма дости́гла єси́. Ті́мже, ублажа́юще тя, взива́єм си́це:","Ра́дуйся, ізмла́да в позна́нії Бо́га ди́вно умудри́вшаяся;","ра́дуйся, а́ки єле́нь ко істо́чнику благода́ті Бо́жия устреми́вшаяся.","Ра́дуйся, а́нгельськоє житіє́ нам явля́ющая;","ра́дуйся, в стра́сі Бо́жиєм нас наставля́ющая.","Ра́дуйся, в терпі́нії і смире́нії своє́м Христу́ Бо́гу подража́вшая;","ра́дуйся, о проще́нії гріхо́в сле́зи пролива́вшая.","Ра́дуйся, вся плотські́я по́хоті Бо́га ра́ди умертви́вшая;","ра́дуйся, мно́гі ко́зні лука́ваго побіди́вшая.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ Серафи́ма преподо́бнаго, єгда́ благослови́ на і́ночеськоє житіє́ прише́дшую к нему́ ма́тер на́шу Ма́рфу. Ми же, див'я́щеся таково́й Прему́дрости Бо́жієй, вопіє́м Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи оби́тель Диве́євськая превели́коє сокро́вище, вседраги́я мо́щі твоя́, преподо́бная ма́ти Ма́рфо, лику́єть, і ми о сем ра́дости ісполня́ємся і с любо́вію воспіва́єм тебі́ такова́я:","Ра́дуйся, із пучи́ни отча́янія нас ізвлека́ющая;","ра́дуйся, во страда́ніїх Бо́га хвали́ти науча́ющая.","Ра́дуйся, мглу сомні́ній на́ших разсеява́ющая;","ра́дуйся, ізнемога́ющия си́ли на́ша на бо́дрость прелага́ющая.","Ра́дуйся, от тісноти́ земни́я го́ре ни вознося́щая;","ра́дуйся, ми́лости у Го́спода нам прося́щая.","Ра́дуйся, ду́ші на́ша от вся́кия скве́рни охраня́ющая;","ра́дуйся, в Небе́снім гра́де нас предваря́ющая.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 4","ps":["Бу́рю помишле́ній претерпі́вши і дия́вольськия си́ли побіди́вши, преподо́бная ма́ти Ма́рфо, пришла́ єси́ в приста́нище ти́хоє і безм'яте́жноє, іді́же поє́ши со всі́ми А́нгельськими Си́лами хвалу́ Бо́гові: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шахом о тебі́, ма́ти Ма́рфо, я́ко ди́вно от мирськи́я суєти́ к мона́шеському по́двигу призвана́ бі, і, єще́ ю́на су́щи, отве́рглася єси́ во́лі своєя́, і в зна́меніє отсіче́нія єя́ постри́гла єси́ власи́ глави́ своєя́. Сіє́ у́бо проізволе́ніє похваля́юще, воспіва́єм ті такова́я:","Ра́дуйся, благо́є і́го Христо́во на себі́ возложи́вшая;","ра́дуйся, ду́ші на́ша сві́том ві́ри просвіти́вшая.","Ра́дуйся, нас во страда́ніїх душе́вних подкрепля́ющая;","ра́дуйся, нас красото́ю любве́ украша́ющая.","Ра́дуйся, Бо́гом на Небесі́ і на землі́ просла́вленная;","ра́дуйся, віне́ць сла́ви і бога́тство нетлі́нноє приі́мшая.","Ра́дуйся, от суєти́ мирськи́я нас огражда́ющая;","ра́дуйся, незло́біє і кро́тость в сердця́ на́ша вселя́ющая.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 5","ps":["Богото́чния струї́ проізлива́ються тобо́ю, ма́ти на́ша Ма́рфо, всім бо се́рдцем приліпи́лася єси́ ко єди́ному Ві́чному Животу́ і красоті́ неізрече́нній, Ісу́су Христу́, пою́щи Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша сестри́ твоя́, преподо́бная ма́ти Ма́рфо, я́ко чу́до пресла́вноє сотвори́ с тобо́ю Госпо́дь: чрез служи́теля бо Своєго́ Серафи́ма сподо́би тя ві́діти ве́лія обітова́нія, я́же о сла́ві Диве́євстей. Сего́ ра́ди тебе́, вели́цій уго́днице Бо́жієй, взива́єм си́це:","Ра́дуйся, соверше́нства А́нгельськаго во о́трочестві дости́гшая;","ра́дуйся, за́повіді преподо́бнаго ніколи́же преступи́вшая.","Ра́дуйся, а́гнице Христо́ва, на землі́ благоче́стно пожи́вшая;","ра́дуйся, ю́ности і красоти́ своєя́ не пощади́вшая.","Ра́дуйся, послуша́нію нас науча́ющая;","ра́дуйся, целому́дріє і чистоту́ восхваля́ющая.","Ра́дуйся, к жела́ній кра́ю прише́дшая;","ра́дуйся, возлю́бленнаго Спа́са і Го́спода узре́вшая.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 6","ps":["Пропові́дуєть оби́тель Диве́євськая ско́роє заступле́ніє і предста́тельство твоє́ пред Го́сподем. Ти же, я́ко улучи́вшая дерзнове́ніє ко Влади́ці, не забу́ди ни, земна́я ча́да твоя́, вопію́щая Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́, я́ко кра́сная заря́, прехожде́ніє твоє́, ма́ти Ма́рфо, от землі́ на Не́бо. Сподо́билася єси́ получи́ти ми́лости от Го́спода і Пречи́стия Ма́тере Єго́ в Небе́сних оби́теліх. Сему́ Бо́жию о тебі́ благоволе́нію див'я́щеся, воспіва́єм си́це:","Ра́дуйся, честні́йшия Богоро́диці похвале́ніє;","ра́дуйся, о́бразе і́стиннаго смире́нія.","Ра́дуйся, вели́кая наста́внице терпі́нія;","ра́дуйся, лю́б'ящим і чту́щим тя хода́тайце спасе́нія.","Ра́дуйся, честно́є Христо́во ізбра́ніє;","ра́дуйся, непоро́чноє Бо́гові благоуха́ніє.","Ра́дуйся, боголюби́вих душ увеселе́ніє;","ра́дуйся, оби́телі Диве́євськия щі́те і огражде́ніє.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 7","ps":["Яви́ Человіколю́бець Госпо́дь моли́твенницю об оби́телі Дивеєвстей тя, преподо́бная ма́ти Ма́рфо, да всі сохраня́ємі предста́тельством твої́м воззову́ть Го́сподеві: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до пові́да о тебі́, ма́ти Ма́рфо, преподо́бний Серафи́м всім приходя́щим к нему́ во дні кончи́ни твоєя́; рече́ бо, я́ко мно́гих гріхо́в ізба́в'яться припа́дающії ко гро́бу твоєму́ і зову́щії тебі́ такова́я:","Ра́дуйся, от ю́ности Бо́гу послужи́вшая;","ра́дуйся, на землі́ благоче́стно пожи́вшая.","Ра́дуйся, ко врато́м жи́зні ві́чния нас приводя́щая;","ра́дуйся, во Ца́рствії Небе́снім пребива́ющая.","Ра́дуйся, я́ко тобо́ю сла́дости духо́вния насища́ємся;","ра́дуйся, я́ко моли́твою твоє́ю укріпля́ємся.","Ра́дуйся, оби́льно ісціле́нія істоча́ющая;","ра́дуйся, моли́тися прилі́жно нас призива́ющая.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 8","ps":["Стра́нствіє земно́є сконча́вши, вознесла́ся єси́, а́ки чи́стая голуби́ця, в неві́стник Христо́в, іді́же поє́ши со всі́ми послужи́вшими Бо́гу хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся і́нокини возра́довашася, єгда́ А́нгели прия́ша честну́ю ду́шу твою́, преподо́бная ма́ти Ма́рфо, і вознесо́ша ю во оби́телі Го́рнія, іді́же ни́ні предстої́ши Пресвяті́й Тро́йце. Ми же, див'я́щеся человіколю́бію Бо́жию, вопіє́м ті такова́я:","Ра́дуйся, гла́су Боже́ственния благода́ті прилі́жно внима́вшая;","ра́дуйся, сла́дкий мед і́стини і спасе́нія взиска́вшая.","Ра́дуйся, всю сла́ву земну́ю попра́вшая;","ра́дуйся, дух твой го́ре возноси́вшая.","Ра́дуйся, в пресві́тлий черто́г Жениха́ твоєго́ вше́дшая;","ра́дуйся, віне́ць воздая́нія приє́мшая.","Ра́дуйся, Христо́вою любо́вію уязвле́нная;","ра́дуйся, в бра́чную оде́жду облече́нная.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 9","ps":["А́нгели на Небесі́ і челові́ци на землі́ вку́пі возра́довахуся о обрі́тенії честни́х моще́й твої́х, преподо́бная ма́ти Ма́рфо. Ми же, ни́ні благодаря́ще Го́спода, я́ко дарова́ нам засту́пницю і моли́твенницю благу́ю, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не возмо́гуть досто́йно ізобрази́ти вели́чіє благодія́ній Бо́жиїх, угото́ванних во Ца́рствії Небе́снім всім лю́б'ящим Го́спода. Ми же, ма́ти Ма́рфо, я́ко соприча́стнице ра́дости неоскудіва́ємия, во умиле́нії се́рдця взива́єм ті си́це:","Ра́дуйся, на житіє́ вре́менноє я́ко на стра́нствіє взира́вшая;","ра́дуйся, і́ночеськаго чи́на ізмла́да іска́вшая.","Ра́дуйся, А́нгельськи в рай вознесе́нная;","ра́дуйся, Го́сподем благослове́нная.","Ра́дуйся, всесві́тлаго Ца́рства Христо́ва наслі́днице;","ра́дуйся, Безпло́тних чино́в собесі́днице.","Ра́дуйся, сла́дость Небе́сную во ві́ки вкуша́ющая;","ра́дуйся, те́плою моли́твою сердця́ на́ша согріва́ющая.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щи душа́м на́шим, ма́ти Ма́рфо, мо́лиши непреста́нно ми́лостиваго Го́спода, да не лиши́ть нас наслі́дія Небе́снаго Ца́рствія Своєго́, пою́щих Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Крі́пость необори́мая к тебі́ прибіга́ющих била́ єси́, ма́ти Ма́рфо. Бу́ди і ни́ні нам защи́тниця от вся́ких наві́тов вра́жиїх, ско́рая же помо́щниця в ну́ждах і ско́рбіх, да любо́вію зове́м ті такова́я:","Ра́дуйся, Христа́ да́же до сме́рти возлюби́вшая;","ра́дуйся, тве́рдую ві́ру в Про́мисл Бо́жий яви́вшая.","Ра́дуйся, несумні́нную наде́жду на милосе́рдіє Госпо́днє показа́вшая;","ра́дуйся, нелицемі́рною любо́вію нас об'я́вшая.","Ра́дуйся, помраче́нноє о́ко душ на́ших просвіща́ющая;","ра́дуйся, в до́брих ді́ліх нас му́дро наставля́ющая.","Ра́дуйся, ми́лости прося́щим подаю́щая;","ра́дуйся, путь к Небесі́ нам указу́ющая.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим ті, преподо́бная ма́ти Ма́рфо, пред [ра́кою моще́й і] святи́м о́бразом твої́м предстоя́ще і моля́щеся прилі́жно. Да укріпи́ть Госпо́дь ві́ру правосла́вную во оте́честві на́шем і іскорени́ть в нем вся є́ресі і раско́ли; да всі лю́діє єди́ними усти́ і єди́ним се́рдцем сла́в'ять Бо́га, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рно світи́ло бу́ди нам, ма́ти на́ша Ма́рфо, путеводя́щи от землі́ на Не́бо, да возмо́жем і ми в житії́ на́шем прославля́ти вели́коє і сла́вноє і́м'я Пресвяти́я Тро́йці і воспіва́ти тебі́ си́це:","Ра́дуйся, спаси́тельнаго безмо́лвія люби́тельнице;","ра́дуйся, соверше́ннаго терпі́нія храни́тельнице.","Ра́дуйся, во́льния нищети́ крест приі́мшая;","ра́дуйся, посто́м і бді́нієм Бо́гу угоди́вшая.","Ра́дуйся, путь пра́вий в Ца́рствіє Небе́сноє нам указу́ющая;","ра́дуйся, духо́вную му́дрость нам да́рующая.","Ра́дуйся, к Бо́гу все́ю душе́ю приліпля́тися науча́ющая;","Ра́дуйся, друг дру́га люби́ти нас призива́ющая.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 12","ps":["Благода́ть і ми́лость іспроси́ нам у Бо́га, ма́ти преподо́бная, вразумля́ющую і укріпля́ющую нас в ді́лі спасе́нія, да не безпло́дні яви́мся в час Суда́ Бо́жия, пою́ще: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще і сла́в'яще преди́вноє прославле́ніє твоє́, ублажа́єм тя, преподо́бная ма́ти Ма́рфо, я́ко те́плую моли́твенницю о нас пред Го́сподем, і с любо́вію возглаша́єм ті такова́я:","Ра́дуйся, благода́тію Пресвята́го Ду́ха приосіне́нная;","ра́дуйся, во оде́жду нетлі́нія облече́нная.","Ра́дуйся, неме́ркнущим сві́том ду́ші на́ша озаря́ющая;","ра́дуйся, на доброде́ланіє нас наставля́ющая.","Ра́дуйся, єди́наго Го́спода во вся дні живота́ своєго́ іска́вшая;","ра́дуйся, в Нем намі́ренія полага́вшая.","Ра́дуйся, оби́тель Богома́тернюю возлюби́вшая;","ра́дуйся, да́же до конця́ в ней пожи́вшая.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 13","ps":["О прехва́льная і пресла́вная преподо́бная ма́ти на́ша Ма́рфо! Прийми́ ми́лостивно от нас сіє́ ма́лоє моле́ніє, в похвалу́ тебі́ приноси́моє, і, предстоя́щи ни́ні Престо́лу Царя́ ца́рствующих, моли́ Всеблага́го Бо́га проба́вити ми́лость Свою́ на ни і на ро́ди родо́в на́ших, утверди́ти ни в правові́рії і благоче́стії, да воспіва́єм Єму́ чи́стим се́рдцем: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели на Небесі́ ра́довахуся, ви́дяще доброді́тельноє житіє́ твоє́, преподо́бная ма́ти Ма́рфо: яви́лася бо єси́ воі́стину іска́тельниця Небе́снаго би́сера, Ісу́са Христа́. Ми же, зря́ще по́двиги і труди́ твоя́, благода́рственно воспису́єм ті такова́я:","Ра́дуйся, плоди́ Ду́ха Свята́го в себі́ стяжа́вшая;","ра́дуйся, к ти́хому приста́нищу нас направля́ющая.","Ра́дуйся, окамене́нная сердця́ на́ша во умиле́ніє приводя́щая;","ра́дуйся, посреді́ скорбе́й ди́вний поко́й нам посила́ющая.","Ра́дуйся, от неча́янния сме́рти нас огражда́ющая;","ра́дуйся, от ко́зней дия́вольських нас заступа́ющая.","Ра́дуйся, із пучи́ни гріхо́в нас ізводя́щая;","ра́дуйся, ко Престо́лу Госпо́дню сердця́ на́ша вознося́щая.","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Кондак 1","ps":["Ізбра́ннице Царя́ Небе́снаго, преподо́бній ма́тері на́шей Ма́рфі, в біда́х і ско́рбіх ско́рой помо́щнице, благода́рственноє пі́ніє прино́сим. Ти же, іму́щая предста́тельство пред Го́сподем, моли́ся о нас, любо́вію тебі́ зову́щих:","Ра́дуйся, преподо́бная ма́ти на́ша Ма́рфо, моли́твами свої́ми оби́тель Диве́євськую не оставля́ющая."]},{"h":"Молитва","ps":["О богому́драя і ди́вная отрокови́це, сосу́де благода́ті Бо́жия, в простоті́ голуби́ней пожи́вшая, кро́тостію Небе́сною, чистото́ю і послуша́нієм просія́вшая, сотаї́ннице преподо́бнаго Серафи́ма, нача́льнице Диве́євських сесте́р в оби́теліх Небе́сних, госпоже́ і ма́ти на́ша Ма́рфо! Бу́ди лю́б'ящим і чту́щим тя хода́тайця спасе́нія, в стра́сі Бо́жиєм нас утверди́, да Го́рняя му́дрствуєм, а не земна́я, ізнемога́ющия си́ли на́ша на бо́дрость преміни́, в любві́ і єдиноми́слії укріпи́ і пом'яни́ нас грі́шних у Престо́ла Бо́жия во Ца́рствії Небе́снім. Амі́нь."]},{"h":"Тропар, глас 2","ps":["Равноа́нгельноє житіє́ стяжа́вшая, ди́вная отрокови́це і собесі́днице Преподо́бнаго Серафи́ма, Госпоже́ і ма́ти на́ша Ма́рфо, ни́ні в нетлі́нних мощеіх почива́єши і у Престо́ла Бо́жия предстої́ши, моли́ о нас Ми́лостиваго Бо́га Небе́снаго, Диві́єва нача́льнице."]},{"h":"Кондак, глас 8","ps":["Небе́сною кро́тостію, молча́нієм і неземно́ю ра́достію іспо́лнилася єси́, ю́ная і невиданная досе́лі в Дивеєві отрокови́це, преподо́бная ма́ти на́ша Ма́рфо, во вели́кую схи́му от преподо́бнаго Серафи́ма облече́нная; ті́мже водвори́лася єси́ с му́дрими ді́вами в Небе́сном черто́зі і со А́нгели Всецарю́ непреста́нно предстої́ши."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бная ма́ти Ма́рфо, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному благовірному князю Олегу Брянському","e":"Akathist to the Venerable Right-Believing Prince Oleg of Bryansk","secs":[{"h":"Кондак 1","ps":["Возбра́нний воєво́до правосла́вних і небе́сний засту́пниче Бря́нския землі́, князе́й ру́ських украше́ніє і мона́хов похвало́, оби́телі первоверхо́вних Апо́стол основа́телю і покрови́телю і о душа́х на́ших усе́рдний моли́твенниче, благода́рственная пі́нія прино́сим ті, глаго́люще:","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгельськія Си́ли ра́довахуся благоче́стію твоєму́, кня́же Оле́же, є́же ізмла́да благода́тію Бо́жиєю яви́л єси́, блага́го ко́рене блага́я отра́сль бив. Ми же сора́дуємся їм і я́ко Бо́жия ізбра́нника восхваля́єм тя си́це:","Ра́дуйся, благочести́вих роди́телей благослове́нний плод;","ра́дуйся, я́ко па́м'ять твоя́ почита́ється в род і род.","Ра́дуйся, от ю́ности Христа́ Бо́га те́плі возлюби́вий;","ра́дуйся, в се́рдці оби́тель Свято́му Ду́ху угото́вивий.","Ра́дуйся, богослуже́нію усе́рдно прилежа́вий;","ра́дуйся, Сло́вом Бо́жиїм ду́шу свою́ пита́вий.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя і сли́ша пра́ведноє житіє́ благові́рних сро́дников твої́х, Черни́говських князе́й Нико́ли Свято́ши і І́горя страстоте́рпця, му́ченика Михаї́ла і роди́теля твоєго́ Рома́на, єще́ же і дще́ре Михаї́лови преподо́бния Євфроси́нії Су́ждальськия, потща́лся єси́, свя́те Оле́же, подража́ти їм, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́нний от ю́ности стяжа́в, благові́рне кня́же Оле́же, не прельсти́лся єси́ су́єтною сла́вою княже́нія земна́го, почита́я сіє́ я́ко сугу́боє служе́ніє лю́дем Бо́жиїм, вруче́нним попече́нію твоєму́. Сего́ ра́ди прийми́ от нас сицева́я:","Ра́дуйся, любо́вію о Христі́ іспо́лнивийся;","ра́дуйся, оте́ць чадолюби́вий лю́дем яви́вийся.","Ра́дуйся, печа́льних благи́й уті́шителю;","ра́дуйся, в біда́х су́щим предста́телю.","Ра́дуйся, ни́щих і убо́гих пита́телю;","ра́дуйся, вдов і сиро́т покрови́телю.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Ду́ха Свята́го укріпля́єм, блаже́нне кня́же Оле́же, в ми́рі сем жив'я́, собла́знов єго́ удаля́лся єси́, уєдине́нно во вертогра́ді роди́телей твої́х водворя́яся; ті́мже і утвержде́нію ві́ри правосла́вния ревну́я, пе́рвую в землі́ Бря́нстей оби́тель во і́м'я святи́х апо́стол Петра́ і Па́вла основа́л єси́, да і́ноці єя́ непреста́нно воспіва́ють Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я богоприя́тноє жела́ніє от суєти́ мирськи́я удали́тися, укріпи́лся єси́ в нем, єгда́ і́ноці созда́нния тобо́ю оби́телі вку́пі с Пече́рськими принесо́ша от Ки́єва чудотво́рную іко́ну Богома́тере, моле́нія ра́ди неду́гующаго роди́теля твоєго́. Ті́мже ублажа́юще ізволе́ніє твоє́, вопіє́м ті та́ко:","Ра́дуйся, у́зький путь Христо́во возлюби́вий;","ра́дуйся, бога́тство і сла́ву ми́ра возненави́дівий.","Ра́дуйся, ру́ці на ра́ло Госпо́днє возложи́вий;","ра́дуйся, всп'ять лиця́ твоєго́ ніколи́же обрати́вий.","Ра́дуйся, Оте́чества Го́рняго дости́гнути возжелі́вий;","ра́дуйся, кня́жеськую діади́му ра́ди Небе́снаго вінця́ оста́вивий.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рею напа́стей коле́блемо оте́чество твоє́ зря, кня́же Оле́же, ага́ряни і злове́рними разоря́ємо, єще́ же і междоусо́бними бра́нями терза́ємо, щито́м ві́ри правосла́вния огради́вся, і мече́м моли́тви вооружи́вся, на враги́ ізше́л єси́, поя́ Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав отця́ твоєго́, благові́рнаго кня́зя Рома́на, во благодаре́ніє за ісціле́ніє оби́тель Све́нськую основа́вшаго і вся, єли́ки ви́ді прозре́вшима очи́ма, зе́млі єй дарова́вшаго, себі́ самаго́ в же́ртву Бо́гу прине́сл єси́, свя́те Оле́же, і во оби́тель сію́ всели́лся єси́. Сего́ ра́ди воспіва́єм тя си́це:","Ра́дуйся, взе́мий крест свой і Христу́ послі́довавий;","ра́дуйся, земни́я по́чести ні во что́же вміни́вий.","Ра́дуйся, по за́повіді Христо́вой смири́вийся;","ра́дуйся, господи́н бив і служи́тель всім соде́лавийся.","Ра́дуйся, люботру́дноє житіє́ ізбра́вий;","ра́дуйся, в пості́ і моли́твах пребива́вий.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ уподо́бился єси́, преподо́бне Оле́же, єгда́ от черто́га кня́жеська во оби́тель первоверхо́вних Апо́стол, я́ко в черто́г Небе́снаго Жениха́, преше́л єси́, о благостоя́нії Святи́я Це́ркве, благоустроє́нії оте́чества і спасе́нії душ вруче́нних ті Бо́гом люде́й усе́рдно моля́ся і со умиле́нієм поя́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше боголюби́вії лю́діє гра́да Бря́нська пра́ведноє житіє́ твоє́, Оле́же богоно́сне, попремно́гу че́ствоваху щедро́ти і по́двиги твоя́. Ти же смиренному́дренно благодаре́ніє Бо́гу приноси́л єси́, сего́ ра́ди і Той тя просла́ви і научи́ ві́рния воспіва́ти та́ко:","Ра́дуйся, дух пра́вия ві́ри укріпля́яй;","ра́дуйся, ре́вность по Бо́зі возгрева́яй.","Ра́дуйся, дія́нію богоми́сліє приложи́вий;","ра́дуйся, тщесла́віє і горди́ню сокруши́вий.","Ра́дуйся, дре́внім отце́м єдинонра́вний;","ра́дуйся, Бо́гом і людьми́ возлю́бленний.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник ві́ри правосла́вния і ревни́тель благоче́стія сло́вом і житіє́м бил єси́, богоблаже́нне кня́же Оле́же, єди́нім бо жела́нієм, подо́бно пра́деду твоєму́ равноапо́стольному кня́зю Влади́миру, горі́л єси́, да всі лю́діє землі́ твоєя́ присво́яться Христу́ і вку́пі с тобо́ю воспіва́ють Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ в де́бріх, град Брянск о́крест облежа́щих, я́ко у́тренняя заря́, і я́ко зві́зди небе́сния, озари́ша зе́млю на́шу доброді́телі твоя́, ї́миже і ни́ні просвіща́єши немо́лчно воспіва́ющих тя си́ми похва́льними словеси́:","Ра́дуйся, во Сві́ті невече́рнім пребива́яй;","ра́дуйся, ду́ші на́ша чудеси́ просвіща́яй.","Ра́дуйся, сто́лпе о́гненний в пусти́ні гріха́ блужда́ющим;","ра́дуйся, путево́дная звіздо́ на Не́бо ше́ствующим.","Ра́дуйся, нетлі́нієм тілесе́ от Бо́га почте́нний;","ра́дуйся, благода́тію Христо́вою облече́нний.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́й по́двигом до́брим подвиза́тися і ві́ру правосла́вную соблюсти́, преподо́бне о́тче Оле́же, от си́ли в си́лу ше́ствовал єси́, укріпля́я ум чте́нієм Боже́ственних слове́с і житі́й святи́х, і́мже подража́я, доброді́телі твоя́ сокри́ти от челові́к тща́лся єси́, воспіва́я Сердцеві́дцю Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя чудотво́рця яви́ Госпо́дь в землі́ Ру́ськой, Оле́же всече́стне, тобо́ю святу́ю правосла́вную ві́ру во гра́ді Бря́нске утвержда́я, і́же сві́тло красу́ється, імі́я тя Небе́снаго засту́пника і предста́теля ко Го́споду, і с любо́вію ті взива́єть:","Ра́дуйся, Правосла́вния Це́ркве во́їне добропобі́дний;","ра́дуйся, Русі́ святи́я моли́твенниче крі́пкий.","Ра́дуйся, землі́ Бря́нськия храни́телю;","ра́дуйся, Петропа́вловськия оби́телі огражде́ніє.","Ра́дуйся, єресе́й і раско́лов разори́телю;","ра́дуйся, душ і тіле́с на́ших ціли́телю.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нно і ди́вно бисть житіє́ твоє́, о́тче наш Оле́же, во оби́телі, єгда́ ігу́мен бив, преподо́бному Феодо́сію Кі́єво-Пече́рському подража́л єси́ і о́браз бра́тії в подви́жничеських труді́х явля́л єси́, вся послуша́нія нелі́ностно ісполня́я, во вре́тище одева́яся, вма́лі на дре́в'яні ло́жі поко́й імі́я, па́че же на всяк час неуста́нно вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся земля́ Бря́нськая ра́достію духо́вною подви́жеся, єгда́ святи́я мо́щі твоя́, достохва́льне кня́же Оле́же, многолі́тні во вре́м'я гоне́ній богобо́рчеських под спу́дом во оби́телі твоє́й храни́мия, па́ки яви́ Госпо́дь ві́рним лю́дем Свої́м, вопію́щим ті такова́я:","Ра́дуйся, сіте́й тлетво́рнаго гріха́ ізбежа́вий;","ра́дуйся, безстра́стієм ду́шу украси́вий.","Ра́дуйся, я́ко мо́щі твоя́ во укріпле́ніє ві́ри нам оста́вивий;","ра́дуйся, освяще́ніє притека́ющим к ним подава́яй.","Ра́дуйся, в ме́ртвеннім тілесі́ жизнь благода́тную явля́яй;","ра́дуйся, от моще́й твої́х чудеса́ істоча́яй.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ А́нгельськоє удиви́ся крі́пости душі́ твоєя́, богому́дре Оле́же, ка́ко соверше́н хотя́ би́ти, бога́тство я́ві і та́йні расточи́л єси́ нужда́ющимся і, нището́ю духо́вною обогати́вся, ра́достно Христу́ Спаси́телю послі́довал єси́, поя́ Тому́: Аллилу́я."]},{"h":"Ікос 9","ps":["Вети́йство челові́чеськоє не довлі́єть по достоя́нію восхвали́ти труди́, болі́зні і по́двиги твоя́, сла́вне кня́же Оле́же, я́же спасе́нія ра́ди душе́внаго под'я́л єси́, чрез все житіє́ неосла́бно плоть распина́я со страстьми́ і похотьми́. Ми же от простоти́ се́рдця любо́вію ублажа́єм тя си́це:","Ра́дуйся, во пло́ті а́ки безпло́тен на землі́ пожи́вий;","ра́дуйся, струя́ми сле́зними огнь страсте́й угаси́вий.","Ра́дуйся, терпі́нієм і кро́тостію дия́вола побіди́вий;","ра́дуйся, нището́ю духо́вною оде́жду нетлі́нія стяжа́вий.","Ра́дуйся, си́лу Воскресе́нія Христо́ва от моще́й твої́х проявля́яй;","ра́дуйся, зарю́ о́бщаго воскресе́нія нетлі́нієм моще́й показу́яй.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ся душа́м на́шим моли́ Человіколю́бця Бо́га, свя́те Оле́же, к тебі́ бо по Бо́зі і Пресвяті́й Богоро́дице усе́рдно прибіга́єм, я́ко ско́рому помо́щнику і те́плому хода́таю о землі́ Бря́нстей і о всіх правосла́вно в ней живу́щих і воспіва́ющих Го́споду: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тверда́ і покро́в ізря́ден бил єси́ в житії́ твоє́м і́ноком оби́телі твоєя́: о́ваго у́бо оте́чеськи назида́я, о́ваго кро́тці облича́я, іни́я же с любо́вію увіщава́я, ні́киїх стра́хом спаса́я, найпа́че же пред кончи́ною твоє́ю вся ко спасе́нію потре́бная запові́дал єси́ їм. Ті́мже і нас грі́шних упаси́, да с любо́вію зове́м ті:","Ра́дуйся, слове́сноє ста́до от волко́в охраня́яй;","ра́дуйся, заблу́ждшия о́вці усе́рдно взиску́яй.","Ра́дуйся, мечу́ Бо́жий, душевре́дния стра́сті посіця́яй;","ра́дуйся, щито́м твої́х моли́тв нас огражда́яй.","Ра́дуйся, мона́хом в по́двизіх укріпле́ніє;","ра́дуйся, всім ві́рним лю́дем поможе́ніє.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє прине́сл єси́ Пресвяті́й Тро́йце в час кончи́ни твоєя́, досточу́дне кня́же Оле́же. Хвала́ Бо́гу благоді́йствующу, — глаго́лал єси́, возлежа́ на сме́ртном о́дре, зрю уже́ брег мо́ря жите́йськаго, і́мже досе́лі ноша́шеся моя́ у́тлая ладія́. І со словеси́ си́ми ра́достно преше́л єси́ во оби́телі Го́рнія, іді́же со А́нгельськими ли́ки поє́ши піснь вели́кую: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́, у́глем благода́ті возжже́нную, ви́діша ученици́ лице́ твоє́, уго́дниче Бо́жий, во свято́м преставле́нії сві́том Небе́сним осія́нноє. Сего́ ра́ди, скорб разлуче́нія с тобо́ю ди́вним сим утіше́нієм раствори́вше, с тре́петом і ра́достію взира́ху на пречестни́я мо́щі твоя́ і отше́ствіє твоє́ просла́виша зва́нії си́ми:","Ра́дуйся, земно́є тече́ніє достохва́льне сконча́вий;","ра́дуйся, по труді́х вре́менних поко́й ві́чний улучи́вий.","Ра́дуйся, віне́ць безсме́ртния жи́зні приє́мий;","ра́дуйся, Престо́лу Вседержи́теля предстоя́й.","Ра́дуйся, любо́вію твоє́ю нас не оставля́яй;","ра́дуйся, чту́щия тя ми́лостивно посіща́яй.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть, да́нную ті, о́тче наш Оле́же, і ве́ліє твоє́ дерзнове́ніє пред Бо́гом ві́дуще, прилі́жно мо́лим тя: моли́ Ми́лостиваго Бо́га, да сохрани́ть Святу́ю Це́рков от єресе́й, раско́лов і нестроє́ній, оте́честву на́шему мир і благоде́нствіє да да́руєть, ві́рних же в Правосла́вії і єдиноми́слії да утверди́ть, пою́щих Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ди́вноє житіє́ твоє́ і честно́є преставле́ніє, богоно́сне о́тче Оле́же, чтим святу́ю па́м'ять твою́, я́ко Небе́снаго предста́теля і засту́пника, от Бо́га нам дарова́ннаго, і, припа́дающе к честни́м моще́м твої́м, прино́сим ті сицеви́я хвали́:","Ра́дуйся, в житії́ сем Бо́гу угоди́вий;","ра́дуйся, Ца́рствіє Небе́сноє наслі́дивий.","Ра́дуйся, я́ко с Го́рних висо́т на ни призира́єши;","ра́дуйся, я́ко град Брянск і оби́тель твою́ покрива́єши.","Ра́дуйся, преді́лов оте́чества на́шего защи́тниче;","ра́дуйся, христолюби́вому во́їнству побо́рниче.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 13","ps":["О свяще́нная главо́, преподо́бне благові́рне кня́же Оле́же, прийми́ сіє́ ма́лоє хвале́ніє от недосто́йних чад твої́х, і моли́твами твої́ми богоприя́тними Правосла́віє в землі́ Ру́ськой утверди́, град Брянск і оби́тель твою́ сохрани́ і душа́м на́шим спасе́ніє іспроси́, да с тобо́ю ни́ні і во ві́ки воспіва́єм Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськія Си́ли ра́довахуся благоче́стію твоєму́, кня́же Оле́же, є́же ізмла́да благода́тію Бо́жиєю яви́л єси́, блага́го ко́рене блага́я отра́сль бив. Ми же сора́дуємся їм і я́ко Бо́жия ізбра́нника восхваля́єм тя си́це:","Ра́дуйся, благочести́вих роди́телей благослове́нний плод;","ра́дуйся, я́ко па́м'ять твоя́ почита́ється в род і род.","Ра́дуйся, от ю́ности Христа́ Бо́га те́плі возлюби́вий;","ра́дуйся, в се́рдці оби́тель Свято́му Ду́ху угото́вивий.","Ра́дуйся, богослуже́нію усе́рдно прилежа́вий;","ра́дуйся, Сло́вом Бо́жиїм ду́шу свою́ пита́вий.","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Кондак 1","ps":["Возбра́нний воєво́до правосла́вних і небе́сний засту́пниче Бря́нския землі́, князе́й ру́ських украше́ніє і мона́хов похвало́, оби́телі первоверхо́вних Апо́стол основа́телю і покрови́телю і о душа́х на́ших усе́рдний моли́твенниче, благода́рственная пі́нія прино́сим ті, глаго́люще:","Ра́дуйся, преподо́бне кня́же Оле́же, Бря́нський чудотво́рче."]},{"h":"Молитва","ps":["О преподо́бне о́тче, благові́рне кня́же Оле́же, уго́дниче Христо́в усе́рдний, моли́твенниче ко Го́споду те́плий, защи́тниче в біда́х і уті́шителю в печа́ліх неуста́нний! Воззри́, преблаже́нне, ми́лостиво на град твой і виждь ча́да твоя́, смире́нно ті припа́дающая і служи́ти тебі́ хотя́щая. Не отве́ргни тре́бующия твоєя́ по́мощі, но, я́ко благоді́тель і хода́тай, моли́ при́сно Го́спода Бо́га і Спа́са на́шего Ісу́са Христа́, да благослови́ть страну́ Россі́йськую, в ми́рі і благові́рії ю сохраня́я, гра́ди умножа́я, достоя́ніє Своє́ соблюда́я. Вознеси́, богоно́сне о́тче наш, сіє́ ма́лоє моле́ніє недосто́йних раб твої́х Влади́ці Христу́, да утверди́ть во святі́й Правосла́вній Це́ркві живи́й дух пра́вия ві́ри і любве́, благоче́стіє непоколеби́мо, любому́дріє христопослі́довательно, да да́руєть па́стирем ре́вность попече́нія о спасе́нії люде́й, во є́же неві́рующія просвіти́ти, заблу́ждшия наста́вити, отпа́дшия обрати́ти і привлещи́. Ізря́дніє же, да вся ча́да Це́ркве Правосла́вния чи́сти сохрани́ть от мирськи́х іскуше́ній, по́хотей плотськи́х, суєму́дрія, суєві́рій і наважде́ній вра́жеських. Єй, уго́дниче Бо́жий, не пре́зри нас, моля́щихся тебі́, но помози́ нам ско́рим предста́тельством твої́м, да вся́ких бід, напа́стей і скорбе́й в сей жи́зні вре́менній избіжа́вше, кончи́ну непости́дну обріте́м, і та́ко на землі́ богоуго́дно пожи́вше, жи́зні ра́йськия на Небесі́ сподо́бимся, іді́же вку́пі с тобо́ю просла́вим человіколю́біє і щедро́ти в Тро́йці сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["От ю́ности возлюби́л Христа́ всім се́рдцем, преподо́бне, / сла́ву земну́ю я́ко преходя́щу оста́вил єси́, / і ца́рство земно́є в нічто́же вміни́в / ли́ку і́нок ра́достно приче́лся єси́, / і труди́ мно́гими град Брянск, а́ки со́лнце пресві́тло, озари́л єси́: / тім бив Тро́йці украше́ніє, // моли́, кня́же Оле́же, Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Уподо́бился єси́ плодоно́сней лі́торасли / от ко́рене честна́го, / Оле́же благоро́дне, / і́стину возлюби́в і нетлі́нний Христо́в живо́т. / Ті́мже моли́твою, бді́нієм і поще́нієм / світи́льник вели́кий бив твої́м ученико́м, // просвіти́, блаже́нне, оте́чество твоє́ і спаси́ ду́ші на́ша."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Оле́же, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Герасиму Йорданському","e":"Akathist to our Venerable Father Gerasimus of the Jordan","secs":[{"h":"Кондак 1","ps":["Ізбра́нника Бо́жия і чудотво́рця, Іорда́на насе́льника і храни́теля, отше́льником же о́браз і миря́ном, восхваля́єм тя, чти́телі твої́, богоно́се. Но я́ко імі́яй дерзнове́ніє ко Го́споду, от враг, тесня́щих ни, защити́, да зове́м ті:","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Ікос 1","ps":["А́нгел от челові́к бил єси́, преподо́бне, прите́к от землі́ к небе́сним. Ни́ні же со беспло́тними ра́дующася тя зря, ужаса́юся і стра́хом зову́ ті от душі́ сія́:","Ра́дуйся, Ликі́ї боже́ственний пло́де;","ра́дуйся, Іорда́на нетлі́нная сла́во.","Ра́дуйся, доброді́телі дру́же і́стинний;","ра́дуйся, Христа́ моєго́ служи́телю велича́йший.","Ра́дуйся, я́ко вся отда́л єси́ і приобрі́л Христа́;","ра́дуйся, я́ко вся в тщету́ вміни́л єси́ Єго́ ра́ди.","Ра́дуйся, я́ко удиви́шася ті А́нгели;","ра́дуйся, я́ко тебі́ і зві́ріє почто́ша.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 2","ps":["Ви́дя ми́ра сего́ тщету́ і жите́йських треволне́ній отріши́вся, богому́дре, разу́мно пре́жнім отце́м подража́л єси́, ї́хже за́повідем послі́дуя, восхожде́нія путь обрі́л єси́, Гера́симе. Сего́ ра́ди і Влади́ці твоєму́, блаже́нне, любо́вію вопія́л єси́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум іми́й пра́вий, ре́вностію диша́ боже́ственною, я́ко і́ний Анто́ній, свя́те Гера́симе, собра́нія мона́шеськая созва́л єси́, я́ко дре́вле от Єги́пта той. Ми же, к тебі́ взира́юще, взива́єм от се́рдця си́це:","Ра́дуйся, сто́лпе безмо́лвія;","ра́дуйся, чу́до воздержа́нія.","Ра́дуйся, в мона́шеськом житії́ ве́лій;","ра́дуйся, ізря́дний сего́ защи́тниче.","Ра́дуйся, Бо́гу нічто́же предпочти́й;","ра́дуйся, благоче́стно во і́м'я Єго́ подвиза́вийся.","Ра́дуйся, А́нгелов купножи́телю;","ра́дуйся, Сил Небе́сних слико́вниче.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 3","ps":["Си́лою сви́ше оболки́йся, блаже́нне, в пусти́ню удали́лся єси́, і я́ко ни́ву благопло́дну і до́бру сію́ показа́л єси́, му́дре, жела́ющим Ца́рство Христо́во стяжа́ти; ті́мже Христу́ поє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Іми́й боже́ственную ре́вность, Гера́симе, в се́рдці твоє́м, і боже́ственний світ, ісполня́яй є, восхожде́нія твори́л єси́ непреста́нно, і до́брую ку́плю тала́нтом соді́яв, ра́довался єси́, ми же, чудя́щеся, вопіє́м ті разу́мно сицева́я:","Ра́дуйся, висото́ богоми́слія;","ра́дуйся, смире́нія глубино́.","Ра́дуйся, безмо́лвія пла́меню неуси́пний;","ра́дуйся, воздержа́нія пра́вило вірні́йшеє.","Ра́дуйся, украше́ніє мона́хов трезвя́щихся;","ра́дуйся, похвало́ подви́жников доброді́тельних.","Ра́дуйся, сві́тлая преподо́бних красото́;","ра́дуйся, сла́вная святи́х добро́то.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 4","ps":["Ре́вности Госпо́дні горя́щей в душі́ твоє́й, Гера́симе, соєдини́лся єси́ А́нгелом, і себі́ сама́го сокро́вище свяще́нноє Тро́йці показа́в, преподо́бне, возглаша́л єси́ с ни́ми боже́ственную піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша живу́щії во страні́ Іорда́нстій сла́ву твою́, і теко́ша в пусти́ню ви́діти тя: ми же, сла́ву твою́ у престо́ла Вседержи́телева до́брі ві́дяще, моли́твенно к тебі́ в пусти́ні житія́ на́шего притека́єм, хва́ляще тя пі́нії такови́ми:","Ра́дуйся, му́дрий стадонача́льниче;","ра́дуйся, па́стирю наш до́брий.","Ра́дуйся, мона́хов руководи́телю;","ра́дуйся, в по́двизі су́щих предста́телю.","Ра́дуйся, світи́ло Іорда́на ясні́йшеє;","ра́дуйся, лампа́до пусти́ні пресві́тлая.","Ра́дуйся, і́мже просла́вися Бог;","ра́дуйся, і́мже враг посрами́ся.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 5","ps":["Богоно́сець ве́лій і сла́вний і́ноков нача́льник всіх прийма́ше ра́достно і я́ко світи́льник просвіща́ше поуче́ньми свої́ми, ві́дий вся, да дости́гнуть Недостижи́маго і лику́юще возопію́ть: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша ли́ци пусти́нних отце́в Гера́сима честна́го на Іорда́ні, і я́ко Па́вла почита́юще єго́ і но́ваго Анто́нія, тща́щагося сих путе́м слі́довати, див'я́щеся вопія́ху си́це:","Ра́дуйся, звіздо́, боже́ственную сві́тлость явля́ющая;","ра́дуйся, огню́, тьму вра́жию отгоня́ющий.","Ра́дуйся, я́ко попра́л єси́ напа́сти дия́вольськия;","ра́дуйся, я́ко смири́л єси́ де́монськую горди́ню.","Ра́дуйся, із глубини́ страсте́й воззва́ніє;","ра́дуйся, омраче́нних зло́бою ісправле́ніє.","Ра́дуйся, ста́да твоєго́ защи́тителю і ізба́вителю;","ра́дуйся, учени́к твої́х наста́вниче і учи́телю.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 6","ps":["Прибі́жище боже́ственноє пусти́ню Іорда́нськую ві́дий, та́мо поспеши́л єси́, жестоти́ єя́ і зно́я ніка́коже убоя́вся, всему́дре, но ра́дуяся от се́рдця вопія́л єси́ Спа́су, поя́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ твоєя́ оби́телі сла́ва, ю́же на Іорда́ні созда́л і распространи́л єси́, треблаже́нне, подвиза́нія ра́ди в чи́стім житії́: мно́жества же неісче́тная мона́хов в сей прия́л єси́, і́же, ви́дяще по́двиги твоя́, взива́ху тебі́ такова́я:","Ра́дуйся, я́ко земна́я преміни́л єси́ в небе́сная;","ра́дуйся, я́ко от ю́ности послі́довал єси́ Христу́.","Ра́дуйся, за́повідей Христо́вих пропові́дниче;","ра́дуйся, отмета́ющих їх секи́ро прео́страя.","Ра́дуйся, преда́ній пусти́ні сохране́ніє;","ра́дуйся, всіх сопроти́вних упраздне́ніє.","Ра́дуйся, і́мже і́ноці хва́ляться;","ра́дуйся, і́мже мирсті́ї возвиша́ються.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 7","ps":["Хотя́ ко істо́чнику води́ живи́я прини́кнути, ви́ну поуча́лся єси́ в зако́ні Госпо́дні, і сего́ ра́ди непоколеби́м я́ко ка́мень показа́лся єси́, і яви́лся крі́пок во іскуше́ніїх, і позна́лся от отце́в соверше́н, і́же ви́дяще льва, во́ду нося́ща, чудя́хуся, вопію́ще: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий показа́л єси́ град пусти́ню Іорда́нськую, Гера́симе, всечестни́й о́тче, і́бо сію́ я́ко іну́ю Фиваї́ду і Нитрі́ю мона́хов іспо́лнил єси́, вопію́щих ті ни́ні во Ца́рствії та́ко:","Ра́дуйся, Євфи́мію єдинонра́вне;","ра́дуйся, Анто́нію єдиноре́вностне.","Ра́дуйся, Ону́фрію равноче́стне;","ра́дуйся, Пахо́мію раностоя́тельне.","Ра́дуйся, я́ко Агафо́ну подража́л єси́ честно́му;","ра́дуйся, я́ко Паї́сію поревнова́л єси́ сла́вному.","Ра́дуйся, іми́й Арсе́нієво горе́ніє;","ра́дуйся, подвиза́вийся в Па́мвовом несмея́нії.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 8","ps":["Насажде́нноє при ісхо́дищих вод дре́во ду́ха яви́лся єси́, богому́дре, і сего́ ра́ди і́ноці, плоди́ неув'яда́ємия на тебі́ ви́дяще, дивля́хуся, пою́ще: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бив во ви́шніх, пречу́дний, ни́жніх же отдаля́яся, отхожда́ше Гера́сим боже́ственний, укра́шен доброді́тельми, от всіх же люби́м і восхваля́єм си́це:","Ра́дуйся, пусти́ні ди́вний цві́те;","ра́дуйся, в безво́дній істо́чниче чу́дний.","Ра́дуйся, освяще́ніє спаси́тельноє;","ра́дуйся, кади́ло богоприя́тноє.","Ра́дуйся, ве́лій в подвиза́нії;","ра́дуйся, бо́лій в мудрова́нії.","Ра́дуйся, і́мже преле́стник посрами́ся;","ра́дуйся, і́мже сатана́ низве́ржеся.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ челові́чеськоє удиви́ся, богому́дре, всесоверше́нно стра́нному і чуде́сному: льва бо послушли́ва зря́ху всі і во́ду нося́ща, і всіх подвиза́юща пі́ти: Аллилу́я."]},{"h":"Ікос 9","ps":["Подвиза́ющимся ізба́витель в пусти́ні показа́лся єси́, Гера́симе, і чуде́с іспо́лнь, се́рдце бо твоє́ храм Бо́жий бі чист і присносві́тел, преподо́бне. Сего́ у́бо ра́ди див'я́щеся, ві́рно вопіє́м ті:","Ра́дуйся, ли́ки і́ночеськия обра́довавий;","ра́дуйся, на лу́чшеє тіх наста́вивий.","Ра́дуйся, мона́хов боже́ственноє похвале́ніє;","ра́дуйся, ві́рних непрестаю́щеє весе́ліє.","Ра́дуйся, я́ко побіди́л єси́ дия́вольськая шата́нія;","ра́дуйся, я́ко порази́л єси́ того́ ко́зні.","Ра́дуйся, чту́щих тя при́сная защи́то;","ра́дуйся, помина́ющим тя по́моще ізві́стная.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 10","ps":["Созда́теля на́шего і Спаси́теля, со преподо́бними на Небесі́х пребива́я, моли́, о́тче, да ми́лостивно пре́зрить гріхи́ на́ша: нас бо ра́ди показа́ся по нам челові́к, да ізба́вить ни бу́дущия геє́нни. Тім благода́рно взива́єм Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ мона́шествующим на Іорда́ні показа́лся єси́ і всім к тебі́ притека́ющим, сего́ ра́ди моли́ся о нас, вельми́ чту́щих тя і любо́вію воспіва́ющих си́це:","Ра́дуйся, святи́х благоукраше́ніє;","ра́дуйся, ли́ка преподо́бних соприча́стниче.","Ра́дуйся, Іларіо́на подо́бниче;","ра́дуйся, Харито́на ревни́телю.","Ра́дуйся, Симео́на юро́диваго сла́во;","ра́дуйся, Іоа́нна по́стника си́ло.","Ра́дуйся, боже́ственнаго Кирія́ка управи́телю;","ра́дуйся, свята́го Ни́кона ликова́ніє.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 11","ps":["Пі́нію всегда́ прилежа́й і бді́нію непреста́нну, А́нгелом уподо́бился єси́, блаже́нне: Євфи́мію бо усо́пшу, ду́шу єго́ на Небеса́ восходя́щую зрел єси́, Го́споду же усе́рдні со А́нгели піл єси́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ сий в пусти́ні, просвіща́л єси́ ученики́ твоя́ во страні́ Іорда́нстій: вжига́яй бо огнь невеще́ственний, наставля́л єси́ к ра́зуму боже́ственному вся, му́дре просвіща́я їх, і́же благода́рно вопія́ху ті сія́:","Ра́дуйся, мона́хов слу́хи возвеселя́яй;","ра́дуйся, сих мно́жества к Бо́гу приведи́й.","Ра́дуйся, новонача́льних в кинові́ю прийма́вий;","ра́дуйся, усоверши́вшихся в пусти́ню отсила́вий.","Ра́дуйся, подви́жников свяще́нная сла́досте;","ра́дуйся, і́ноков небе́сная ра́досте.","Ра́дуйся, і́мже похваля́ються благогові́йнії;","ра́дуйся, і́мже охраня́ються цілому́дрії.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 12","ps":["Ра́дуяся, преподо́бне, подвиза́лся єси́ во мно́зім безмо́лвії со отці́ богоно́сними, удаля́яся в пусти́ню вре́мене ра́ди поста́ і вку́пі со всі́ми поя́: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́ши ни́ні со А́нгели на Небесі́, я́ко ні́когда на землі́ с челові́ки, трисвяту́ю піснь Бо́гу, Єго́же, сла́вне Гера́симе, всегда́ моли́ о нас, чту́щих тя і сла́в'ящих пі́сньми сицеви́ми:","Ра́дуйся, хода́таю на́шего спасе́нія;","ра́дуйся, це́ркве сла́во і благоуха́ніє.","Ра́дуйся, правосла́вних стіно́ і огражде́ніє;","ра́дуйся, христия́ном вели́кий наста́вниче.","Ра́дуйся, любве́ сугу́бия сокро́вище;","ра́дуйся, те́плий наш предста́телю.","Ра́дуйся, соблюда́яй ни в час сме́ртний;","ра́дуйся, непости́дний о нас моли́твенниче.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 13","ps":["О всечестни́й о́тче Гера́симе, мона́хов сві́тлосте, Христа́ моєго́ служи́телю! Прийми́ моле́ніє сіє́ ма́лоє і твої́ми к Бо́гу моли́твами от вся́кия ізба́ви напа́сти всіх вопію́щих Тому́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел от челові́к бил єси́, преподо́бне, прите́к от землі́ к небе́сним. Ни́ні же со беспло́тними ра́дующася тя зря, ужаса́юся і стра́хом зову́ ті от душі́ сія́:","Ра́дуйся, Ликі́ї боже́ственний пло́де;","ра́дуйся, Іорда́на нетлі́нная сла́во.","Ра́дуйся, доброді́телі дру́же і́стинний;","ра́дуйся, Христа́ моєго́ служи́телю велича́йший.","Ра́дуйся, я́ко вся отда́л єси́ і приобрі́л Христа́;","ра́дуйся, я́ко вся в тщету́ вміни́л єси́ Єго́ ра́ди.","Ра́дуйся, я́ко удиви́шася ті А́нгели;","ра́дуйся, я́ко тебі́ і зві́ріє почто́ша.","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Кондак 1","ps":["Ізбра́нника Бо́жия і чудотво́рця, Іорда́на насе́льника і храни́теля, отше́льником же о́браз і миря́ном, восхваля́єм тя, чти́телі твої́, богоно́се. Но я́ко імі́яй дерзнове́ніє ко Го́споду, от враг, тесня́щих ни, защити́, да зове́м ті:","Ра́дуйся, преподо́бне Гера́симе, всепочита́ємий пустинножи́телю."]},{"h":"Молитва","ps":["О свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Гера́симе! Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х твої́х і благоприя́тних моли́твах к Бо́гу. Пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́: не премолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя. Помина́й нас недосто́йних у престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу: і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх і вся́кия пре́лести бісо́вськия і ко́зней дия́вольських, па́стирю наш до́брий. А́ще бо і мо́щі твоя́ сокрове́ни би́ша на землі́, но свята́я твоя́ душа́ со А́нгельськими во́їнстви, со Безпло́тними ли́ки, с Небе́сними Си́лами, у Престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться. Ві́дуще у́бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас всеси́льному Бо́гу, о по́льзі душ на́ших, і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на Не́бо, от мита́рств же го́рких, бісо́во возду́шних князе́й і от ві́чния муки́ да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со безнача́льним Єго́ Отце́м, і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["В тебі́, о́тче, ізві́стно спасе́ся, є́же по о́бразу: / приї́м бо крест, послі́довал єси́ Христу́, / і ді́я учи́л єси́ презира́ти у́бо плоть, прехо́дить бо, / приліжа́ти же о душі́, ве́щі безсме́ртній. // Ті́мже і со А́нгели сра́дується, преподо́бне Гера́симе, дух твой."]},{"h":"Кондак, глас 4","ps":["Возгорі́вся раче́нієм Го́рнім, / же́стость пусти́ні Іорда́нови па́че всіх ми́ра сла́дких предпоче́л єси́; / отону́дуже повину́ся тебі́ звір да́же до сме́рти, о́тче, / послу́шні і жа́лостні на гро́бі твоє́м сконча́ся, / просла́вльшу тя та́ко Бо́гу, / к Нему́же моля́ся, і о нас, // о́тче Гера́симе, помина́й."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Гера́симе, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Зосимі Верховському","e":"Akathist to our Venerable Father Zosimas of Verkhovo","secs":[{"h":"Кондак 1","ps":["Ізбра́нному сви́ше на по́двиги і́ночества преподо́бному отцю́ на́шему Зоси́мі похва́льноє прино́сим пі́ніє. Ти же, преподо́бне о́тче, предста́тельствуй у Престо́ла Бо́жия за нас, многогрі́шних чад твої́х, да зове́м ті:","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Ікос 1","ps":["А́нгелом сви́ше предуста́влен бисть, преподо́бне о́тче Зоси́мо, на служе́ніє Бо́гу, єгда́, єще́ во чре́ві ті су́щу, оте́ць твой в нощі́ на моли́тві усли́ша глас: си́на, і́же ті роди́тися і́мать, не учи́ мирськи́м нау́кам, но зако́ну Бо́жию то́кмо. Ті́мже, восхваля́юще тя, зове́м:","Ра́дуйся, уго́дниче Бо́жий предизбра́нний;","ра́дуйся, моли́твенниче і засту́пниче, от Бо́га нам дарова́нний.","Ра́дуйся, я́ко житіє́м оте́чеським внима́л єси́;","ра́дуйся, я́ко ду́шу свою́ сло́вом Бо́жиїм пита́л єси́.","Ра́дуйся, сокро́вище ви́шніх разумі́ній;","ра́дуйся, научи́вийся ісполне́нію Боже́ственних велі́ній.","Ра́дуйся, у пеще́р преподо́бнаго Авраа́мія Смоле́нськаго воспита́нний;","ра́дуйся, послуша́нія і моли́тви ді́лателю неуста́нний.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 2","ps":["Ві́дая от ю́ности, я́ко прехо́дить о́браз ми́ра сего́, о́тче Зоси́мо, отре́клся єси́ су́єтнаго житія́, служе́нію царю́ земно́му предпоче́т служе́ніє Царю́ Небе́сному, да со всі́ми святи́ми вопіє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум і́стинний от Бо́га сви́ше восприя́л єси́, єгда́ не прельсти́ся імі́нієм ве́ліїм, і усли́шал єси́ глас Бо́жий, глаго́лющ, я́ко путе́м і́ночеським тещи́ і́маши. Ті́мже і бога́тство су́єтноє нівочто́же вміни́л єси́, ми же зове́м ті:","Ра́дуйся, суєті́ мирсте́й не подклони́вийся;","ра́дуйся, о Бо́зі Спа́сі твоє́м возвесели́вийся.","Ра́дуйся, імі́ніє ве́ліє ра́ди Бо́га отве́ргий;","ра́дуйся, путь ті́сний, і́мже не мно́зі ше́ствують, ізбра́вий.","Ра́дуйся, я́ко нищету́ во́льную Го́спода ра́ди предпоче́л єси́;","ра́дуйся, я́ко бога́тство бла́гости Бо́жия восприя́л єси́.","Ра́дуйся, пре́жде всего́ Ца́рствія Небе́снаго іска́вий;","ра́дуйся, мно́гі труди́ любве́ ра́ди ко Го́споду под'я́вий.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю сви́ше осіне́нний, весь ум свой, всю ду́шу і се́рдце устреми́л єси́ на служе́ніє Бо́гу в зва́нії і́ночестім, воспіва́я Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Ре́вность по Бо́зі восприї́м, оста́вил єси́ мир і я́же в ми́рі, ко отце́м пусти́нником в ліса́ Ро́славльськия прите́кл єси́. І житія́ подви́жничеськаго взиску́я, всего́ себе́ ста́рцю Васили́ску пре́дал єси́, да послуша́нієм і отверже́нієм себі́ Ца́рство Бо́жиє приобря́щеши, сего́ ра́ди вопіє́м ті такова́я:","Ра́дуйся, стро́гости житія́ пусти́нничеськаго поревнова́вий;","ра́дуйся, плод послуша́нія і терпі́нія до́брі показа́вий.","Ра́дуйся, благослове́нієм ста́рця Адрія́на в по́двизіх утвержде́нний;","ра́дуйся, отверже́нія себі́ сама́го ді́лателю усе́рдний.","Ра́дуйся, богому́дрих наста́вник ре́вностний учениче́;","ра́дуйся, отце́в добротолю́бія богоно́сний сонаслі́дниче.","Ра́дуйся, преє́мник і́стиннаго ста́рчества Бо́гом показа́нний;","ра́дуйся, от чад преподо́бнаго Паї́сія о́ноє восприє́мий.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 4","ps":["Ві́дий преподо́бний Васили́ск, я́ко не подоба́єть вступа́ти в по́двиги пустинножи́тельства не іспита́нним пре́жде в і́ночестім о́бщем житії́, та́ко упра́ви тя, о́тче Зоси́мо, да с со́нмом і́нок вопіє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Ста́рцю Васили́ску повину́яся, прите́кл єси́ во оби́тель Коне́вськую і та́мо в послуша́нії у ста́рця Адрія́на среди́ бра́тії преби́л єси́. Ті́мже, удивля́ющеся трудо́м твої́м і вну́тренним боре́нієм во оби́телі сей, зове́м:","Ра́дуйся, ре́вность в тя́жціх труді́х яви́вий;","ра́дуйся, послуша́ніє ста́рцю твоєму́ сохрани́вий.","Ра́дуйся, кро́тостію, зло препобежда́ющею, себі́ украси́вий;","ра́дуйся, плод пра́вди, соу́з доброді́телей в себі́ возрасти́вий.","Ра́дуйся, я́ко терпі́нієм твої́м любо́во в се́рдці возже́гл єси́;","ра́дуйся, я́ко тщесла́віє дале́че от себе́ отгна́л єси́.","Ра́дуйся, уче́нієм святооте́чеським внима́вий;","ра́дуйся, па́че всіх бога́тств нищету́ Христо́ву восприє́мий.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 5","ps":["Равноа́нгельнаго житія́ взиска́в, преподо́бне о́тче, всено́щними бді́нії, труди́, же́сткия власяни́ци ноше́нієм плоть свою́ смири́л єси́, ду́хом горя́ і воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ві́дая, я́ко благоче́стіє на вся поле́зно єсть, о́тче Зоси́мо, святи́х оте́ць уче́нію приліжа́л єси́, найпа́че же о моли́тві серде́чній, єго́же і пові́дал єси́ ста́рцю твоєму́ Васили́ску. Ми же, не іму́щії ре́вности о таково́м ді́ланії, но твої́м заступле́нієм у Бо́га іспроси́ти ю наді́ющіїся, зове́м ті:","Ра́дуйся, при нача́лі по́двига твоєго́ ре́вность по Бо́зі показа́вий;","ра́дуйся, до конця́ житія́ твоєго́ сію́ удержа́вий.","Ра́дуйся, я́ко непреста́нно в моли́тві пребива́л єси́;","ра́дуйся, я́ко чистоту́ по́мислов от Бо́га получи́л єси́.","Ра́дуйся, я́ко рукоді́лієм многоразли́чним приліжа́л єси́;","ра́дуйся, я́ко ті́ми мно́гих бра́тій напита́л єси́.","Ра́дуйся, к трезве́нію ві́рния приводя́й;","ра́дуйся, росо́ю благода́ті ду́ші на́ша ісполня́яй.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 6","ps":["Ди́внії подви́жници оби́телі Коне́вськия яви́шася святі́ї Зоси́ма і Васили́ск, я́ко тіх ра́ди мно́зії лю́діє притека́ху в ню. Оба́че не восхоті́ша преподо́бнії сла́ви і многолю́дства, но то́чію житія́ безмо́лвнаго в пусти́ні, да та́мо воспою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Ві́рнії ді́лателіє послуша́нія преби́ша преподо́бнії Зоси́ма і Васили́ск, єгда́ іспо́лниша благослове́ніє ста́рця своєго́ Адрія́на преби́ти с ним во оби́телі Коне́встій, а́ще і вельми́ жела́ша житія́ пусти́ннаго. По отше́ствії же того́, о́тче Зоси́мо, во смире́нії от служе́нія ігу́менськаго уклони́лся єси́, да лу́чшеє в пусти́нном безмо́лвії улучи́ши. Ті́мже ті зове́м:","Ра́дуйся, от ста́рця Васили́ська сотаї́нником нарече́нний;","ра́дуйся, в противостоя́нії вою́ющим на ни страсте́м і́ноче соверше́нний.","Ра́дуйся, сла́дость безмо́лвія пусти́ннаго вкуси́вий;","ра́дуйся, посто́м і воздержа́нієм плоть твою́ ду́хові покори́вий.","Ра́дуйся, показа́вий сла́вния над ми́ром, пло́тію і дия́волом побі́ди;","ра́дуйся, в чистоті́ сохрани́вий мона́шеськия обі́ти.","Ра́дуйся, я́ко благо́є і́го Госпо́днє с любо́вію поне́сл єси́;","ра́дуйся, я́ко сего́ ра́ди кро́ток і смире́н се́рдцем яви́лся єси́.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 7","ps":["Во́лю Бо́жию о мі́сті пусти́ннаго пребива́нія взиску́юще, мно́гая мі́ста іспита́ша святі́ї Зоси́ма і Васили́ск, оба́че не бисть во́ля Бо́жия, да поки́нуть ста́рці страну́ Россі́йськую. О сем ми, ра́дующеся, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Світи́ла вели́кая яви́стеся землі́ Сиби́рстій, преподо́бнії Зоси́мо і Васили́сче, єгда́ на безмо́лвноє жи́тельство та́мо пресели́стеся. Кто бо ісчи́слить лише́нія і боре́нія ва́ша, бді́нія же, і злострада́нія, я́же та́мо преби́ша вам? Ти же, о́тче Зоси́мо, томи́м вельми́ іскуше́нії дия́вольськими, проти́ву і́мене Бо́жия воздвиза́ємими, от ста́рця Васили́ська укріпля́єм, вся претерпі́л єси́, вя́щшую любо́в ко Го́споду стяжа́в. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, пусти́нниче соверше́нний, стрі́ли разжже́нния дия́вольськия угаси́вий;","ра́дуйся, непреста́нним призива́нієм і́мене Ісу́сова бісо́вськия полки́ порази́вий.","Ра́дуйся, безмо́лвія рачи́телю, пусти́ню духо́вно уплодоноси́вий;","ра́дуйся, подви́жничеським житіє́м твої́м сію́ просла́вивий.","Ра́дуйся, мно́гажди от немину́ємия сме́рті си́лою Бо́жиєю сохране́нний;","ра́дуйся, сла́ву Бо́гу за вся воздая́й, подви́жниче смире́нний.","Ра́дуйся, созида́нія і возстановле́нія святи́х оби́телей до́брий ревни́телю;","ра́дуйся, чи́на житія́ і́ночеськаго в тіх благи́й насади́телю.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 8","ps":["Провозві́стници путі́ у́мнаго ді́ланія яви́шася в землі́ Ру́ськой преподо́бнії Зоси́ма і Васили́ск, єгда́ в безмо́лвії тому́ приліжа́ще, воспі́ша Бо́гу немо́лчную піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Просія́ житіє́ ва́ше, отці́ преподо́бнії Зоси́мо і Васили́сче, не в Россі́ї то́чію, но і дале́че су́щим, во о́браз житія́ всім в пусти́ні хотя́щим спасти́ся. Ті́мже і послі́дующії подвиго́м ва́шим, тобо́ю, о́тче Зоси́мо, ізложе́нним, плод мног принесо́ша, восхваля́юще тя си́це:","Ра́дуйся, благода́тная ді́йствія моли́тви у́мния списа́вий;","ра́дуйся, по́двиги сомоли́твенника твоєго́ ми́ру возвісти́вий.","Ра́дуйся, я́ко назида́нієм твої́м ві́ра мно́гих утверди́ся;","ра́дуйся, я́ко о уче́нії твоє́м чин і́ночеський возвесели́ся.","Ра́дуйся, дре́во благопло́дноє, при вода́х пусти́нних возраще́нноє;","ра́дуйся, предста́телю наш пред Бо́гом, равноа́нгельноє житіє́ показа́вий.","Ра́дуйся, ве́ліє утіше́ніє Ду́ха Свята́го стяжа́вий;","ра́дуйся, по кончи́ні твоє́й Ца́рство Небе́сноє улучи́вий.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 9","ps":["Во́лі Бо́жієй повину́яся, прите́кшия к тебі́ сестри́ в послуша́нії подвиза́тися прия́л єси́. О сем і возда́л єси́ сла́ву Бо́гу ку́пно со ста́рцем Васили́ском, я́ко обріта́ються ду́ші, жела́ющия послужи́ти Тому́ єди́ному. Ти́я же і до днесь притека́ють под кров оби́телі твоєя́, вопію́ще: Аллилу́я."]},{"h":"Ікос 9","ps":["Мно́гія труди́ под'я́л єси́, о́тче Зоси́мо, в устроє́нії душ сестр, вве́рившихся руковожде́нію твоєму́, найпа́че же ско́рби і гоне́нія непра́ведная. Ти же вся сія́ до конця́ претерпі́л єси́, да устро́їши спасе́ніє себе́ і приходя́щих к тебі́. Ми же ві́дуще, я́ко сего́ ра́ди мзда твоя́ мно́га на Небесі́х, вопіє́м ті:","Ра́дуйся, ізгна́ніє пра́вди ра́ди претерпі́вий;","ра́дуйся, терпі́нієм твої́м нас наста́вивий.","Ра́дуйся, в кро́тости і смире́нії святи́м мно́гим подража́вий;","ра́дуйся, о́браз, ка́ко подоба́єть претерпіва́ти поноше́ніє і гоне́ніє, нам оста́вивий.","Ра́дуйся, я́ко моли́твами твої́ми сро́дниці твої́ в чи́ні і́ночестім Бо́гу послужи́ша;","ра́дуйся, я́ко мно́гия сестри́ подража́ти їм благопоспеши́ша.","Ра́дуйся, оби́тель во і́м'я Одиги́трії основа́вий Бо́жиїм смотре́нієм;","ра́дуйся, я́ко та і до ни́ні жела́ющим рабо́тати Бо́гові приста́нище єсть спасе́нія.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 10","ps":["От ю́ности твоєя́, о́тче Зоси́мо, ді́вственноє житіє́ возлюби́л єси́, в пості́ і моли́твах пребива́я і благоугожда́я Бо́гові, во є́же би́ти тебі́ освяще́нним сосу́дом Ду́ха Свята́го, все́льшагося в чи́стоє се́рдце твоє́ і воздиха́нії неізглаго́ланними научи́вшаго тя благоприя́тно пі́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ неруши́мая і Путеводи́тельниця ди́вная яви́ся Ма́тер Бо́жия во всем житії́ твоє́м, преподо́бне о́тче. Ті́мже і пре́жде успе́нія твоєго́ проре́кл єси́ сестра́м оби́телі своєя́: Ма́тер Бо́жия, Є́йже аз вручи́х вас і всю оби́тель сію́, просла́вить і́м'я Своє́ на мі́сті сем і удиви́ть на вас ми́лость Свою́. Ми же, сбитіє́ сего́ зря́ще, зове́м:","Ра́дуйся, Ма́тере Бо́жия благогові́йний служи́телю;","ра́дуйся, оби́телі і́ночеськия во і́м'я Єя́ основа́телю.","Ра́дуйся, Пресвяти́я Богоро́диці покро́вом о3сене́нний;","ра́дуйся, все упова́ніє твоє́ на Цари́цю Небе́сную возложи́вий.","Ра́дуйся, в ско́рбіх і ра́достіх во вся дні своя́ к Присноді́ві прибіга́вий;","ра́дуйся, по отше́ствії твоє́м от житія́ сего́ Бо́гом і людьми́ просла́вленний.","Ра́дуйся, я́ко в го́рній Ієрусали́м благо́ю Путеводи́тельницею упра́влен бил єси́;","ра́дуйся, я́ко сего́ ра́ди всім ше́ствующим к Небесі́ помо́щник от Бо́га яви́лся єси́.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє прино́сим ті, о́тче Зоси́мо, і всеусе́рдно про́сим: научи́ ни блюсти́ себе́ от ожесточе́нія серде́чнаго, от разоре́нія єдиноду́шія і от охлажде́нія дружелю́бія, да пребу́дем в любві́ Бо́жієй, я́же о Христі́ Ісу́се, і со всі́ми святи́ми, угоди́вшими Бо́гу, сподо́бимся воспіва́ти: Аллилу́я."]},{"h":"Ікос 11","ps":["Спаси́тельнаго ді́ланія наста́вник многому́дрий воі́стину яви́лся єси́, богоно́сне о́тче Зоси́мо, ти бо в писа́ніїх твої́х о ді́ланії духо́внім возвісти́л єси́, о стяжа́нії благода́ті Всесвята́го Ду́ха і творе́нії моли́тви Ісу́сови. Ми же тя, в бді́нії і моли́тві подвиза́вшагося, до́ндеже Го́сподеві пре́дал єси́ святу́ю ду́шу твою́, воспіва́єм:","Ра́дуйся, богому́дрия писа́нія до́брі оста́вивий нам в до́броє назида́ніє;","ра́дуйся, посо́бниче на́шему в терпі́нії і моли́тві возраста́нію.","Ра́дуйся, пра́здности і́щущих і труда́ бе́гающих обличи́телю;","ра́дуйся, о стяжа́нії такови́ми доброді́телей і́ночеських нелицеприє́мний попечи́телю.","Ра́дуйся, ре́вностію о ді́ланії моли́твеннім нас обогаща́яй;","ра́дуйся, да́ри бла́гості і кро́тости нас преобража́яй.","Ра́дуйся, я́ко подви́жник іску́сен преби́л єси́;","ра́дуйся, я́ко о́браз пра́ваго прохожде́нія мона́шеськаго житія́ яви́л єси́.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 12","ps":["Благода́ті Боже́ственния сосу́д яви́лся єси́, преподо́бне, єгда́ а́ще і неду́гом ве́ліїм одержи́м бя́ше, непреста́нную моли́тву твори́л єси́, вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["По́двигом до́брим подвиза́яся, о́тче Зоси́мо, тече́ніє соверши́л єси́. Ті́мже і преходя́ от ві́ка сего́ преле́стнаго, рек, я́ко в наде́жді умира́єши, восприя́л єси́ віне́ць пра́вди, єго́же угото́ва Бог лю́б'ящим Єго́. Ми же, упова́юще на предста́тельство твоє́ о нас грі́шних ко Го́споду, вопіє́м ті:","Ра́дуйся, тече́ніє житія́ земна́го до́брі соверши́вий;","ра́дуйся, обітова́нная Бо́жия непрело́жні получи́вий.","Ра́дуйся, я́ко благоче́стія лампа́ду возже́гл єси́;","ра́дуйся, чистоти́ ангелоподо́бния побо́рниче.","Ра́дуйся, богому́дрими писа́нії твої́ми нас грі́шних назида́яй;","ра́дуйся, благода́тію моли́тв твої́х нас утіша́яй і увеселя́яй.","Ра́дуйся, о́бразе благи́й, і́ночествующим от Бо́га дарова́нний;","ра́дуйся, всім призива́ющим тя моли́твенниче непреста́нний.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 13","ps":["О преподо́бне о́тче Зоси́мо, ни́ні предстоя́й у Престо́ла Бо́жия, моли́ся за нас, грі́шних і недосто́йних чад твої́х, да моли́твами твої́ми ізба́вльшеся от страсте́й дия́вольських, вою́ющих на ду́ші на́ша, сподо́бимся неосужде́нно предста́ти пред Го́сподем і в невече́рнім дні Ца́рствія Єго́ взива́ти: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом сви́ше предуста́влен бисть, преподо́бне о́тче Зоси́мо, на служе́ніє Бо́гу, єгда́, єще́ во чре́ві ті су́щу, оте́ць твой в нощі́ на моли́тві усли́ша глас: си́на, і́же ті роди́тися і́мать, не учи́ мирськи́м нау́кам, но зако́ну Бо́жию то́кмо. Ті́мже, восхваля́юще тя, зове́м:","Ра́дуйся, уго́дниче Бо́жий предизбра́нний;","ра́дуйся, моли́твенниче і засту́пниче, от Бо́га нам дарова́нний.","Ра́дуйся, я́ко житіє́м оте́чеським внима́л єси́;","ра́дуйся, я́ко ду́шу свою́ сло́вом Бо́жиїм пита́л єси́.","Ра́дуйся, сокро́вище ви́шніх разумі́ній;","ра́дуйся, научи́вийся ісполне́нію Боже́ственних велі́ній.","Ра́дуйся, у пеще́р преподо́бнаго Авраа́мія Смоле́нськаго воспита́нний;","ра́дуйся, послуша́нія і моли́тви ді́лателю неуста́нний.","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Кондак 1","ps":["Ізбра́нному сви́ше на по́двиги і́ночества преподо́бному отцю́ на́шему Зоси́мі похва́льноє прино́сим пі́ніє. Ти же, преподо́бне о́тче, предста́тельствуй у Престо́ла Бо́жия за нас, многогрі́шних чад твої́х, да зове́м ті:","Ра́дуйся, преподо́бне о́тче Зоси́мо, благоче́стія подви́жниче."]},{"h":"Молитва","ps":["О вели́кий ста́рче, преподо́бне о́тче наш Зоси́мо! Кто ізглаго́леть по́двиги твоя́: безмо́лвіє, бді́ніє, моли́тву непреста́нную, скорбе́й терпі́ніє, сле́зи покая́нія і всіх проще́ніє, во́лі Бо́жієй всеці́лоє преда́ніє? Ти от ю́ности жизнь свою́ Христу́ посвяти́л єси́, імі́ніє разда́в, во оби́тель пусти́нную всели́лся єси́. Мно́гим ді́вам, Бо́гу уневе́стившимся, па́че отця́ ти бил єси́, духо́вно їх окормля́я і ко спасе́нію наставля́я. І ни́ні мо́лим тя, святи́й уго́дниче Христо́в, ми недосто́йнії: бу́ди нам помо́щник і засту́пник, оби́телі же, тобо́ю основа́нней, утвержде́ніє і покро́в; научи́ нас во́лю Бо́жию твори́ти, оби́ди проща́ти, ско́рби і болі́зні благоду́шно терпі́ти, да сподо́бимся і ми моли́твами твої́ми в ми́рі, любві́ і покая́нії земни́й путь наш соверши́ти і Ца́рствія Небе́снаго дости́гнути, іді́же ти со всі́ми святи́ми воспіва́єши непреста́нно Бо́га во Святі́й Тро́йці сла́вимаго, Отця́, і Си́на, і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Любо́вію Христо́вою уязви́лся єси́, преподо́бне, вся кра́сная ми́ра отри́нув, по́двигом безмо́лвія подвиза́вся, доброді́телі Боже́ственния стяжа́л єси́; прему́дрости Бо́жия прича́стниче, о́тче наш Зоси́мо, моли́ Христа́ Бо́га і Пречи́стую Ді́ву Богоро́дицю спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 6","ps":["Ізбра́нниче Бо́жий і ста́рче прему́дрий, наста́вниче наш Зоси́мо, от ю́ности по́стничеською стезе́ю ше́дий, во оде́жду кро́тости і терпі́нія обле́клся єси́, ті́мже дар Свята́го Ду́ха улучи́в, мно́гіє ду́ші Христу́ уневе́стил єси́. Ни́ні в со́нмі преподо́бних на Небесі́х лику́єши, моля́ся непреста́нно о чту́щих святу́ю па́м'ять твою́."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Зоси́мо, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]}];
export default D;
